- `src/runtime/typed_callback.zig`
- `specs/idl/streams.idl` - WritableStream interface

Create error mapping from libcurl CURLcode values to WHATWG Fetch NetworkError types.

## Background
The WHATWG Fetch spec defines specific network error types. Libcurl has its own error codes. We need a mapping layer that translates curl errors to spec-compliant errors.

## File Location
`src/fetch/network/curl_error.zig`

## Error Mapping Table

| Libcurl Error | NetworkError | Fetch Spec Context |
|---------------|--------------|-------------------|
| CURLE_COULDNT_RESOLVE_HOST | DnsResolutionFailed | DNS lookup failed |
| CURLE_COULDNT_RESOLVE_PROXY | DnsResolutionFailed | Proxy DNS failed |
| CURLE_COULDNT_CONNECT | ConnectionRefused | TCP connection failed |
| CURLE_OPERATION_TIMEDOUT | RequestTimeout | Overall timeout |
| CURLE_SSL_CONNECT_ERROR | SslHandshakeFailed | TLS handshake failed |
| CURLE_SSL_ENGINE_NOTFOUND | SslHandshakeFailed | TLS engine error |
| CURLE_SSL_ENGINE_SETFAILED | SslHandshakeFailed | TLS engine error |
| CURLE_SSL_CERTPROBLEM | SslCertificateError | Client cert issue |
| CURLE_SSL_CACERT | SslCertificateError | CA verification failed |
| CURLE_PEER_FAILED_VERIFICATION | SslCertificateError | Cert verification failed |
| CURLE_SSL_ISSUER_ERROR | SslCertificateError | Issuer check failed |
| CURLE_SSL_PINNEDPUBKEYNOTMATCH | SslCertificateError | Pin mismatch |
| CURLE_TOO_MANY_REDIRECTS | TooManyRedirects | Redirect limit |
| CURLE_URL_MALFORMAT | InvalidUrl | Bad URL |
| CURLE_BAD_FUNCTION_ARGUMENT | InvalidUrl | Bad argument |
| CURLE_ABORTED_BY_CALLBACK | Aborted | User abort |
| CURLE_RECV_ERROR | ConnectionReset | Receive failed |
| CURLE_SEND_ERROR | ConnectionReset | Send failed |
| CURLE_GOT_NOTHING | ConnectionReset | Empty response |
| CURLE_UNSUPPORTED_PROTOCOL | ProtocolError | Unknown protocol |
| CURLE_HTTP_RETURNED_ERROR | ProtocolError | HTTP error |
| CURLE_WEIRD_SERVER_REPLY | ProtocolError | Malformed response |
| CURLE_OUT_OF_MEMORY | OutOfMemory | Allocation failed |
| (all others) | Unknown | Catch-all |

## Implementation

```zig
//! Libcurl Error Code Mapping
//!
//! Maps libcurl CURLcode values to WHATWG Fetch NetworkError types.
//! Ensures spec-compliant error reporting for network failures.
//!
//! Spec: https://fetch.spec.whatwg.org/#concept-network-error

const std = @import("std");
const curl = @import("curl_ffi.zig");
const backend = @import("backend.zig");
const NetworkError = backend.NetworkError;

/// Map a libcurl error code to a NetworkError.
///
/// This mapping follows the WHATWG Fetch spec's network error categories:
/// - DNS resolution failures
/// - Connection failures (refused, timeout, reset)
/// - TLS/SSL failures (handshake, certificate)
/// - Protocol errors
/// - Abort
pub fn mapCurlError(code: curl.CURLcode) NetworkError {
    return switch (code) {
        // Success - should not be called with CURLE_OK
        curl.CURLE_OK => unreachable,

        // DNS Resolution Failures
        // Spec: "DNS error" in network error creation
        curl.c.CURLE_COULDNT_RESOLVE_PROXY,
        curl.c.CURLE_COULDNT_RESOLVE_HOST,
        => .DnsResolutionFailed,

        // Connection Refused
        // Spec: Connection error during TCP establishment
        curl.c.CURLE_COULDNT_CONNECT,
        => .ConnectionRefused,

        // Timeout
        // Spec: "timed out" in network error
        curl.c.CURLE_OPERATION_TIMEDOUT,
        => .RequestTimeout,

        // TLS Handshake Failures
        // Spec: "TLS negotiation" error
        curl.c.CURLE_SSL_CONNECT_ERROR,
        curl.c.CURLE_SSL_ENGINE_NOTFOUND,
        curl.c.CURLE_SSL_ENGINE_SETFAILED,
        => .SslHandshakeFailed,

        // TLS Certificate Errors
        // Spec: "bad TLS certificate" error
        curl.c.CURLE_SSL_CERTPROBLEM,
        curl.c.CURLE_SSL_CACERT,
        curl.c.CURLE_PEER_FAILED_VERIFICATION,
        curl.c.CURLE_SSL_ISSUER_ERROR,
        curl.c.CURLE_SSL_PINNEDPUBKEYNOTMATCH,
        => .SslCertificateError,

        // Redirect Limit
        // Spec: Handled by Fetch algorithm, but curl can hit this
        curl.c.CURLE_TOO_MANY_REDIRECTS,
        => .TooManyRedirects,

        // Invalid URL
        // Spec: URL parsing failure
        curl.c.CURLE_URL_MALFORMAT,
        curl.c.CURLE_BAD_FUNCTION_ARGUMENT,
        => .InvalidUrl,

        // Aborted by User
        // Spec: "aborted" flag on response
        curl.c.CURLE_ABORTED_BY_CALLBACK,
        => .Aborted,

        // Connection Reset / Receive Errors
        // Spec: Connection terminated unexpectedly
        curl.c.CURLE_RECV_ERROR,
        curl.c.CURLE_SEND_ERROR,
        curl.c.CURLE_GOT_NOTHING,
        => .ConnectionReset,

        // Protocol Errors
        // Spec: Malformed HTTP response
        curl.c.CURLE_UNSUPPORTED_PROTOCOL,
        curl.c.CURLE_HTTP_RETURNED_ERROR,
        curl.c.CURLE_WEIRD_SERVER_REPLY,
        => .ProtocolError,

        // Memory Errors
        curl.c.CURLE_OUT_OF_MEMORY,
        => .OutOfMemory,

        // All other errors map to Unknown
        else => .Unknown,
    };
}

/// Get a human-readable error message for a curl error code.
pub fn getErrorMessage(code: curl.CURLcode) []const u8 {
    const msg = curl.curl_easy_strerror(code);
    return std.mem.span(msg);
}

/// Check if an error is retryable (transient network issue).
///
/// Returns true for errors that might succeed on retry:
/// - DNS resolution (might be temporary)
/// - Connection timeout (server might be temporarily overloaded)
/// - Connection reset (might be a transient issue)
pub fn isRetryable(err: NetworkError) bool {
    return switch (err) {
        .DnsResolutionFailed,
        .ConnectionTimeout,
        .RequestTimeout,
        .ConnectionReset,
        .NetworkUnreachable,
        .HostUnreachable,
        => true,

        .ConnectionRefused,
        .SslHandshakeFailed,
        .SslCertificateError,
        .TooManyRedirects,
        .InvalidUrl,
        .Aborted,
        .ProtocolError,
        .OutOfMemory,
        .Unknown,
        => false,
    };
}

/// Check if an error is related to TLS/SSL.
pub fn isTlsError(err: NetworkError) bool {
    return switch (err) {
        .SslHandshakeFailed,
        .SslCertificateError,
        => true,
        else => false,
    };
}

// ============================================================================
// Tests
// ============================================================================

test "mapCurlError - DNS errors" {
    try std.testing.expectEqual(
        NetworkError.DnsResolutionFailed,
        mapCurlError(curl.c.CURLE_COULDNT_RESOLVE_HOST),
    );
}

test "mapCurlError - connection errors" {
    try std.testing.expectEqual(
        NetworkError.ConnectionRefused,
        mapCurlError(curl.c.CURLE_COULDNT_CONNECT),
    );
}

test "mapCurlError - TLS errors" {
    try std.testing.expectEqual(
        NetworkError.SslHandshakeFailed,
        mapCurlError(curl.c.CURLE_SSL_CONNECT_ERROR),
    );
    try std.testing.expectEqual(
        NetworkError.SslCertificateError,
        mapCurlError(curl.c.CURLE_PEER_FAILED_VERIFICATION),
    );
}

test "mapCurlError - abort" {
    try std.testing.expectEqual(
        NetworkError.Aborted,
        mapCurlError(curl.c.CURLE_ABORTED_BY_CALLBACK),
    );
}

test "isRetryable" {
    try std.testing.expect(isRetryable(.DnsResolutionFailed));
    try std.testing.expect(isRetryable(.RequestTimeout));
    try std.testing.expect(!isRetryable(.SslCertificateError));
    try std.testing.expect(!isRetryable(.Aborted));
}

test "isTlsError" {
    try std.testing.expect(isTlsError(.SslHandshakeFailed));
    try std.testing.expect(isTlsError(.SslCertificateError));
    try std.testing.expect(!isTlsError(.DnsResolutionFailed));
}

test "getErrorMessage" {
    const msg = getErrorMessage(curl.c.CURLE_COULDNT_CONNECT);
    try std.testing.expect(msg.len > 0);
}
```

## Acceptance Criteria
- [ ] All curl errors map to appropriate NetworkError
- [ ] mapCurlError() handles all documented CURLcode values
- [ ] getErrorMessage() returns human-readable strings
- [ ] isRetryable() correctly identifies transient errors
- [ ] isTlsError() correctly identifies TLS-related errors
- [ ] All tests pass
- [ ] Error mapping documented with spec references

