## Required Changes

### 1. Update InternalState to use GlobalHandle

```zig
const GlobalHandle = @import\("global_handles.zig"\).GlobalHandle\;

pub const InternalState = struct {
    /// [[startAlgorithm]]: Global handle to start callback function
    start_algorithm: ?GlobalHandle = null,

    /// [[writeAlgorithm]]: Global handle to write callback function  
    write_algorithm: ?GlobalHandle = null,

    /// [[closeAlgorithm]]: Global handle to close callback function
    close_algorithm: ?GlobalHandle = null,

    /// [[abortAlgorithm]]: Global handle to abort callback function
    abort_algorithm: ?GlobalHandle = null,

    /// [[strategySizeAlgorithm]]: Global handle to size function
    strategy_size_algorithm: ?GlobalHandle = null,

    // ... rest unchanged
}\;
```

### 2. Update Callback Extraction \(WritableStream.zig:652-666\)

```zig
// Convert Local callback to Global before storing
if \(underlyingSinkDict.start\) \|start_local\| {
    const start_global = GlobalHandle.create\(isolate, @ptrCast\(@alignCast\(@constCast\(start_local\)\)\)\)\;
    start_algorithm = start_global\;
}
if \(underlyingSinkDict.write\) \|write_local\| {
    write_algorithm = GlobalHandle.create\(isolate, @ptrCast\(@alignCast\(@constCast\(write_local\)\)\)\)\;
}
// ... same for close, abort, strategy_size
```

### 3. Update Controller Setup \(WritableStream.zig:714-731\)

```zig
controller_internal.* = .{
    // ...
    .start_algorithm = startAlgorithm,  // Now GlobalHandle
    .write_algorithm = writeAlgorithm,
    .close_algorithm = closeAlgorithm,
    .abort_algorithm = abortAlgorithm,
    .strategy_size_algorithm = strategySizeAlgorithm,
    // ...
}\;
```

### 4. Fix invokePendingStartCallback \(WritableStream.zig:914-1088\)

```zig
pub fn invokePendingStartCallback\(
    instance: *runtime.Instance,
    controller_v8: *anyopaque,
    v8_isolate: *anyopaque,
    v8_context: *anyopaque,
\) void {
    // ...

    const start_algo = controller_internal.start_algorithm orelse {
        onWritableStartFulfilledImmediate\(controller_internal\)\;
        return\;
    }\;

    // Get Local from Global \(safe - we're in a HandleScope\)
    const local_value = start_algo.get\(isolate\) orelse {
        // Global was disposed or became empty
        controller_internal.start_algorithm = null\;
        onWritableStartFulfilledImmediate\(controller_internal\)\;
        return\;
    }\;

    if \(\!v8.v8_Value_IsFunction\(local_value\)\) {
        controller_internal.start_algorithm.?.dispose\(\)\;
        controller_internal.start_algorithm = null\;
        onWritableStartFulfilledImmediate\(controller_internal\)\;
        return\;
    }

    // Call the function
    const func: *v8.Function = @ptrCast\(local_value\)\;
    // ... rest of invocation logic

    // Clear after use
    start_algo.dispose\(\)\;
    controller_internal.start_algorithm = null\;
}
```

### 5. Add Cleanup in Controller deinit

```zig
pub fn deinit\(self: *InternalState, allocator: std.mem.Allocator\) void {
    // Dispose all V8 Global handles
    if \(self.start_algorithm\) \|handle\| {
        handle.dispose\(\)\;
    }
    if \(self.write_algorithm\) \|handle\| {
        handle.dispose\(\)\;
    }
    if \(self.close_algorithm\) \|handle\| {
        handle.dispose\(\)\;
    }
    if \(self.abort_algorithm\) \|handle\| {
        handle.dispose\(\)\;
    }
    if \(self.strategy_size_algorithm\) \|handle\| {
        handle.dispose\(\)\;
    }

    // Clean up queue
    self.queue.deinit\(allocator\)\;
    allocator.destroy\(self\)\;
}
```

