### 2. Create FrozenContextManager (frozen_context_manager.zig)
```zig
const std = @import("std");
const v8 = @import("ffi.zig");
const runtime = @import("../../runtime.zig");

pub const FrozenContext = struct {
    /// The V8 context (retained Global handle)
    v8_ctx: *v8.Context,

    /// Runtime context data
    runtime_ctx: runtime.ContextData,

    /// Event loop (frozen state)
    event_loop: *V8EventLoop,

    /// Frozen task queue (tasks captured at freeze time)
    frozen_tasks: std.ArrayList(Task),

    /// Frozen timers (timer IDs and remaining times)
    frozen_timers: std.ArrayList(FrozenTimer),

    /// DOM state handle (for detachment/reattachment)
    dom_state: ?*anyopaque,

    /// Timestamp when frozen
    frozen_at: i64,

    /// URL at time of freeze (for cache key)
    url: []const u8,

    /// Navigation ID for matching
    navigation_id: u64,
};

pub const FrozenTimer = struct {
    timer_id: u32,
    remaining_ms: i64,
    callback: *anyopaque,
    is_interval: bool,
    interval_ms: ?i64,
};

pub const FrozenContextManager = struct {
    allocator: std.mem.Allocator,
    frozen_contexts: std.AutoHashMap(u64, *FrozenContext),
    max_frozen_contexts: usize,
    max_freeze_duration_ms: i64,

    pub fn init(allocator: std.mem.Allocator) FrozenContextManager {
        return .{
            .allocator = allocator,
            .frozen_contexts = std.AutoHashMap(u64, *FrozenContext).init(allocator),
            .max_frozen_contexts = 10,  // Configurable limit
            .max_freeze_duration_ms = 10 * 60 * 1000,  // 10 minutes default
        };
    }

    pub fn deinit(self: *FrozenContextManager) void {
        var iter = self.frozen_contexts.valueIterator();
        while (iter.next()) |frozen| {
            self.disposeFrozenContext(frozen.*);
        }
        self.frozen_contexts.deinit();
    }

    /// Freeze a context for bfcache
    pub fn freeze(self: *FrozenContextManager, v8_ctx: *v8.Context, navigation_id: u64) !void {
        // Evict oldest if at capacity
        if (self.frozen_contexts.count() >= self.max_frozen_contexts) {
            try self.evictOldest();
        }

        const frozen = try self.allocator.create(FrozenContext);
        errdefer self.allocator.destroy(frozen);

        // 1. Get context entry from active contexts
        const ctx_entry = context_manager.getContextEntry(v8_ctx) orelse 
            return error.ContextNotFound;

        // 2. Freeze event loop (suspends timers and tasks)
        if (ctx_entry.event_loop) |ev_loop| {
            try ev_loop.freeze();
            frozen.frozen_tasks = ev_loop.drainTasks();
            frozen.frozen_timers = try ev_loop.captureTimers(self.allocator);
        }

        // 3. Prepare DOM for detachment
        frozen.dom_state = try detachDOM(v8_ctx);

        // 4. Store frozen state
        frozen.* = .{
            .v8_ctx = v8_ctx,
            .runtime_ctx = ctx_entry.runtime_ctx,
            .event_loop = ctx_entry.event_loop.?,
            .frozen_tasks = frozen.frozen_tasks,
            .frozen_timers = frozen.frozen_timers,
            .dom_state = frozen.dom_state,
            .frozen_at = std.time.milliTimestamp(),
            .url = try self.allocator.dupe(u8, ctx_entry.url),
            .navigation_id = navigation_id,
        };

        try self.frozen_contexts.put(navigation_id, frozen);

        // 5. Remove from active contexts (but DON'T deinit!)
        context_manager.removeWithoutDeinit(v8_ctx);
    }

    /// Thaw a context from bfcache
    pub fn thaw(self: *FrozenContextManager, navigation_id: u64) !*v8.Context {
        const frozen = self.frozen_contexts.get(navigation_id) orelse
            return error.NotFrozen;

        // 1. Re-enter V8 context
        v8.v8_Context_Enter(frozen.v8_ctx);

        // 2. Reattach DOM
        try reattachDOM(frozen.v8_ctx, frozen.dom_state);

        // 3. Restore timers with adjusted remaining times
        const now = std.time.milliTimestamp();
        const elapsed = now - frozen.frozen_at;
        try frozen.event_loop.restoreTimers(frozen.frozen_timers, elapsed);

        // 4. Restore task queue
        try frozen.event_loop.restoreTasks(frozen.frozen_tasks);

        // 5. Resume event loop
        try frozen.event_loop.thaw();

        // 6. Re-add to active contexts
        try context_manager.restoreContext(frozen.v8_ctx, frozen.runtime_ctx, frozen.event_loop);

        // 7. Remove from frozen storage
        _ = self.frozen_contexts.remove(navigation_id);

        // 8. Cleanup frozen state (but not the context!)
        self.allocator.free(frozen.url);
        self.allocator.destroy(frozen);

        return frozen.v8_ctx;
    }

    /// Check if navigation can be restored from bfcache
    pub fn canRestore(self: *FrozenContextManager, navigation_id: u64) bool {
        if (self.frozen_contexts.get(navigation_id)) |frozen| {
            const now = std.time.milliTimestamp();
            const age = now - frozen.frozen_at;
            return age < self.max_freeze_duration_ms;
        }
        return false;
    }

    fn evictOldest(self: *FrozenContextManager) !void {
        var oldest_id: ?u64 = null;
        var oldest_time: i64 = std.math.maxInt(i64);

        var iter = self.frozen_contexts.iterator();
        while (iter.next()) |entry| {
            if (entry.value_ptr.*.frozen_at < oldest_time) {
                oldest_time = entry.value_ptr.*.frozen_at;
                oldest_id = entry.key_ptr.*;
            }
        }

        if (oldest_id) |id| {
            if (self.frozen_contexts.fetchRemove(id)) |kv| {
                self.disposeFrozenContext(kv.value);
            }
        }
    }

    fn disposeFrozenContext(self: *FrozenContextManager, frozen: *FrozenContext) void {
        // Actually destroy the context now
        frozen.event_loop.deinit();
        frozen.runtime_ctx.deinit();
        v8.v8_Context_Dispose(frozen.v8_ctx);
        self.allocator.free(frozen.url);
        frozen.frozen_tasks.deinit();
        frozen.frozen_timers.deinit();
        self.allocator.destroy(frozen);
    }
};
```

### 3. Add Event Loop Freeze/Thaw (event_loop.zig)
```zig
pub const V8EventLoop = struct {
    // ... existing fields ...

    /// Whether this event loop is frozen
    frozen: bool = false,

    /// Tasks captured at freeze time (for restoration)
    frozen_tasks_backup: std.ArrayList(Task),

    /// Freeze the event loop - suspend all timers and task processing
    pub fn freeze(self: *Self) !void {
        if (self.frozen) return error.AlreadyFrozen;

        // 1. Mark as frozen (stops runOnce from processing)
        self.frozen = true;

        // 2. Suspend all timers
        if (self.timer_manager) |mgr| {
            try mgr.suspendAll();
        }
    }

    /// Thaw the event loop - resume timers and task processing
    pub fn thaw(self: *Self) !void {
        if (!self.frozen) return error.NotFrozen;

        // 1. Resume all timers
        if (self.timer_manager) |mgr| {
            try mgr.resumeAll();
        }

        // 2. Unfreeze (allows runOnce to process again)
        self.frozen = false;
    }

    /// Drain all pending tasks (for freeze)
    pub fn drainTasks(self: *Self) std.ArrayList(Task) {
        const tasks = self.tasks;
        self.tasks = std.ArrayList(Task).init(self.allocator);
        return tasks;
    }

    /// Restore tasks (for thaw)
    pub fn restoreTasks(self: *Self, tasks: std.ArrayList(Task)) !void {
        try self.tasks.appendSlice(tasks.items);
    }

    /// Capture timer state for freeze
    pub fn captureTimers(self: *Self, allocator: Allocator) !std.ArrayList(FrozenTimer) {
        if (self.timer_manager) |mgr| {
            return mgr.captureState(allocator);
        }
        return std.ArrayList(FrozenTimer).init(allocator);
    }

    /// Restore timers with elapsed time adjustment
    pub fn restoreTimers(self: *Self, timers: std.ArrayList(FrozenTimer), elapsed_ms: i64) !void {
        if (self.timer_manager) |mgr| {
            try mgr.restoreState(timers, elapsed_ms);
        }
    }

