### 4. Add Timer Manager Suspend/Resume (libuv_timer.zig or timer_manager.zig)
```zig
pub const TimerManager = struct {
    // ... existing fields ...

    suspended: bool = false,
    suspended_timers: std.ArrayList(SuspendedTimerState),

    pub fn suspendAll(self: *Self) !void {
        if (self.suspended) return;

        self.suspended_timers = std.ArrayList(SuspendedTimerState).init(self.allocator);

        // Iterate all active timers
        var iter = self.timers.iterator();
        while (iter.next()) |entry| {
            const timer = entry.value_ptr.*;

            // Calculate remaining time
            const remaining = timer.getRemaining();

            // Stop the timer
            timer.stop();

            // Store state for restoration
            try self.suspended_timers.append(.{
                .timer_id = entry.key_ptr.*,
                .remaining_ms = remaining,
                .callback = timer.callback,
                .repeat = timer.repeat,
            });
        }

        self.suspended = true;
    }

    pub fn resumeAll(self: *Self) !void {
        if (!self.suspended) return;

        // Restore all timers with their remaining times
        for (self.suspended_timers.items) |state| {
            const timer = self.timers.get(state.timer_id) orelse continue;
            timer.start(state.remaining_ms, if (state.repeat) state.remaining_ms else 0);
        }

        self.suspended_timers.deinit();
        self.suspended = false;
    }

    pub fn captureState(self: *Self, allocator: Allocator) !std.ArrayList(FrozenTimer) {
        var result = std.ArrayList(FrozenTimer).init(allocator);

        var iter = self.timers.iterator();
        while (iter.next()) |entry| {
            try result.append(.{
                .timer_id = entry.key_ptr.*,
                .remaining_ms = entry.value_ptr.*.getRemaining(),
                .callback = entry.value_ptr.*.callback,
                .is_interval = entry.value_ptr.*.repeat,
                .interval_ms = if (entry.value_ptr.*.repeat) entry.value_ptr.*.interval else null,
            });
        }

        return result;
    }
};
