### 5. DOM Detachment/Reattachment Helpers
```zig
/// Detach DOM from window object to prevent memory leaks during freeze
fn detachDOM(v8_ctx: *v8.Context) !?*anyopaque {
    // Get window object
    const global = v8.v8_Context_Global(v8_ctx) orelse return null;

    // Get document property
    const document_key = v8.v8_String_NewFromUtf8(..., "document");
    const document = v8.v8_Object_Get(global, v8_ctx, document_key);

    if (document) |doc| {
        // Store reference for reattachment
        const dom_state = try allocator.create(DOMState);
        dom_state.document = doc;

        // Disconnect MutationObservers
        try disconnectObservers(doc);

        // Pause animations
        try pauseAnimations(doc);

        // Suspend media elements
        try suspendMedia(doc);

        return @ptrCast(dom_state);
    }

    return null;
}

/// Reattach DOM after thaw
fn reattachDOM(v8_ctx: *v8.Context, dom_state: ?*anyopaque) !void {
    if (dom_state) |state| {
        const ds: *DOMState = @ptrCast(@alignCast(state));

        // Reconnect MutationObservers
        try reconnectObservers(ds.document);

        // Resume animations
        try resumeAnimations(ds.document);

        // Resume media elements
        try resumeMedia(ds.document);
    }
}
```

