pub const JSValue = union\(enum\) {
    undefined: void,
    null: void,
    boolean: bool,
    number: f64,
    string: StringValue,
    handle: EngineHandle,
    instance: *Instance,  // Now typed\!

    /// Create JSValue from runtime Instance
    pub fn fromInstance\(inst: *Instance\) JSValue {
        return .{ .instance = inst }\;
    }

    /// Extract Instance if this JSValue holds one
    pub fn toInstance\(self: JSValue\) ?*Instance {
        return if \(self == .instance\) self.instance else null\;
    }

    /// Type-safe instance extraction with interface type
    pub fn toTypedInstance\(self: JSValue, comptime T: type\) ?*T {
        if \(self.toInstance\(\)\) \|inst\| {
            return inst.getState\(T\)\;
        }
        return null\;
    }
}\;
```

