const std = @import("std");
const ffi = @import("ffi.zig");

/// RAII wrapper for V8 Global<Value>
/// Automatically disposes handle when scope exits
pub const V8Value = struct {
    ptr: *ffi.Value,

    pub fn wrap(ptr: *ffi.Value) V8Value {
        return .{ .ptr = ptr };
    }

    pub fn wrapOptional(ptr: ?*ffi.Value) ?V8Value {
        if (ptr) |p| return wrap(p);
        return null;
    }

    pub fn deinit(self: *V8Value) void {
        ffi.v8_Value_Dispose(self.ptr);
        self.* = undefined;
    }

    /// Get raw pointer (for FFI calls)
    pub fn raw(self: V8Value) *ffi.Value {
        return self.ptr;
    }

    /// Transfer ownership - caller takes responsibility
    pub fn release(self: *V8Value) *ffi.Value {
        const ptr = self.ptr;
        self.* = undefined;
        return ptr;
    }
};

/// RAII wrapper for V8 Global<Object>
pub const V8Object = struct {
    ptr: *ffi.Object,

    pub fn wrap(ptr: *ffi.Object) V8Object {
        return .{ .ptr = ptr };
    }

    pub fn deinit(self: *V8Object) void {
        ffi.v8_Object_Dispose(self.ptr);
        self.* = undefined;
    }

    pub fn raw(self: V8Object) *ffi.Object {
        return self.ptr;
    }

    pub fn release(self: *V8Object) *ffi.Object {
        const ptr = self.ptr;
        self.* = undefined;
        return ptr;
    }

    /// Get property with automatic handle management
    pub fn get(self: V8Object, context: *ffi.Context, key: V8Value) \!V8Value {
        const result = ffi.v8_Object_Get(self.ptr, context, key.ptr) orelse
            return error.PropertyAccessFailed;
        return V8Value.wrap(result);
    }

    /// Set property
    pub fn set(self: V8Object, context: *ffi.Context, key: V8Value, value: V8Value) \!void {
        if (\!ffi.v8_Object_Set(self.ptr, context, key.ptr, value.ptr)) {
            return error.PropertySetFailed;
        }
    }
};

/// RAII wrapper for V8 Global<String>
pub const V8String = struct {
    ptr: *ffi.String,

    pub fn wrap(ptr: *ffi.String) V8String {
        return .{ .ptr = ptr };
    }

    pub fn fromUtf8(isolate: *ffi.Isolate, bytes: []const u8) \!V8String {
        const ptr = ffi.v8_String_NewFromUtf8(
            isolate,
            bytes.ptr,
            @intCast(bytes.len),
        ) orelse return error.StringCreationFailed;
        return wrap(ptr);
    }

    pub fn deinit(self: *V8String) void {
        ffi.v8_String_Dispose(self.ptr);
        self.* = undefined;
    }

    pub fn raw(self: V8String) *ffi.String {
        return self.ptr;
    }

    /// Convert to Zig string (allocates)
    pub fn toSlice(self: V8String, allocator: std.mem.Allocator, isolate: *ffi.Isolate) \![]const u8 {
        const len = ffi.v8_String_Utf8Length(self.ptr, isolate);
        const buf = try allocator.alloc(u8, @intCast(len));
        errdefer allocator.free(buf);

        const written = ffi.v8_String_WriteUtf8(self.ptr, isolate, buf.ptr, @intCast(len));
        return buf[0..@intCast(written)];
    }
};

/// RAII wrapper for V8 Global<Function>
pub const V8Function = struct {
    ptr: *ffi.Function,

    pub fn wrap(ptr: *ffi.Function) V8Function {
        return .{ .ptr = ptr };
    }

    pub fn deinit(self: *V8Function) void {
        ffi.v8_Function_Dispose(self.ptr);
        self.* = undefined;
    }

    pub fn raw(self: V8Function) *ffi.Function {
        return self.ptr;
    }

    /// Call function with automatic handle management
    pub fn call(
        self: V8Function,
        context: *ffi.Context,
        receiver: V8Value,
        args: []const V8Value,
    ) \!V8Value {
        // Convert to raw pointers for FFI
        var raw_args = try std.heap.page_allocator.alloc(*ffi.Value, args.len);
        defer std.heap.page_allocator.free(raw_args);

        for (args, 0..) |arg, i| {
            raw_args[i] = arg.ptr;
        }

        const result = ffi.v8_Function_Call(
            self.ptr,
            context,
            receiver.ptr,
            raw_args.ptr,
            @intCast(args.len),
        ) orelse return error.FunctionCallFailed;

        return V8Value.wrap(result);
    }
};

/// RAII wrapper for V8 Global<Promise>
pub const V8Promise = struct {
    ptr: *ffi.Promise,

    pub fn wrap(ptr: *ffi.Promise) V8Promise {
        return .{ .ptr = ptr };
    }

    pub fn deinit(self: *V8Promise) void {
        ffi.v8_Promise_Dispose(self.ptr);
        self.* = undefined;
    }

    pub fn raw(self: V8Promise) *ffi.Promise {
        return self.ptr;
    }

    pub fn then(
        self: V8Promise,
        context: *ffi.Context,
        on_fulfilled: V8Function,
    ) \!V8Promise {
        const result = ffi.v8_Promise_Then(
            self.ptr,
            context,
            on_fulfilled.ptr,
        ) orelse return error.PromiseThenFailed;
        return wrap(result);
    }
};

/// RAII wrapper for V8 Global<Context>
pub const V8Context = struct {
    ptr: *ffi.Context,

    pub fn wrap(ptr: *ffi.Context) V8Context {
        return .{ .ptr = ptr };
    }

    pub fn deinit(self: *V8Context) void {
        ffi.v8_Context_Dispose(self.ptr);
        self.* = undefined;
    }

    pub fn raw(self: V8Context) *ffi.Context {
        return self.ptr;
    }

    pub fn enter(self: V8Context) void {
        ffi.v8_Context_Enter(self.ptr);
    }

    pub fn exit(self: V8Context) void {
        ffi.v8_Context_Exit(self.ptr);
    }

    pub fn global(self: V8Context) \!V8Object {
        const g = ffi.v8_Context_Global(self.ptr) orelse
            return error.GlobalAccessFailed;
        return V8Object.wrap(g);
    }
};
```

### 2. HandleScope RAII Wrapper
```zig
/// RAII wrapper for V8 HandleScope
/// Ensures proper scope nesting
pub const HandleScope = struct {
    ptr: *anyopaque,
    isolate: *ffi.Isolate,

    pub fn init(isolate: *ffi.Isolate) HandleScope {
        return .{
            .ptr = ffi.v8_HandleScope_New(isolate),
            .isolate = isolate,
        };
    }

    pub fn deinit(self: *HandleScope) void {
        ffi.v8_HandleScope_Dispose(self.ptr, self.isolate);
        self.* = undefined;
    }
};

/// Scoped handle scope - use with block
pub fn withHandleScope(isolate: *ffi.Isolate, comptime func: fn (*ffi.Isolate) anyerror\!void) \!void {
    var scope = HandleScope.init(isolate);
    defer scope.deinit();

    try func(isolate);
}
```

### 3. Auto-Managed Handle List
```zig
/// Manages multiple handles with automatic cleanup
pub const HandleBag = struct {
    allocator: std.mem.Allocator,
    values: std.ArrayList(*ffi.Value),
    objects: std.ArrayList(*ffi.Object),
    strings: std.ArrayList(*ffi.String),
    functions: std.ArrayList(*ffi.Function),

    pub fn init(allocator: std.mem.Allocator) HandleBag {
        return .{
            .allocator = allocator,
            .values = std.ArrayList(*ffi.Value).init(allocator),
            .objects = std.ArrayList(*ffi.Object).init(allocator),
            .strings = std.ArrayList(*ffi.String).init(allocator),
            .functions = std.ArrayList(*ffi.Function).init(allocator),
        };
    }

    pub fn deinit(self: *HandleBag) void {
        for (self.values.items) |v| ffi.v8_Value_Dispose(v);
        for (self.objects.items) |o| ffi.v8_Object_Dispose(o);
        for (self.strings.items) |s| ffi.v8_String_Dispose(s);
        for (self.functions.items) |f| ffi.v8_Function_Dispose(f);

        self.values.deinit();
        self.objects.deinit();
        self.strings.deinit();
        self.functions.deinit();
    }

    pub fn trackValue(self: *HandleBag, value: *ffi.Value) \!*ffi.Value {
        try self.values.append(value);
        return value;
    }

    pub fn trackObject(self: *HandleBag, object: *ffi.Object) \!*ffi.Object {
        try self.objects.append(object);
        return object;
    }

    pub fn trackString(self: *HandleBag, string: *ffi.String) \!*ffi.String {
        try self.strings.append(string);
        return string;
    }
};
```

