### 5. Compile-Time Ownership Tracking (Optional Enhancement)
```zig
/// Ownership state for compile-time tracking
pub const Ownership = enum {
    owned,      // We own this handle, must dispose
    borrowed,   // Someone else owns it, don't dispose
    released,   // Ownership transferred, don't dispose
};

pub fn OwnedHandle(comptime T: type) type {
    return struct {
        ptr: T,
        ownership: Ownership,

        const Self = @This();

        pub fn owned(ptr: T) Self {
            return .{ .ptr = ptr, .ownership = .owned };
        }

        pub fn borrowed(ptr: T) Self {
            return .{ .ptr = ptr, .ownership = .borrowed };
        }

        pub fn deinit(self: *Self) void {
            if (self.ownership == .owned) {
                // Dispose based on type
                disposeHandle(T, self.ptr);
            }
            self.ownership = .released;
        }

        pub fn release(self: *Self) T {
            std.debug.assert(self.ownership == .owned);
            self.ownership = .released;
            return self.ptr;
        }
    };
}
```

