`src/runtime/engines/v8/js_value.zig`

## Implementation

```zig
const std = @import\("std"\)\;
const v8 = @import\("ffi.zig"\)\;
const runtime = @import\("../../../runtime.zig"\)\;
const GlobalHandle = @import\("global_handles.zig"\).GlobalHandle\;

/// Type-safe representation of any JavaScript value
/// Replaces all *const anyopaque in V8 binding layer
pub const JSValue = union\(enum\) {
    /// JavaScript null
    null: void,

    /// JavaScript undefined
    undefined: void,

    /// V8 Global handle - persists across HandleScopes until disposed
    /// Safe to store in structs
    global: GlobalHandle,

    /// Zig runtime.Instance - NOT a V8 pointer\!
    /// Represents a WebIDL interface instance
    instance: *runtime.Instance,

    /// V8 Local handle - ONLY valid within current HandleScope
    /// WARNING: Do NOT store in structs - will become dangling\!
    local: LocalHandle,

    /// Boolean primitive \(optimization\)
    boolean: bool,

    /// Number primitive \(optimization\)
    number: f64,

    // === Type Checking ===

    pub fn isNullOrUndefined\(self: JSValue\) bool {
        return self == .null or self == .undefined\;
    }

    pub fn isNull\(self: JSValue\) bool {
        return self == .null\;
    }

    pub fn isUndefined\(self: JSValue\) bool {
        return self == .undefined\;
    }

    pub fn isInstance\(self: JSValue\) bool {
        return self == .instance\;
    }

    pub fn isCallable\(self: JSValue\) bool {
        return switch \(self\) {
            .global =\> \|g\| g.isFunction\(\),
            .local =\> \|l\| l.isFunction\(\),
            else =\> false,
        }\;
    }

    // === Conversion ===

    /// Convert to V8 Value for FFI calls
    pub fn toV8\(self: JSValue, isolate: *v8.Isolate\) ?*v8.Value {
        return switch \(self\) {
            .null =\> v8.v8_Null\(isolate\),
            .undefined =\> v8.v8_Undefined\(isolate\),
            .global =\> \|g\| g.get\(isolate\),
            .instance =\> \|i\| instanceToV8\(isolate, i\),
            .local =\> \|l\| l.raw,
            .boolean =\> \|b\| v8.v8_Boolean_New\(isolate, b\),
            .number =\> \|n\| v8.v8_Number_New\(isolate, n\),
        }\;
    }

    /// Extract as runtime.Instance \(returns null if not an instance\)
    pub fn asInstance\(self: JSValue\) ?*runtime.Instance {
        return if \(self == .instance\) self.instance else null\;
    }

    /// Extract as GlobalHandle \(returns null if not global\)
    pub fn asGlobal\(self: JSValue\) ?GlobalHandle {
        return if \(self == .global\) self.global else null\;
    }

    /// Convert Local to Global for storage \(REQUIRED before storing\!\)
    pub fn toGlobal\(self: JSValue, isolate: *v8.Isolate\) \!JSValue {
        return switch \(self\) {
            .local =\> \|l\| .{ .global = try l.toGlobal\(isolate\) },
            .global =\> self, // Already global
            else =\> self, // Primitives don't need conversion
        }\;
    }

    // === Lifecycle ===

    /// Dispose any owned resources \(Global handles\)
    pub fn dispose\(self: *JSValue\) void {
        if \(self.* == .global\) {
            self.global.dispose\(\)\;
        }
        self.* = .{ .undefined = {} }\;
    }

    // === Legacy Interop \(for gradual migration\) ===

    /// Convert from legacy anyopaque \(uses pointer tagging\)
    pub fn fromAnyopaque\(ptr: *const anyopaque\) JSValue {
        const pointer_tag = @import\("pointer_tag.zig"\)\;
        const untagged = pointer_tag.untagPointer\(ptr\)\;

        return switch \(untagged.tag\) {
            .global_handle =\> .{ .global = .{ .ptr = @constCast\(untagged.ptr\) } },
            .runtime_instance =\> .{ .instance = @ptrCast\(@alignCast\(@constCast\(untagged.ptr\)\)\) },
            .local_value =\> .{ .local = .{ .raw = @ptrCast\(@constCast\(untagged.ptr\)\) } },
            .untagged =\> {
                // Legacy untagged - assume it's a local value
                // This is unsafe but needed for migration
                return .{ .local = .{ .raw = @ptrCast\(@constCast\(untagged.ptr\)\) } }\;
            },
        }\;
    }

    /// Convert to legacy anyopaque \(for interop with old code\)
    pub fn toAnyopaque\(self: JSValue\) ?*const anyopaque {
        const pointer_tag = @import\("pointer_tag.zig"\)\;

        return switch \(self\) {
            .null, .undefined =\> null,
            .global =\> \|g\| pointer_tag.tagPointer\(g.ptr, .global_handle\),
            .instance =\> \|i\| pointer_tag.tagPointer\(@ptrCast\(i\), .runtime_instance\),
            .local =\> \|l\| pointer_tag.tagPointer\(@ptrCast\(l.raw\), .local_value\),
            .boolean, .number =\> null, // Primitives can't be represented as pointers
        }\;
    }
}\;

/// V8 Local handle wrapper
/// Compile-time enforcement: NO storage methods\!
pub const LocalHandle = struct {
    raw: *v8.Value,

    /// Convert to Global for persistent storage
    pub fn toGlobal\(self: LocalHandle, isolate: *v8.Isolate\) \!GlobalHandle {
        return GlobalHandle.create\(isolate, self.raw\)\;
    }

    /// Check if this is a function
    pub fn isFunction\(self: LocalHandle\) bool {
        return v8.v8_Value_IsFunction\(self.raw\)\;
    }

    /// Check if this is an object
    pub fn isObject\(self: LocalHandle\) bool {
        return v8.v8_Value_IsObject\(self.raw\)\;
    }
}\;

/// Optional JSValue \(replaces webidl.Opt\(*const anyopaque\)\)
pub const OptionalJSValue = union\(enum\) {
    not_passed: void,
    passed: JSValue,

    pub fn getOrUndefined\(self: OptionalJSValue\) JSValue {
        return switch \(self\) {
            .not_passed =\> .{ .undefined = {} },
            .passed =\> \|v\| v,
        }\;
    }

    pub fn getOrNull\(self: OptionalJSValue\) JSValue {
        return switch \(self\) {
            .not_passed =\> .{ .null = {} },
            .passed =\> \|v\| v,
        }\;
    }

    pub fn wasPassed\(self: OptionalJSValue\) bool {
        return self == .passed\;
    }
}\;

// Helper for instance conversion
fn instanceToV8\(isolate: *v8.Isolate, instance: *runtime.Instance\) ?*v8.Value {
    // Use existing wrapper cache mechanism
    const wrapper_cache = @import\("wrapper_cache.zig"\)\;
    return wrapper_cache.getOrCreateWrapper\(isolate, instance\)\;
}

