## Summary

Implement serialization of WebSocket frame headers for sending frames. This is the counterpart to WS-04 (parsing).

## Specification Reference

RFC 6455 Section 5.2 - Same framing format as parsing, but now we're producing bytes.

Key requirements:
- Client MUST mask all frames to server
- Server MUST NOT mask frames to client
- Use appropriate length encoding (7-bit, 16-bit, or 64-bit)

## Implementation Details

### File: src/websocket/protocol/frame.zig (additions)

```zig
/// Options for creating a frame
pub const FrameOptions = struct {
    /// Is this the final fragment?
    fin: bool = true,

    /// Frame opcode
    opcode: Opcode,

    /// Payload length
    payload_length: u64,

    /// Should the frame be masked? (required for client→server)
    mask: bool,

    /// RSV bits for extensions (usually all false)
    rsv1: bool = false,
    rsv2: bool = false,
    rsv3: bool = false,
};

/// Serialize a frame header into a buffer
/// Returns number of bytes written
/// Caller must ensure buffer is large enough (use headerSizeForPayload)
pub fn serializeFrameHeader(
    buffer: []u8,
    options: FrameOptions,
    masking_key: ?[4]u8, // Required if mask=true
) !usize {
    var offset: usize = 0;

    // Byte 0: FIN, RSV1-3, opcode
    var byte0: u8 = 0;
    if (options.fin) byte0 |= 0x80;
    if (options.rsv1) byte0 |= 0x40;
    if (options.rsv2) byte0 |= 0x20;
    if (options.rsv3) byte0 |= 0x10;
    byte0 |= @intFromEnum(options.opcode);
    buffer[offset] = byte0;
    offset += 1;

    // Byte 1: MASK, payload length
    var byte1: u8 = if (options.mask) 0x80 else 0;

    if (options.payload_length <= 125) {
        byte1 |= @truncate(options.payload_length);
        buffer[offset] = byte1;
        offset += 1;
    } else if (options.payload_length <= 65535) {
        byte1 |= 126;
        buffer[offset] = byte1;
        offset += 1;
        std.mem.writeInt(u16, buffer[offset..][0..2], @truncate(options.payload_length), .big);
        offset += 2;
    } else {
        byte1 |= 127;
        buffer[offset] = byte1;
        offset += 1;
        std.mem.writeInt(u64, buffer[offset..][0..8], options.payload_length, .big);
        offset += 8;
    }

    // Masking key (if masked)
    if (options.mask) {
        const key = masking_key orelse return error.MaskingKeyRequired;
        @memcpy(buffer[offset..][0..4], &key);
        offset += 4;
    }

    return offset;
}

/// Calculate header size for a given payload length and mask setting
pub fn headerSizeForPayload(payload_length: u64, masked: bool) usize {
    var size: usize = 2; // Base header
    if (payload_length >= 126 and payload_length <= 65535) {
        size += 2;
    } else if (payload_length > 65535) {
        size += 8;
    }
    if (masked) {
        size += 4;
    }
    return size;
}

/// Generate a random masking key
pub fn generateMaskingKey(rng: std.rand.Random) [4]u8 {
    var key: [4]u8 = undefined;
    rng.bytes(&key);
    return key;
}
```

