    const isolate = info.getIsolate();
    const arg = info.get(0);  // Local handle on Zig stack - is it rooted?

    // If GC runs here, is `arg` still valid?
    // V8's conservative scanner might not see Zig stack frames\!
    doSomethingThatTriggersGC();

    // Use-after-free if GC collected `arg`?
    processArg(arg);
