test "GC does not collect Zig stack handles" {
    const allocator = std.testing.allocator;

    // Create large object to pressure GC
    const isolate = try createTestIsolate();
    defer destroyIsolate(isolate);

    const context = try createTestContext(isolate);
    defer destroyContext(context);

    // Enter context
    ffi.v8_Context_Enter(context);
    defer ffi.v8_Context_Exit(context);

    // Create callback that holds Local handles across GC
    const callback = struct {
        fn call(info: *const ffi.FunctionCallbackInfo) callconv(.c) void {
            const iso = ffi.v8_FunctionCallbackInfo_GetIsolate(info);

            // Get argument - this is a Local handle on Zig stack
            const arg = ffi.v8_FunctionCallbackInfo_GetArg(info, 0);

            // Force garbage collection multiple times
            for (0..100) |_| {
                ffi.v8_Isolate_RequestGarbageCollectionForTesting(
                    iso,
                    ffi.GC_TYPE_FULL,
                );
            }

            // If GC collected `arg`, this will crash or corrupt data
            const str = ffi.v8_Value_ToString(arg, context);
            if (str == null) {
