            const len = ffi.v8_String_WriteUtf8(str, iso, &buf, 256);
            const content = buf[0..@intCast(len)];

            if (\!std.mem.eql(u8, content, "test_value")) {
                std.debug.panic("Handle data corrupted after GC\!", .{});
            }
        }
    };

    // Register callback
    const func_template = ffi.v8_FunctionTemplate_New(isolate, callback.call, null);
    const func = ffi.v8_FunctionTemplate_GetFunction(func_template, context);

    // Create test value
    const test_value = ffi.v8_String_NewFromUtf8(isolate, "test_value", 10);

    // Call function with test value
