### Fallback Option 2: Explicit Rooting in Zig
```zig
/// Root a Local handle explicitly
pub fn root(local: *ffi.Value) *ffi.Value {
    // Convert to Global (persistent) and back
    // This ensures V8 knows about the handle
    const global = ffi.v8_Global_New(local);
    // Keep global alive while we use it
    return ffi.v8_Global_Get(global);
}

fn myCallback(info: *const FunctionCallbackInfo) callconv(.c) void {
    const arg = ffi.v8_FunctionCallbackInfo_GetArg(info, 0);

    // Explicitly root before GC-triggering operations
    const rooted_arg = root(arg);
    defer ffi.v8_Global_Dispose(rooted_arg);

    doSomethingThatTriggersGC();

    // Safe to use rooted_arg
    processArg(rooted_arg);
}
```

