```zig
//! Implementation for WebIDL namespace: TestUtils
//!
//! WHATWG TestUtils Standard: https://testutils.spec.whatwg.org/
//!
//! This namespace provides testing APIs that are only available when
//! built with `-Denable-test-utils=true`.
//!
//! ## WebIDL Definition
//! ```webidl
//! [Exposed=(Window,Worker)]
//! namespace TestUtils {
//!   [NewObject] Promise<undefined> gc();
//! };
//! ```

const std = @import("std");
const runtime = @import("runtime");
const build_options = @import("build_options");

// Conditionally import testutils module
const testutils = if (build_options.enable_test_utils)
    @import("testutils")
else
    struct {
        // Stub when TestUtils is disabled
        pub fn performGC(_: runtime.Context) !*anyopaque {
            return error.NotImplemented;
        }
    };

/// TestUtils.gc() - Trigger garbage collection
///
/// Per WHATWG TestUtils spec:
/// 1. Let p be a new promise.
/// 2. Run the following in parallel:
///    2.1. Run implementation-defined steps to perform a garbage collection
///         covering at least the entry Realm.
///    2.2. Resolve p.
///
/// ## Returns
/// Promise<undefined> - resolves after GC completes
///
/// ## Errors
/// - error.NotImplemented: TestUtils not enabled in build
/// - error.NotExposedInContext: Called from wrong context (not Window/Worker)
/// - error.NoEngine: No JS engine configured
/// - error.PromiseError: Failed to create Promise
pub fn call_gc(ctx: runtime.Context) anyerror!*const anyopaque {
    return testutils.performGC(ctx);
}
```

