Alternatively, keep the existing file but gate the impl:

```zig
//! WebIDL namespace: TestUtils
//!
//! This file is AUTO-GENERATED. Do not edit manually.

const runtime = @import("runtime");
const build_options = @import("build_options");

const TestUtils_impl = if (build_options.enable_test_utils)
    @import("impls").TestUtils
else
    struct {
        pub fn call_gc(_: runtime.Context) anyerror!*const anyopaque {
            return error.NotImplemented;
        }
    };

pub const TestUtils = struct {
    pub const Meta = struct {
        pub const name = "TestUtils";
        pub const is_namespace = true;
        pub const BaseType = ?*anyopaque;
        pub const MixinTypes = &.{};

        pub const methods = .{
            .{ "gc", "call_gc" },
        };

        pub const has_constructor = false;
        pub const properties = .{};

        /// Whether TestUtils is enabled in this build
        pub const is_enabled = build_options.enable_test_utils;
    };

    pub const State = struct {};

    pub fn call_gc(ctx: runtime.Context) anyerror!*const anyopaque {
        return try TestUtils_impl.call_gc(ctx);
    }
};
```

