    defer c.curl_easy_cleanup(curl);

    _ = c.curl_easy_setopt(curl, c.CURLOPT_COOKIEFILE, "");
    _ = c.curl_easy_setopt(curl, c.CURLOPT_COOKIELIST, 
        "Set-Cookie: name=value; domain=.example.com; path=/; secure");

