//! Examples of V8 wrapper cache usage patterns

const std = @import("std");
const runtime = @import("runtime");
const v8 = @import("v8");

/// Example 1: querySelector returns same wrapper
pub fn exampleQuerySelectorIdentity() !void {
    // JavaScript equivalent:
    // const h1 = document.querySelector("header");
    // const h2 = document.querySelector("header");
    // console.assert(h1 === h2);

    const header1 = try querySelector("header");
    const header2 = try querySelector("header");

    // Same V8 Object pointer (identity preserved)
    std.debug.assert(header1 == header2);
}

/// Example 2: Constructor creates cached wrapper
pub fn exampleConstructorCaching() !void {
    // JavaScript: const elem = document.createElement("div");
    const elem = try createElement("div");

    // Cache now contains wrapper for elem
    // Future queries will return this same wrapper
}

/// Example 3: Cache hit vs miss performance
pub fn examplePerformance() !void {
    const start_miss = std.time.nanoTimestamp();
    const wrapper1 = try wrapInstanceAsV8Object(instance, "Element", isolate, context);
    const miss_duration = std.time.nanoTimestamp() - start_miss;

    const start_hit = std.time.nanoTimestamp();
    const wrapper2 = try wrapInstanceAsV8Object(instance, "Element", isolate, context);
    const hit_duration = std.time.nanoTimestamp() - start_hit;

    std.debug.print("Cache miss: {}ns\n", .{miss_duration});
    std.debug.print("Cache hit: {}ns\n", .{hit_duration});
    std.debug.print("Speedup: {}x\n", .{miss_duration / hit_duration});
}
