### 3. Add Realm Helper Methods

```zig
impl Realm {
    /// Create a TypeError from this realm
    pub fn createTypeError\(self: *Realm, message: []const u8\) v8.Value {
        const msg_str = v8.v8_String_NewFromUtf8\(self.isolate, message.ptr\)\;
        return v8.v8_Function_Call1\(
            self.intrinsics.type_error.toLocal\(self.isolate\),
            v8.v8_Undefined\(self.isolate\),
            msg_str,
        \)\;
    }

    /// Throw a TypeError from this realm
    pub fn throwTypeError\(self: *Realm, message: []const u8\) void {
        const error = self.createTypeError\(message\)\;
        v8.v8_Isolate_ThrowException\(self.isolate, error\)\;
    }

    /// Create a plain object {} in this realm
    pub fn createObject\(self: *Realm\) v8.Object {
        return v8.v8_Object_New\(self.isolate\)\;
        // Note: This automatically uses the current context's Object.prototype
    }

    /// Get the global object for this realm
    pub fn getGlobalObject\(self: *Realm\) v8.Value {
        return self.global_object.toLocal\(self.isolate\)\;
    }

    /// Check if this is a Window realm
    pub fn isWindow\(self: *Realm\) bool {
        return self.info.context_type == .window\;
    }
}
```

