fn aboutFetch(allocator: std.mem.Allocator, request: *InternalRequest) !*InternalResponse {
    const url = request.currentUrl();

    // Only about:blank is supported
    if (std.mem.eql(u8, url.path, "blank") and url.query == null) {
        const response = try InternalResponse.init(allocator);
        response.status = 200;
        try response.header_list.append("Content-Type", "text/html;charset=utf-8");
        response.body = try Body.fromBytes(allocator, "");
        return response;
    }

    return InternalResponse.networkError(allocator);
}
