fn blobFetch(allocator: std.mem.Allocator, request: *InternalRequest) !*InternalResponse {
    const url = request.currentUrl();

    // Resolve blob URL from blob URL store
    const blob = blobUrlStore.resolve(url) orelse {
        return InternalResponse.networkError(allocator);
    };

    const response = try InternalResponse.init(allocator);
    response.status = 200;

    // Set Content-Type if blob has type
    if (blob.mime_type.len > 0) {
        try response.header_list.append("Content-Type", blob.mime_type);
    }

    // Set Content-Length
    const length_str = try std.fmt.allocPrint(allocator, "{d}", .{blob.bytes.len});
    try response.header_list.append("Content-Length", length_str);

    // Set body
    response.body = try Body.fromBytes(allocator, blob.bytes);

    return response;
}
