## Summary

Implement the WebSocket connection state machine that tracks connection lifecycle per WHATWG WebSockets spec and RFC 6455.

## Specification Reference

### WHATWG WebSockets - Ready State

Each WebSocket object has an associated ready state:
- CONNECTING (0): Connection not yet established
- OPEN (1): Connection established, communication possible
- CLOSING (2): Going through closing handshake
- CLOSED (3): Connection closed or could not be opened

### RFC 6455 Section 7 - Closing the Connection

- "Start the WebSocket Closing Handshake" - Send close frame
- "The WebSocket Closing Handshake is Started" - Close frame sent or received
- "The WebSocket Connection is Closed" - TCP connection closed
- "Close the WebSocket Connection" - Initiate TCP close
- "The WebSocket Connection Close Code" and "Close Reason"

## Implementation Details

### File: src/websocket/connection/state_machine.zig

```zig
const std = @import("std");
const CloseCode = @import("../protocol/close_codes.zig").CloseCode;

/// WebSocket connection state per WHATWG spec
pub const ReadyState = enum(u2) {
    /// The connection has not yet been established
    connecting = 0,
    /// The WebSocket connection is established and communication is possible
    open = 1,
    /// The connection is going through the closing handshake
    closing = 2,
    /// The connection has been closed or could not be opened
    closed = 3,
};

/// Close information when connection ends
pub const CloseInfo = struct {
    /// The close code (1000-4999)
    code: CloseCode,
    /// The close reason (max 123 bytes UTF-8)
    reason: []const u8,
    /// Whether connection closed cleanly (close handshake completed)
    was_clean: bool,
};

/// Events emitted by the state machine
pub const StateEvent = union(enum) {
    /// Connection established - fire 'open' event
    opened,
    /// Message received - fire 'message' event
    message: MessageData,
    /// Error occurred - fire 'error' event  
    @"error": ErrorInfo,
    /// Connection closed - fire 'close' event
    closed: CloseInfo,
    /// Ping received - send pong automatically
    ping_received: []const u8,
    /// Pong received - for latency tracking
    pong_received: []const u8,
};

pub const MessageData = struct {
    /// Message content
    data: []const u8,
    /// True if text, false if binary
    is_text: bool,
};

pub const ErrorInfo = struct {
    /// Error description (not exposed to JS per spec)
    message: []const u8,
};

/// WebSocket connection state machine
pub const ConnectionStateMachine = struct {
    /// Current ready state
    state: ReadyState,

    /// Close code received/sent (valid in closing/closed states)
    close_code: ?CloseCode,

    /// Close reason received/sent
    close_reason: []const u8,

    /// Did we send the close frame?
    close_frame_sent: bool,

    /// Did we receive a close frame?
    close_frame_received: bool,

    /// Amount of data queued but not sent
    buffered_amount: u64,

    /// For fragmented messages: collected fragments
    fragment_buffer: std.ArrayList(u8),

    /// Type of current fragmented message (null if not fragmenting)
    fragment_opcode: ?Opcode,

    const Self = @This();

    pub fn init(allocator: std.mem.Allocator) Self {
        return .{
            .state = .connecting,
            .close_code = null,
            .close_reason = "",
            .close_frame_sent = false,
            .close_frame_received = false,
            .buffered_amount = 0,
            .fragment_buffer = std.ArrayList(u8).init(allocator),
            .fragment_opcode = null,
        };
    }

    pub fn deinit(self: *Self) void {
        self.fragment_buffer.deinit();
    }

    /// Transition to OPEN state when handshake completes
    pub fn connectionEstablished(self: *Self) !StateEvent {
        if (self.state != .connecting) {
            return error.InvalidStateTransition;
        }
        self.state = .open;
        return .opened;
    }

    /// Handle an incoming frame
    pub fn handleFrame(self: *Self, frame: FrameHeader, payload: []const u8) !?StateEvent {
        return switch (self.state) {
            .open, .closing => self.processFrame(frame, payload),
            .connecting => error.NotYetConnected,
            .closed => error.ConnectionClosed,
        };
    }

    fn processFrame(self: *Self, frame: FrameHeader, payload: []const u8) !?StateEvent {
        switch (frame.opcode) {
            .close => return self.handleCloseFrame(payload),
            .ping => return .{ .ping_received = payload },
            .pong => return .{ .pong_received = payload },
            .text, .binary => return self.handleDataFrame(frame, payload),
            .continuation => return self.handleContinuation(frame, payload),
            else => return error.InvalidOpcode,
        }
    }

    fn handleCloseFrame(self: *Self, payload: []const u8) !StateEvent {
        self.close_frame_received = true;

        // Parse close code and reason from payload
        if (payload.len >= 2) {
            self.close_code = @enumFromInt(std.mem.readInt(u16, payload[0..2], .big));
            if (payload.len > 2) {
                self.close_reason = payload[2..];
            }
        } else {
            self.close_code = .no_status_received;
        }

        if (self.state == .open) {
            // Server initiated close - transition to closing
            self.state = .closing;
        }

        if (self.close_frame_sent and self.close_frame_received) {
            // Close handshake complete
            self.state = .closed;
            return .{ .closed = .{
                .code = self.close_code.?,
                .reason = self.close_reason,
                .was_clean = true,
            }};
        }

        return null; // Need to send close frame in response
    }

    fn handleDataFrame(self: *Self, frame: FrameHeader, payload: []const u8) !StateEvent {
        if (frame.fin) {
            // Complete message in single frame
            return .{ .message = .{
                .data = payload,
                .is_text = frame.opcode == .text,
            }};
        } else {
            // First fragment of a message
            self.fragment_opcode = frame.opcode;
            try self.fragment_buffer.appendSlice(payload);
            return null;
        }
    }

    fn handleContinuation(self: *Self, frame: FrameHeader, payload: []const u8) !StateEvent {
        if (self.fragment_opcode == null) {
            return error.UnexpectedContinuation;
        }

        try self.fragment_buffer.appendSlice(payload);

        if (frame.fin) {
            // Final fragment - deliver complete message
            const data = try self.fragment_buffer.toOwnedSlice();
            const is_text = self.fragment_opcode.? == .text;
            self.fragment_opcode = null;

            return .{ .message = .{
                .data = data,
                .is_text = is_text,
            }};
        }

        return null;
    }

    /// Initiate close handshake (from API call)
    pub fn initiateClose(self: *Self, code: ?CloseCode, reason: []const u8) !void {
        switch (self.state) {
            .open => {
                self.state = .closing;
                self.close_code = code orelse .normal_closure;
                self.close_reason = reason;
            },
            .closing, .closed => {}, // Already closing/closed
            .connecting => {
                // Fail the connection
                self.state = .closing;
            },
        }
    }

    /// Mark close frame as sent
    pub fn closeFrameSent(self: *Self) void {
        self.close_frame_sent = true;
        if (self.close_frame_sent and self.close_frame_received) {
            self.state = .closed;
        }
    }

    /// Handle abnormal closure (TCP disconnect without close frame)
    pub fn abnormalClose(self: *Self) StateEvent {
        self.state = .closed;
        return .{ .closed = .{
            .code = .abnormal_closure,
            .reason = "",
            .was_clean = false,
        }};
    }

    /// Update buffered amount
    pub fn addBufferedAmount(self: *Self, bytes: u64) void {
        self.buffered_amount += bytes;
    }

    pub fn subtractBufferedAmount(self: *Self, bytes: u64) void {
        self.buffered_amount -= @min(bytes, self.buffered_amount);
    }
};
```

