test "clean close handshake" {
    var sm = ConnectionStateMachine.init(testing.allocator);
    defer sm.deinit();
    _ = try sm.connectionEstablished();

    // Initiate close
    try sm.initiateClose(.normal_closure, "goodbye");
    try testing.expectEqual(ReadyState.closing, sm.state);

    // Mark our close as sent
    sm.closeFrameSent();

    // Receive close response
    const close_payload = [_]u8{ 0x03, 0xE8 }; // 1000
    const event = try sm.handleFrame(.{ .opcode = .close, .fin = true, ... }, &close_payload);

    try testing.expectEqual(ReadyState.closed, sm.state);
    try testing.expect(event.?.closed.was_clean);
}

test "server-initiated close" {
    var sm = ConnectionStateMachine.init(testing.allocator);
    defer sm.deinit();
    _ = try sm.connectionEstablished();

    // Receive close from server
    const close_payload = [_]u8{ 0x03, 0xE8, 'b', 'y', 'e' }; // 1000, "bye"
    _ = try sm.handleFrame(.{ .opcode = .close, ... }, &close_payload);

    try testing.expectEqual(ReadyState.closing, sm.state);
    try testing.expectEqual(CloseCode.normal_closure, sm.close_code.?);
}

test "fragmented message reassembly" {
    var sm = ConnectionStateMachine.init(testing.allocator);
    defer sm.deinit();
    _ = try sm.connectionEstablished();

    // First fragment
    _ = try sm.handleFrame(.{ .opcode = .text, .fin = false, ... }, "Hel");
    try testing.expect(sm.fragment_opcode != null);

    // Continuation
    _ = try sm.handleFrame(.{ .opcode = .continuation, .fin = false, ... }, "lo ");

    // Final fragment
    const event = try sm.handleFrame(.{ .opcode = .continuation, .fin = true, ... }, "World");
    try testing.expectEqualSlices(u8, "Hello World", event.?.message.data);
}
