**Interface Design:**

```zig
pub const Operation = union(enum) {
    Read: struct {
        fd: std.os.fd_t,
        buffer: []u8,
        offset: u64,
    },
    Write: struct {
        fd: std.os.fd_t,
        buffer: []const u8,
        offset: u64,
    },
    Accept: struct {
        listen_fd: std.os.fd_t,
    },
    Connect: struct {
        fd: std.os.fd_t,
        addr: std.net.Address,
    },
    Close: struct {
        fd: std.os.fd_t,
    },
};

pub const Completion = struct {
    op: Operation,
    result: union(enum) {
        Success: usize, // bytes transferred or fd
        Error: anyerror,
    },
    user_data: u64, // User context
};

pub const Poller = struct {
    ptr: *anyopaque,
    vtable: *const VTable,

    pub const VTable = struct {
        init: *const fn (allocator: std.mem.Allocator) anyerror!*anyopaque,
        deinit: *const fn (ctx: *anyopaque) void,
        submit: *const fn (ctx: *anyopaque, op: Operation, user_data: u64) anyerror!void,
        poll: *const fn (ctx: *anyopaque, completions: []Completion, timeout_ns: ?u64) anyerror!usize,
    };

    pub fn init(allocator: std.mem.Allocator) !Poller {
        // Compile-time platform selection
        const Impl = switch (builtin.os.tag) {
            .linux => @import("linux_uring.zig").UringPoller,
            .windows => @import("windows_iocp.zig").IOCPPoller,
            .macos, .ios => @import("macos_kqueue.zig").KqueuePoller,
            else => @compileError("Unsupported platform"),
        };

        const impl = try Impl.init(allocator);
        return Poller{
            .ptr = impl,
            .vtable = &Impl.vtable,
        };
    }

    pub fn submit(self: *Poller, op: Operation, user_data: u64) !void {
        return self.vtable.submit(self.ptr, op, user_data);
    }

    pub fn poll(self: *Poller, completions: []Completion, timeout_ns: ?u64) !usize {
        return self.vtable.poll(self.ptr, completions, timeout_ns);
    }
};
