const std = @import("std");

/// Abstract network transport interface for WebSocket
pub const Transport = struct {
    ptr: *anyopaque,
    vtable: *const VTable,

    pub const VTable = struct {
        /// Read data from the transport
        read: *const fn (ptr: *anyopaque, buffer: []u8) ReadError!usize,

        /// Write data to the transport
        write: *const fn (ptr: *anyopaque, data: []const u8) WriteError!usize,

        /// Close the transport
        close: *const fn (ptr: *anyopaque) void,

        /// Check if more data is available without blocking
        poll: *const fn (ptr: *anyopaque) PollResult,

        /// Get the remote address (for debugging)
        getRemoteAddress: *const fn (ptr: *anyopaque) ?std.net.Address,
    };

    pub const ReadError = error{
        ConnectionClosed,
        ConnectionReset,
        Timeout,
        WouldBlock,
        TlsError,
        Unexpected,
    };

    pub const WriteError = error{
        ConnectionClosed,
        ConnectionReset,
        BrokenPipe,
        WouldBlock,
        TlsError,
        Unexpected,
    };

    pub const PollResult = enum {
        /// Data available to read
        readable,
        /// Socket ready for writing
        writable,
        /// Connection closed
        closed,
        /// Error occurred
        @"error",
        /// No events (timeout)
        none,
    };

    pub fn read(self: Transport, buffer: []u8) ReadError!usize {
        return self.vtable.read(self.ptr, buffer);
    }

    pub fn write(self: Transport, data: []const u8) WriteError!usize {
        return self.vtable.write(self.ptr, data);
    }

    pub fn close(self: Transport) void {
        self.vtable.close(self.ptr);
    }

    pub fn poll(self: Transport) PollResult {
        return self.vtable.poll(self.ptr);
    }

    pub fn getRemoteAddress(self: Transport) ?std.net.Address {
        return self.vtable.getRemoteAddress(self.ptr);
    }

    /// Helper to write all data
    pub fn writeAll(self: Transport, data: []const u8) WriteError!void {
        var written: usize = 0;
        while (written < data.len) {
            written += try self.write(data[written..]);
        }
    }

    /// Helper to read exactly n bytes
    pub fn readExact(self: Transport, buffer: []u8) ReadError!void {
        var read_bytes: usize = 0;
        while (read_bytes < buffer.len) {
            const n = try self.read(buffer[read_bytes..]);
            if (n == 0) return error.ConnectionClosed;
            read_bytes += n;
        }
    }
};

/// Connection options for establishing transport
pub const ConnectOptions = struct {
    /// Target host
    host: []const u8,
    /// Target port
    port: u16,
    /// Connection timeout in milliseconds
    timeout_ms: u32 = 30000,
    /// Use TLS (for wss://)
    use_tls: bool = false,
    /// TLS server name indication (defaults to host)
    tls_sni: ?[]const u8 = null,
    /// Skip TLS certificate verification (DANGEROUS - testing only)
    tls_skip_verify: bool = false,
};

/// Establish a connection and return a Transport
pub fn connect(allocator: std.mem.Allocator, options: ConnectOptions) !Transport {
    if (options.use_tls) {
        return TlsTransport.connect(allocator, options);
    } else {
        return TcpTransport.connect(allocator, options);
    }
}
```

