```zig
const std = @import("std");
const Transport = @import("transport.zig").Transport;
const ConnectOptions = @import("transport.zig").ConnectOptions;

/// Plain TCP transport implementation
pub const TcpTransport = struct {
    stream: std.net.Stream,
    allocator: std.mem.Allocator,

    const Self = @This();

    pub fn connect(allocator: std.mem.Allocator, options: ConnectOptions) !Transport {
        const address = try std.net.Address.resolveIp(options.host, options.port);
        const stream = try std.net.tcpConnectToAddress(address);

        const self = try allocator.create(Self);
        self.* = .{
            .stream = stream,
            .allocator = allocator,
        };

        return .{
            .ptr = self,
            .vtable = &vtable,
        };
    }

    fn readImpl(ptr: *anyopaque, buffer: []u8) Transport.ReadError!usize {
        const self: *Self = @ptrCast(@alignCast(ptr));
        return self.stream.read(buffer) catch |err| switch (err) {
            error.ConnectionResetByPeer => error.ConnectionReset,
            else => error.Unexpected,
        };
    }

    fn writeImpl(ptr: *anyopaque, data: []const u8) Transport.WriteError!usize {
        const self: *Self = @ptrCast(@alignCast(ptr));
        return self.stream.write(data) catch |err| switch (err) {
            error.ConnectionResetByPeer => error.ConnectionReset,
            error.BrokenPipe => error.BrokenPipe,
            else => error.Unexpected,
        };
    }

    fn closeImpl(ptr: *anyopaque) void {
        const self: *Self = @ptrCast(@alignCast(ptr));
        self.stream.close();
        self.allocator.destroy(self);
    }

    fn pollImpl(ptr: *anyopaque) Transport.PollResult {
        // TODO: Use poll/select
        _ = ptr;
        return .readable;
    }

    fn getRemoteAddressImpl(ptr: *anyopaque) ?std.net.Address {
        const self: *Self = @ptrCast(@alignCast(ptr));
        return self.stream.getRemoteAddress() catch null;
    }

    const vtable = Transport.VTable{
        .read = readImpl,
        .write = writeImpl,
        .close = closeImpl,
        .poll = pollImpl,
        .getRemoteAddress = getRemoteAddressImpl,
    };
};
