Implement production io_uring backend with SQPOLL (zero-syscall submission) and buffer registration.

**Objectives:**
- io_uring initialization with SQPOLL flag
- Zero-syscall submission
- Buffer registration from slab allocator
- Completion queue processing

**Files to Create:**
```
src/runtime/event_loop/reactor/linux_uring.zig
tests/event_loop/linux_uring_test.zig
```

**Implementation:**

```zig
pub const UringPoller = struct {
    ring: std.os.linux.IO_Uring,
    registered_buffers: [][]u8, // From SlabAllocator
    allocator: std.mem.Allocator,

    pub fn init(allocator: std.mem.Allocator) !*UringPoller {
        const self = try allocator.create(UringPoller);

        // Initialize io_uring with 4096 entries
        self.ring = try std.os.linux.IO_Uring.init(4096, 0);

        // Enable SQPOLL (kernel thread polls submission queue)
        const params = std.os.linux.io_uring_params{
            .flags = std.os.linux.IORING_SETUP_SQPOLL | 
                     std.os.linux.IORING_SETUP_SQ_AFF,
            .sq_thread_idle = 1000, // 1 second idle timeout
            .sq_thread_cpu = 0, // Pin to CPU 0
        };

        try self.ring.reinit(&params);

        self.allocator = allocator;
        return self;
    }

    pub fn registerBuffers(self: *UringPoller, buffers: [][]u8) !void {
        // Register buffers with kernel (one-time mapping)
        var iovecs = try self.allocator.alloc(std.os.iovec, buffers.len);
        defer self.allocator.free(iovecs);

        for (buffers, 0..) |buf, i| {
            iovecs[i] = .{
                .iov_base = buf.ptr,
                .iov_len = buf.len,
            };
        }

        try self.ring.register_buffers(iovecs);
        self.registered_buffers = buffers;
    }

    pub fn submit(self: *UringPoller, op: Operation, user_data: u64) !void {
        const sqe = try self.ring.get_sqe();

        switch (op) {
            .Read => |r| {
                // Use registered buffer if available
                const buf_idx = self.findBufferIndex(r.buffer);
                if (buf_idx) |idx| {
                    sqe.prep_read_fixed(r.fd, r.buffer, r.offset, idx);
                } else {
                    sqe.prep_read(r.fd, r.buffer, r.offset);
                }
            },
            .Write => |w| {
                const buf_idx = self.findBufferIndex(w.buffer);
                if (buf_idx) |idx| {
                    sqe.prep_write_fixed(w.fd, w.buffer, w.offset, idx);
                } else {
                    sqe.prep_write(w.fd, w.buffer, w.offset);
                }
            },
            .Accept => |a| sqe.prep_accept(a.listen_fd, null, null, 0),
            .Connect => |c| sqe.prep_connect(c.fd, &c.addr.any, c.addr.getOsSockLen()),
            .Close => |c| sqe.prep_close(c.fd),
        }

        sqe.user_data = user_data;

        // NO SYSCALL HERE - kernel thread will see the SQE
    }

    pub fn poll(self: *UringPoller, completions: []Completion, timeout_ns: ?u64) !usize {
        const timeout_spec = if (timeout_ns) |ns| 
            std.os.linux.kernel_timespec{
                .tv_sec = @intCast(ns / std.time.ns_per_s),
                .tv_nsec = @intCast(ns % std.time.ns_per_s),
            }
        else null;

        // Wait for completions (only syscall if CQ empty)
        const count = try self.ring.copy_cqes(completions.len, timeout_spec);

        for (self.ring.cqes[0..count], 0..) |cqe, i| {
            completions[i] = .{
                .op = undefined, // TODO: Reconstruct from user_data
                .result = if (cqe.res >= 0) 
                    .{ .Success = @intCast(cqe.res) }
                else 
                    .{ .Error = error.IOError },
                .user_data = cqe.user_data,
            };
        }

        return count;
    }

    fn findBufferIndex(self: *UringPoller, buffer: []const u8) ?u16 {
        for (self.registered_buffers, 0..) |buf, i| {
            if (buf.ptr == buffer.ptr) return @intCast(i);
        }
        return null;
    }

    pub fn deinit(self: *UringPoller) void {
        self.ring.deinit();
        self.allocator.destroy(self);
    }

    pub const vtable = Poller.VTable{
        .init = init,
        .deinit = deinit,
        .submit = submit,
        .poll = poll,
    };
};
```

