test "slice - end clamped to size" {
    const allocator = testing.allocator;
    const blob = try BlobData.init(allocator, "Hello", "");
    defer blob.deinit();

    const sliced = try sliceBlob(allocator, blob, 0, 1000, null);
    defer sliced.deinit();

    try testing.expectEqualStrings("Hello", sliced.bytes);
}

test "slice - null params = clone" {
    const allocator = testing.allocator;
    const blob = try BlobData.init(allocator, "Hello", "text/plain");
    defer blob.deinit();

    const sliced = try sliceBlob(allocator, blob, null, null, null);
    defer sliced.deinit();

    try testing.expectEqualStrings("Hello", sliced.bytes);
    try testing.expectEqualStrings("", sliced.getType()); // Note: contentType not inherited
}

test "slice - invalid contentType chars" {
    const allocator = testing.allocator;
    const blob = try BlobData.init(allocator, "Hello", "");
    defer blob.deinit();

    // contentType with invalid char should become empty
    const sliced = try sliceBlob(allocator, blob, null, null, "text/plain\x00");
    defer sliced.deinit();

    try testing.expectEqualStrings("", sliced.getType());
}

test "slice - empty blob" {
    const allocator = testing.allocator;
    const blob = try BlobData.init(allocator, "", "");
    defer blob.deinit();

    const sliced = try sliceBlob(allocator, blob, 0, 10, null);
    defer sliced.deinit();

    try testing.expectEqual(@as(u64, 0), sliced.size());
}

test "slice - very negative start clamped to 0" {
    const allocator = testing.allocator;
    const blob = try BlobData.init(allocator, "Hello", "");
    defer blob.deinit();

    const sliced = try sliceBlob(allocator, blob, -1000, null, null);
    defer sliced.deinit();

    try testing.expectEqualStrings("Hello", sliced.bytes);
}
```

## Spec Notes

### Index Normalization
The algorithm uses JavaScript-style index normalization:
- Negative indices count backwards from end
- Out-of-bounds indices are clamped to valid range
- If start >= end after normalization, result is empty Blob

### ContentType Behavior
- **Not inherited**: If contentType is null, new Blob's type is empty string (not inherited from original)
- **Validated**: Characters must be in range U+0020-U+007E
- **Lowercased**: Converted to ASCII lowercase

