pub const CacheBackend = struct {
    ptr: *anyopaque,
    vtable: *const VTable,

    pub const VTable = struct {
        /// Find matching cached response for request.
        match: *const fn(ptr: *anyopaque, key: CacheKey) ?*CacheEntry,

        /// Store response in cache.
        store: *const fn(ptr: *anyopaque, key: CacheKey, entry: CacheEntry) anyerror!void,

        /// Delete cached entry.
        delete: *const fn(ptr: *anyopaque, key: CacheKey) void,

        /// Clear all entries.
