/// Calculate freshness lifetime per RFC 7234 § 4.2.1.
pub fn calculateFreshnessLifetime(entry: *CacheEntry) u64 {
    // 1. If s-maxage present (shared cache), use it
    // 2. Else if max-age present, use it
    // 3. Else if Expires present, use Expires - Date
    // 4. Else use heuristic (10% of time since Last-Modified)
}

/// Calculate current age per RFC 7234 § 4.2.3.
pub fn calculateCurrentAge(entry: *CacheEntry) u64 {
    // age_value = Age header if present, else 0
    // date_value = Date header
    // now = current time
    // request_time = when request was made
    // response_time = when response was received
    // apparent_age = max(0, response_time - date_value)
    // corrected_age_value = age_value + (response_time - request_time)
    // corrected_initial_age = max(apparent_age, corrected_age_value)
    // resident_time = now - response_time
    // current_age = corrected_initial_age + resident_time
}
