                .opened => WebSocketEventTask{
                    .websocket = self.websocket_instance.?,
                    .event = .{ .open = .{
                        .extensions = self.extensions,
                        .protocol = self.protocol,
                    }},
                },
                .message => |msg| WebSocketEventTask{
                    .websocket = self.websocket_instance.?,
                    .event = .{ .message = .{
                        .data = msg.data,
                        .is_text = msg.is_text,
                        .origin = self.url,
                    }},
                },
                .closed => |info| WebSocketEventTask{
                    .websocket = self.websocket_instance.?,
                    .event = .{ .close = .{
                        .was_clean = info.was_clean,
                        .code = @intFromEnum(info.code),
                        .reason = info.reason,
                    }},
                },
                // ... etc
            };

            queueWebSocketEvent(loop, task) catch {};
        }
    }
};
```

