pub fn exec\(
    pattern: *const URLPattern,
    input: URLPatternInput,
    base_url: ?[]const u8,
\) ?URLPatternResult {
    // 1. Parse input URL
    const url = parseInput\(input, base_url\) orelse return null\;

    // 2. Match each component
    const protocol_result = matchComponent\(pattern.protocol, url.scheme\) orelse return null\;
    const username_result = matchComponent\(pattern.username, url.username\) orelse return null\;
    // ... etc for all 8 components

    // 3. Build result
    return URLPatternResult{
        .inputs = \&[_][]const u8{input},
        .protocol = protocol_result,
        // ... etc
    }\;
}
```

## Match Component

```zig
fn matchComponent\(component: Component, input: []const u8\) ?URLPatternComponentResult {
    // 1. Execute regex
    const match_result = component.regex.match\(input\) orelse return null\;

    // 2. Extract named groups
    var groups = StringMap.init\(allocator\)\;
    for \(component.group_names\) \|name\| {
        if \(component.regex.getNamedGroup\(name\)\) \|value\| {
            groups.put\(name, value\)\;
        }
    }

    return URLPatternComponentResult{
        .input = input,
        .groups = groups,
    }\;
}
```

## Input Processing

```zig
const URLPatternInput = union\(enum\) {
    string: []const u8,
    init: URLPatternInit,
}\;

fn parseInput\(input: URLPatternInput, base_url: ?[]const u8\) ?ParsedURL {
    switch \(input\) {
        .string =\> \|s\| {
            // Parse as URL
            return URL.parse\(allocator, s, base_url\)\;
        },
        .init =\> \|init\| {
            // Use individual component values
            return buildURLFromInit\(init\)\;
        },
    }
}
```

