## Summary
Implement the ProgressEvent interface used by FileReader for progress notifications. ProgressEvent extends Event with progress-related properties.

## Spec Reference
- XMLHttpRequest Standard: ProgressEvent
- https://xhr.spec.whatwg.org/#progressevent
- Used by: FileReader, XMLHttpRequest, Fetch

## WebIDL Definition
```webidl
[Exposed=(Window,Worker)]
interface ProgressEvent : Event {
  constructor(DOMString type, optional ProgressEventInit eventInitDict = {});
  readonly attribute boolean lengthComputable;
  readonly attribute unsigned long long loaded;
  readonly attribute unsigned long long total;
};

dictionary ProgressEventInit : EventInit {
  boolean lengthComputable = false;
  unsigned long long loaded = 0;
  unsigned long long total = 0;
};
```

## Implementation
```zig
// src/webidl/impls/ProgressEvent.zig

pub const InternalState = struct {
    length_computable: bool,
    loaded: u64,
    total: u64,
};

pub fn call_constructor(
    allocator: std.mem.Allocator,
    ctx: runtime.Context,
    event_type: runtime.DOMString,
    init: dictionaries.ProgressEventInit,
) !*runtime.Instance {
    // Create Event base
    const event_init = dictionaries.EventInit{
        .bubbles = init.base.bubbles,
        .cancelable = init.base.cancelable,
        .composed = init.base.composed,
    };

    const instance = try ProgressEvent.init(allocator, ProgressEvent.State, &ProgressEvent.vtable, ctx);

    // Initialize Event properties via base
    try Event.initializeEvent(instance, event_type, event_init);

    // Set ProgressEvent-specific properties
    const internal = try allocator.create(InternalState);
    internal.* = .{
        .length_computable = init.lengthComputable orelse false,
        .loaded = init.loaded orelse 0,
        .total = init.total orelse 0,
    };
    try setInternal(instance, internal);

    return instance;
}

pub fn get_lengthComputable(instance: *runtime.Instance) !bool {
    const internal = getInternal(instance) orelse return false;
    return internal.length_computable;
}

pub fn get_loaded(instance: *runtime.Instance) !u64 {
    const internal = getInternal(instance) orelse return 0;
    return internal.loaded;
}

pub fn get_total(instance: *runtime.Instance) !u64 {
    const internal = getInternal(instance) orelse return 0;
    return internal.total;
}
```

## Usage in FileReader
```zig
fn fireProgressEvent(
    file_reader: *runtime.Instance,
    event_name: []const u8,
    length_computable: bool,
    loaded: u64,
    total: u64,
) !void {
    const event = try ProgressEvent.call_constructor(
        allocator, ctx,
        runtime.DOMString.fromSlice(event_name),
        .{
            .base = .{ .bubbles = false, .cancelable = false },
            .lengthComputable = length_computable,
            .loaded = loaded,
            .total = total,
        },
    );
    defer ProgressEvent.deinit(event);

    // Set isTrusted for UA-dispatched events
    Event.setIsTrusted(event, true);

    // Dispatch via EventTarget
    _ = try EventTarget.call_dispatchEvent(file_reader, event);
}
```

