### Create Blob from WebSocket data

```zig
// src/websocket/binary_types.zig

const std = @import("std");
const runtime = @import("runtime");
const interfaces = @import("interfaces");
const BlobImpl = @import("../file/blob.zig");

/// Create a Blob from binary WebSocket message data
pub fn createBlobFromBinary(
    allocator: std.mem.Allocator,
    ctx: runtime.Context,
    data: []const u8,
) !*runtime.Instance {
    // Create Blob using the File API implementation
    const blob = try BlobImpl.createFromBytes(allocator, ctx, data, .{
        .type = "", // No MIME type for WebSocket binary
    });

    return blob;
}

/// Create an ArrayBuffer from binary WebSocket message data
pub fn createArrayBufferFromBinary(
    allocator: std.mem.Allocator,
    ctx: runtime.Context,
    data: []const u8,
) !runtime.ArrayBuffer {
    // Create ArrayBuffer in the relevant realm
    return try runtime.ArrayBuffer.fromSlice(allocator, ctx, data);
}

/// Get binary data from send() argument based on its type
pub const BinaryDataSource = union(enum) {
    string: []const u8,
    blob: *runtime.Instance,
    array_buffer: runtime.ArrayBuffer,
    array_buffer_view: runtime.ArrayBufferView,

    /// Extract the raw bytes for sending
    pub fn getBytes(self: BinaryDataSource, allocator: std.mem.Allocator) ![]const u8 {
        return switch (self) {
            .string => |s| s,
            .blob => |b| try BlobImpl.getBytes(b, allocator),
            .array_buffer => |ab| ab.data,
            .array_buffer_view => |view| view.getSlice(),
        };
    }

    /// Get byte length for bufferedAmount
    pub fn byteLength(self: BinaryDataSource) u64 {
        return switch (self) {
            .string => |s| s.len,
            .blob => |b| BlobImpl.getSize(b),
            .array_buffer => |ab| ab.data.len,
            .array_buffer_view => |view| view.byteLength,
        };
    }
};

/// Determine the type of data passed to send()
/// This would be called from the JS binding layer
pub fn classifyBinaryData(data: *const anyopaque, type_info: TypeInfo) BinaryDataSource {
    return switch (type_info) {
        .string => .{ .string = @ptrCast(data) },
        .blob => .{ .blob = @ptrCast(@alignCast(data)) },
        .array_buffer => .{ .array_buffer = @ptrCast(@alignCast(data)).* },
        .typed_array, .data_view => .{ .array_buffer_view = @ptrCast(@alignCast(data)).* },
    };
}

pub const TypeInfo = enum {
    string,
    blob,
    array_buffer,
    typed_array,
    data_view,
};
```

### Integration with MessageEvent

```zig
// In events.zig or MessageEvent impl

pub fn createBinaryMessageEvent(
    allocator: std.mem.Allocator,
    ctx: runtime.Context,
    data: []const u8,
    origin: []const u8,
    binary_type: enums.BinaryType,
) !*runtime.Instance {
    const event = try MessageEventImpl.init(allocator, MessageEvent.State, &MessageEvent.vtable, ctx);
    errdefer MessageEventImpl.deinit(event);

    const state = event.getState(MessageEvent.State);
    state.type = "message";

    const internal = state._internal.?;
    internal.origin = try allocator.dupe(u8, origin);

    // Create appropriate data type based on binaryType
    internal.data = switch (binary_type) {
        .blob => .{ .blob = try binary_types.createBlobFromBinary(allocator, ctx, data) },
        .arraybuffer => .{ .array_buffer = try binary_types.createArrayBufferFromBinary(allocator, ctx, data) },
    };

    return event;
}
```

### Memory Management for Blob Data

```zig
// Ensure Blob data is properly managed

pub const BlobData = struct {
    /// The raw binary data
    bytes: []const u8,
    /// Whether we own this memory
    owned: bool,
    /// Allocator used (if owned)
    allocator: ?std.mem.Allocator,

    pub fn fromWebSocketMessage(allocator: std.mem.Allocator, data: []const u8) !BlobData {
        return .{
            .bytes = try allocator.dupe(u8, data),
            .owned = true,
            .allocator = allocator,
        };
    }

    pub fn deinit(self: *BlobData) void {
        if (self.owned) {
            if (self.allocator) |alloc| {
                alloc.free(self.bytes);
            }
        }
    }
};
```

