### abort() Method
```zig
pub fn call_abort(instance: *runtime.Instance) !void {
    const internal = getInternal(instance) orelse return;

    // If EMPTY or DONE, just set result to null
    if (internal.state == .EMPTY or internal.state == .DONE) {
        internal.result = null;
        return;
    }

    // If LOADING, abort the read
    if (internal.state == .LOADING) {
        internal.state = .DONE;
        internal.result = null;
        // Cancel pending read tasks
        // Fire abort event
        try fireProgressEvent(instance, "abort", false, 0, 0);
        // Fire loadend if still not loading
        if (internal.state != .LOADING) {
            try fireProgressEvent(instance, "loadend", false, 0, 0);
        }
    }
}
