## Overview

Ensure that `[Default] toJSON\(\)` operations create result objects in the **method's realm**, not the caller's realm.

## WPT Test Requirements

From `default-toJSON-cross-realm.html`:
```javascript
const other = iframe.contentWindow\;
const rect = new DOMRectReadOnly\(1, 2, 3, 4\)\;

// Call other realm's toJSON on our rect
const json = other.DOMRectReadOnly.prototype.toJSON.call\(rect\)\;

// Result object's prototype should be from OTHER realm
assert_equals\(Object.getPrototypeOf\(json\), other.Object.prototype\)\;
```

## Current State

toJSON implementations likely create objects using the current context, not the method's realm.

## Required Changes

### 1. Add Realm Parameter to toJSON

```zig
// In codegen for [Default] toJSON

pub fn toJSON\(instance: *Instance, realm: *Realm\) \!v8.Object {
    // Create result object in the specified realm
    const result = realm.createObject\(\)\;

    // Populate with attribute values
    // Note: The VALUES may come from different realms - that's OK
    // Only the container object needs to be from method's realm
    inline for \(Interface.exposed_attributes\) \|attr\| {
        const value = try @field\(instance, attr.getter\)\(instance\)\;
        try result.set\(attr.name, value\)\;
    }

    return result\;
}
```

### 2. Update toJSON Callback to Pass Realm

```zig
pub fn toJSON_callback\(info: v8.FunctionCallbackInfo\) callconv\(.c\) void {
    // Get the method's realm \(from callback context\)
    const method_realm = getCallbackRealm\(info\)\;

    // Validate this
    const instance = validateThis\(info, Interface\) catch return\;

    // Call toJSON with method's realm
    const result = instance.toJSON\(method_realm\) catch \|err\| {
        handleError\(method_realm, err\)\;
        return\;
    }\;

    v8.v8_ReturnValue_Set\(info.getReturnValue\(\), result\)\;
}
```

### 3. Implement Realm.createObject

```zig
// In realm.zig

pub fn createObject\(self: *Realm\) v8.Object {
    // Enter this realm's context to create object
    const was_in_context = v8.v8_Context_InContext\(self.v8_context\)\;
    if \(\!was_in_context\) {
        v8.v8_Context_Enter\(self.v8_context\)\;
    }
    defer if \(\!was_in_context\) {
        v8.v8_Context_Exit\(self.v8_context\)\;
    }\;

    // Create plain object - inherits from this context's Object.prototype
    return v8.v8_Object_New\(self.isolate\)\;
}
```

### 4. Update Codegen for toJSON

```zig
// In codegen/writer.zig

fn writeDefaultToJSON\(writer: anytype, interface: InterfaceDef\) \!void {
    try writer.print\(
        \\pub fn toJSON\(info: v8.FunctionCallbackInfo\) callconv\(.c\) void {{
        \\    const method_realm = runtime.getCallbackRealm\(info\)\;
        \\    const instance = validateThis\(info, {s}\) catch return\;
        \\    
        \\    // Create result in method's realm
        \\    const result = method_realm.createObject\(\)\;
        \\    
    , .{interface.name}\)\;

    // Add each exposed attribute
    for \(interface.attributes\) \|attr\| {
        if \(attr.has_default_to_json\) {
            try writer.print\(
                \\    result.set\("{s}", instance.get_{s}\(\) catch \|e\| {{
                \\        method_realm.throwError\(e\)\;
                \\        return\;
                \\    }}\)\;
            , .{ attr.name, attr.name }\)\;
        }
    }

    try writer.print\(
        \\    
        \\    info.getReturnValue\(\).set\(result\)\;
        \\}}
    , .{}\)\;
}
```

