## Overview
Implement build system support for selecting JavaScript engines at compile time. Currently V8 is hardcoded; the research document recommends supporting V8, JSC, and SpiderMonkey via build flags.

## Problem Statement
**Current State**: V8 is implicitly linked with no option to switch engines
**Research Requirement**: `zig build -Dengine=v8` or `zig build -Dengine=jsc`

**Impact**:
- Cannot test alternative engines without modifying build.zig
- No easy way to compare engine performance
- Limits development flexibility

## Research Document Requirements
From research.md Section 7 (Build System Configuration):
```zig
const engine = b.option([]const u8, "engine", "Select JS engine: v8, sm, jsc") orelse "jsc";
if (std.mem.eql(u8, engine, "v8")) {
    exe.linkLibCpp();
    exe.linkSystemLibrary("v8_monolith");
} else if (std.mem.eql(u8, engine, "jsc")) {
    exe.linkFramework("JavaScriptCore");
}
```

## Implementation Requirements

### 1. Engine Selection Option in build.zig
```zig
pub fn build(b: *std.Build) void {
    const target = b.standardTargetOptions(.{});
    const optimize = b.standardOptimizeOption(.{});

    // Engine selection option
    const engine_choice = b.option(
        []const u8,
        "engine",
        "JavaScript engine backend: v8, jsc, quickjs (default: v8)",
    ) orelse "v8";

    // Validate engine choice
    const valid_engines = [_][]const u8{ "v8", "jsc", "quickjs" };
    var valid = false;
    for (valid_engines) |e| {
        if (std.mem.eql(u8, engine_choice, e)) {
            valid = true;
            break;
        }
    }
    if (\!valid) {
        std.debug.panic(
            "Invalid engine '{s}'. Valid options: v8, jsc, quickjs",
            .{engine_choice},
        );
    }

    // Create main executable
    const exe = b.addExecutable(.{
        .name = "whatwg-runtime",
        .root_source_file = b.path("src/main.zig"),
        .target = target,
        .optimize = optimize,
    });

    // Configure engine-specific settings
    configureJSEngine(b, exe, engine_choice, target);

    b.installArtifact(exe);

    // Create engine-specific test configurations
    const test_step = b.step("test", "Run unit tests");
    const unit_tests = b.addTest(.{
        .root_source_file = b.path("src/main.zig"),
        .target = target,
        .optimize = optimize,
    });
    configureJSEngine(b, unit_tests, engine_choice, target);
    test_step.dependOn(&b.addRunArtifact(unit_tests).step);
}
```

### 2. Engine Configuration Function
```zig
fn configureJSEngine(
    b: *std.Build,
    compile: *std.Build.Step.Compile,
    engine: []const u8,
    target: std.Build.ResolvedTarget,
) void {
    // Create build options module
    const options = b.addOptions();

    if (std.mem.eql(u8, engine, "v8")) {
        configureV8(b, compile, options, target);
    } else if (std.mem.eql(u8, engine, "jsc")) {
        configureJSC(b, compile, options, target);
    } else if (std.mem.eql(u8, engine, "quickjs")) {
        configureQuickJS(b, compile, options, target);
    }

    compile.root_module.addOptions("engine_config", options);
}

fn configureV8(
    b: *std.Build,
    compile: *std.Build.Step.Compile,
    options: *std.Build.Step.Options,
    target: std.Build.ResolvedTarget,
) void {
    options.addOption([]const u8, "engine_name", "v8");
    options.addOption(bool, "has_snapshot_support", true);
    options.addOption(bool, "has_isolate_per_thread", true);

    // Link C++ standard library
    compile.linkLibCpp();

    // V8 include paths
    compile.addIncludePath(b.path("libs/v8/include"));

    // V8 library paths
    const v8_lib_path = b.path("libs/v8/lib");
    compile.addLibraryPath(v8_lib_path);

    // Link V8 monolith
    compile.linkSystemLibrary("v8_monolith");

    // Required preprocessor definitions (must match V8 build)
    compile.root_module.addCMacro("V8_COMPRESS_POINTERS", "1");
    compile.root_module.addCMacro("V8_ENABLE_SANDBOX", "1");
    compile.root_module.addCMacro("V8_31BIT_SMIS_ON_64BIT_ARCH", "1");

    // Platform-specific libraries
    const os = target.result.os.tag;
    if (os == .macos) {
        compile.linkFramework("CoreFoundation");
    } else if (os == .linux) {
        compile.linkSystemLibrary("pthread");
        compile.linkSystemLibrary("dl");
    }

    // Add V8 wrapper C++ source
    compile.addCSourceFile(.{
        .file = b.path("src/runtime/engines/v8/v8_wrapper.cpp"),
        .flags = &.{
            "-std=c++17",
            "-fno-exceptions",
            "-DV8_COMPRESS_POINTERS",
            "-DV8_ENABLE_SANDBOX",
        },
    });
}

fn configureJSC(
    b: *std.Build,
    compile: *std.Build.Step.Compile,
    options: *std.Build.Step.Options,
    target: std.Build.ResolvedTarget,
) void {
    options.addOption([]const u8, "engine_name", "jsc");
    options.addOption(bool, "has_snapshot_support", false);
    options.addOption(bool, "has_isolate_per_thread", false);

    compile.linkLibC();

    const os = target.result.os.tag;
    if (os == .macos or os == .ios) {
        // macOS/iOS: Use system JavaScriptCore framework
        compile.linkFramework("JavaScriptCore");
    } else if (os == .linux) {
        // Linux: Use WebKitGTK's JSC
        compile.linkSystemLibrary("javascriptcoregtk-4.0");

        // pkg-config for include paths
        compile.linkSystemLibrary("glib-2.0");
    }
}

fn configureQuickJS(
    b: *std.Build,
    compile: *std.Build.Step.Compile,
    options: *std.Build.Step.Options,
    target: std.Build.ResolvedTarget,
) void {
    options.addOption([]const u8, "engine_name", "quickjs");
    options.addOption(bool, "has_snapshot_support", false);
    options.addOption(bool, "has_isolate_per_thread", false);

    compile.linkLibC();

    // QuickJS include path
    compile.addIncludePath(b.path("libs/quickjs/include"));

    // QuickJS library
    compile.addLibraryPath(b.path("libs/quickjs/lib"));
    compile.linkSystemLibrary("quickjs");

    // Math library for QuickJS
    compile.linkSystemLibrary("m");
}
```

