/// Get engine-specific backend module
pub fn getBackend() type {
    return switch (current_engine) {
        .v8 => @import("engines/v8/engine.zig"),
        .jsc => @import("engines/jsc/engine.zig"),
        .quickjs => @import("engines/quickjs/engine.zig"),
    };
}

