## Overview

Some use cases need weak references to V8 objects that don't prevent garbage collection. Add weak reference support to V8Handle.

## Use Cases

1. **Object caches**: Keep references to JS objects without preventing GC
2. **Event listeners**: Allow JS callbacks to be GC'd when no longer needed
3. **DOM node references**: Don't keep entire DOM tree alive through JS references

## Target Design

```zig
pub const WeakV8Handle = struct {
    inner: *Inner,

    const Inner = struct {
        weak: *v8.Weak,
        isolate: *v8.Isolate,
        allocator: Allocator,
        callback: ?*const fn\(*WeakV8Handle\) void,

        pub fn isAlive\(self: *Inner\) bool {
            return \!v8.v8_Weak_IsEmpty\(self.weak\)\;
        }
    }\;

    pub fn init\(allocator: Allocator, handle: V8Handle\) \!WeakV8Handle {
        const inner = try allocator.create\(Inner\)\;
        const weak = v8.v8_Weak_New\(handle.inner.isolate, handle.toLocal\(\)\)\;
        inner.* = .{
            .weak = weak,
            .isolate = handle.inner.isolate,
            .allocator = allocator,
            .callback = null,
        }\;
        return .{ .inner = inner }\;
    }

    pub fn setCallback\(self: *WeakV8Handle, callback: *const fn\(*WeakV8Handle\) void\) void {
        self.inner.callback = callback\;
        v8.v8_Weak_SetCallback\(self.inner.weak, weakCallback, self\)\;
    }

    pub fn toStrong\(self: WeakV8Handle\) ?V8Handle {
        if \(\!self.inner.isAlive\(\)\) return null\;
        // Convert weak back to strong handle
        return V8Handle.fromWeak\(self\)\;
    }

    pub fn isAlive\(self: WeakV8Handle\) bool {
        return self.inner.isAlive\(\)\;
    }

    pub fn deinit\(self: *WeakV8Handle\) void {
        v8.v8_Weak_Reset\(self.inner.weak\)\;
        self.inner.allocator.destroy\(self.inner\)\;
    }
}\;

fn weakCallback\(weak: *v8.Weak, data: *anyopaque\) callconv\(.C\) void {
    const handle: *WeakV8Handle = @ptrCast\(@alignCast\(data\)\)\;
    if \(handle.inner.callback\) \|cb\| {
        cb\(handle\)\;
    }
}
```

