## Implementation

### Updated httpNetworkFetch
```zig
const curl_backend = @import("../network/curl_backend.zig");
const network_backend = @import("../network/backend.zig");

/// HTTP-network fetch algorithm.
///
/// Per Fetch spec section 4.9:
/// This is where the actual network request happens.
///
/// Steps:
/// 1. Create network backend
/// 2. Build NetworkRequest from InternalRequest
/// 3. Perform network fetch
/// 4. Convert NetworkResponse to InternalResponse
/// 5. Record timing information
pub fn httpNetworkFetch(
    allocator: Allocator,
    params: *FetchParams,
    options: HttpFetchOptions,
) HttpFetchError!*InternalResponse {
    _ = options;
    const request = params.request;

    // Step 1: Create network backend
    const backend_impl = curl_backend.LibcurlBackend.init(allocator) catch {
        return HttpFetchError.NetworkError;
    };
    defer backend_impl.deinit();

    // Step 2: Build NetworkRequest
    var network_request = buildNetworkRequest(allocator, request) catch {
        return HttpFetchError.OutOfMemory;
    };
    defer freeNetworkRequest(allocator, &network_request);

    // Step 3: Perform network fetch
    var network_response = backend_impl.asBackend().send(allocator, &network_request) catch |err| {
        return mapNetworkError(err);
    };
    defer network_response.deinit();

    // Step 4: Convert to InternalResponse
    const response = try convertToInternalResponse(allocator, &network_response, request);

    // Step 5: Record timing
    recordTiming(params.timing_info, &network_response);

    return response;
}
```

### Build NetworkRequest from InternalRequest
```zig
/// Convert InternalRequest to NetworkRequest for the backend.
///
/// Maps Fetch spec request properties to network layer properties.
fn buildNetworkRequest(
    allocator: Allocator,
    request: *InternalRequest,
) !network_backend.NetworkRequest {
    // Build headers array
    var headers = std.ArrayList(network_backend.NetworkRequest.Header).init(allocator);
    errdefer {
        for (headers.items) |h| {
            allocator.free(h.name);
            allocator.free(h.value);
        }
        headers.deinit();
    }

    // Copy headers from InternalRequest
    for (request.header_list.entries.items) |entry| {
        try headers.append(.{
            .name = try allocator.dupe(u8, entry.name),
            .value = try allocator.dupe(u8, entry.value),
        });
    }

    // Extract body bytes if present
    const body_bytes: ?[]const u8 = if (request.body) |body| blk: {
        // For now, assume body has bytes available
        // TODO: Handle streaming bodies
        break :blk body.getBytes();
    } else null;

    return network_backend.NetworkRequest{
        .url = request.currentUrl(),
        .method = request.method,
        .headers = try headers.toOwnedSlice(),
        .body = body_bytes,
        .http_version = .http_1_1, // Default to HTTP/1.1
        .connect_timeout_ms = 30_000, // 30 seconds
        .timeout_ms = 0, // No total timeout by default
        .follow_redirects = false, // Fetch spec handles redirects
        .max_redirects = 20,
        .proxy = null, // TODO: Get from environment/settings
        .cert_options = .{
            .verify_peer = true,
            .verify_host = true,
        },
        .verbose = false,
    };
}

/// Free NetworkRequest resources
fn freeNetworkRequest(allocator: Allocator, request: *network_backend.NetworkRequest) void {
    for (request.headers) |h| {
        allocator.free(h.name);
        allocator.free(h.value);
    }
    allocator.free(request.headers);
}
```

### Convert NetworkResponse to InternalResponse
```zig
/// Convert NetworkResponse to InternalResponse.
///
/// Creates a Fetch spec compliant InternalResponse from the
/// network layer response.
fn convertToInternalResponse(
    allocator: Allocator,
    network_response: *network_backend.NetworkResponse,
    request: *InternalRequest,
) HttpFetchError!*InternalResponse {
    const response = InternalResponse.init(allocator) catch {
        return HttpFetchError.OutOfMemory;
    };
    errdefer response.deinit();

    // Set status
    response.status = network_response.status;

    // Copy headers
    for (network_response.headers) |header| {
        response.header_list.append(header.name, header.value) catch {
            return HttpFetchError.OutOfMemory;
        };
    }

    // Set body if present
    if (network_response.body) |body| {
        response.body = Body.fromBytes(allocator, body) catch {
            return HttpFetchError.OutOfMemory;
        };
    }

    // Set URL (final URL after any redirects, or request URL)
    const url = network_response.final_url orelse request.currentUrl();
    response.addUrl(url) catch {
        return HttpFetchError.OutOfMemory;
    };

    return response;
}
```

### Error Mapping
```zig
/// Map NetworkError to HttpFetchError.
fn mapNetworkError(err: network_backend.NetworkError) HttpFetchError {
    return switch (err) {
        .OutOfMemory => HttpFetchError.OutOfMemory,
        .DnsResolutionFailed,
        .ConnectionRefused,
        .ConnectionTimeout,
        .RequestTimeout,
        .SslHandshakeFailed,
        .SslCertificateError,
        .TooManyRedirects,
        .InvalidUrl,
        .Aborted,
        .NetworkUnreachable,
        .HostUnreachable,
        .ConnectionReset,
        .ProtocolError,
        .Unknown,
        => HttpFetchError.NetworkError,
    };
}
```

### Timing Recording
```zig
/// Record timing information from network response.
///
/// Per Resource Timing spec, captures:
/// - Response start time
/// - Response end time
fn recordTiming(
    timing_info: *FetchTimingInfo,
    network_response: *network_backend.NetworkResponse,
) void {
    const now = getCurrentTimeMs();

    // Time to first byte
    if (network_response.time_to_first_byte_ms > 0) {
        timing_info.final_network_response_start_time = 
            now - @as(f64, @floatFromInt(network_response.total_time_ms)) +
            @as(f64, @floatFromInt(network_response.time_to_first_byte_ms));
    }

    timing_info.end_time = now;
}
```

