    const original_ptr: *const anyopaque = @ptrFromInt\(0x12345670\)\;

    for \([_]PointerTag{ .untagged, .global_handle, .runtime_instance, .local_value }\) \|tag\| {
        const tagged = pointer_tag.tagPointer\(original_ptr, tag\)\;
        const untagged = pointer_tag.untagPointer\(tagged\)\;

