### 3. Trigger Context Creation on Load

```zig
// When iframe loads content \(src or srcdoc\)

pub fn onNavigationComplete\(self: *IFrameIntegration\) \!void {
    // Create realm if not exists
    if \(self.realm == null\) {
        const isolate = v8.v8_Isolate_GetCurrent\(\)\;
        const parent_ctx = v8.v8_Isolate_GetCurrentContext\(isolate\)\;
        try self.createRealmAndContext\(parent_ctx, isolate, self.allocator\)\;
    }

    // Create Document in iframe's realm
    try self.createDocumentInRealm\(\)\;

