### 4. Handle Context Cleanup

```zig
pub fn onRemovedFromDocument\(self: *IFrameIntegration\) void {
    // Clean up V8 context
    if \(self.realm\) \|realm\| {
        const entry = context_manager.getEntry\(self.v8_context.?\)\;
        if \(entry\) \|e\| {
            context_manager.destroyChildContext\(e, self.allocator\)\;
        }
    }
    self.realm = null\;
    self.v8_context = null\;

    // Clean up browsing context
    if \(self.browsing_context\) \|ctx\| {
        ctx.close\(\)\;
    }
}
