## Summary
Implement the async Promise-returning methods `Blob.text()`, `Blob.arrayBuffer()`, and `Blob.bytes()` that consume the blob stream and return the data in different formats.

## Spec Reference
- W3C File API §3.3.3: The text() method
- W3C File API §3.3.4: The arrayBuffer() method
- W3C File API §3.3.5: The bytes() method
- https://www.w3.org/TR/FileAPI/#text-method-algo

## Algorithms (from spec)

### text() method (§3.3.3)
1. Let `stream` be the result of calling get stream on this.
2. Let `reader` be the result of getting a reader from stream. If that threw an exception, return a new promise rejected with that exception.
3. Let `promise` be the result of reading all bytes from stream with reader.
4. Return the result of transforming promise by a fulfillment handler that returns the result of running UTF-8 decode on its first argument.

### arrayBuffer() method (§3.3.4)
1. Let `stream` be the result of calling get stream on this.
2. Let `reader` be the result of getting a reader from stream. If that threw an exception, return a new promise rejected with that exception.
3. Let `promise` be the result of reading all bytes from stream with reader.
4. Return the result of transforming promise by a fulfillment handler that returns a new ArrayBuffer whose contents are its first argument.

### bytes() method (§3.3.5)
1. Let `stream` be the result of calling get stream on this.
2. Let `reader` be the result of getting a reader from stream. If that threw an exception, return a new promise rejected with that exception.
3. Let `promise` be the result of reading all bytes from stream with reader.
4. Return the result of transforming promise by a fulfillment handler that returns a new Uint8Array wrapping an ArrayBuffer containing its first argument.

## Implementation

```zig
const std = @import("std");
const streams = @import("streams");
const encoding = @import("encoding");
const runtime = @import("runtime");
const async_promise = @import("streams/internal/async_promise.zig");

/// Read all bytes from a stream
/// Helper function implementing "read all bytes" operation
fn readAllBytes(
    allocator: std.mem.Allocator,
    stream: *runtime.Instance,
) ![]u8 {
    // Get a reader from stream
    const reader = try streams.interfaces.ReadableStream.call_getReader(stream, .{});

    var bytes = std.ArrayList(u8).init(allocator);
    errdefer bytes.deinit();

    // Read all chunks
    while (true) {
        const result = try streams.interfaces.ReadableStreamDefaultReader.call_read(reader);
        if (result.done) break;

        // Append chunk bytes
        try bytes.appendSlice(result.value);
    }

    // Release the reader lock
    try streams.interfaces.ReadableStreamDefaultReader.call_releaseLock(reader);

    return bytes.toOwnedSlice();
}

/// Blob.text() implementation
/// Returns a Promise that resolves to a USVString (UTF-8 decoded)
pub fn blobText(
    allocator: std.mem.Allocator,
    ctx: runtime.Context,
    blob_data: *const BlobData,
    event_loop: *EventLoop,
) !*async_promise.AsyncPromise([]const u8) {
    const promise = try async_promise.AsyncPromise([]const u8).init(allocator, event_loop);

    // Queue the async operation
    event_loop.queueTask(.{
        .callback = struct {
            fn execute(context: *anyopaque) void {
                const state = @as(*TextReadState, @ptrCast(@alignCast(context)));

                // Step 1: Get stream
                const stream = createBlobStream(state.allocator, state.ctx, state.blob_data) catch |err| {
                    state.promise.reject(makeException(err));
                    return;
                };
                defer stream.deinit();

                // Step 2-3: Read all bytes
                const bytes = readAllBytes(state.allocator, stream) catch |err| {
                    state.promise.reject(makeException(err));
                    return;
                };
                defer state.allocator.free(bytes);

                // Step 4: UTF-8 decode
                // Note: text() always uses UTF-8, unlike FileReader.readAsText()
                const text = encoding.utf8Decode(state.allocator, bytes) catch |err| {
                    state.promise.reject(makeException(err));
                    return;
                };

                state.promise.fulfill(text);
            }
        }.execute,
        .context = &TextReadState{
            .allocator = allocator,
            .ctx = ctx,
            .blob_data = blob_data,
            .promise = promise,
        },
    });

    return promise;
}

/// Blob.arrayBuffer() implementation
/// Returns a Promise that resolves to an ArrayBuffer
pub fn blobArrayBuffer(
    allocator: std.mem.Allocator,
    ctx: runtime.Context,
    blob_data: *const BlobData,
    event_loop: *EventLoop,
) !*async_promise.AsyncPromise(*runtime.ArrayBuffer) {
    const promise = try async_promise.AsyncPromise(*runtime.ArrayBuffer).init(allocator, event_loop);

    event_loop.queueTask(.{
        .callback = struct {
            fn execute(context: *anyopaque) void {
                const state = @as(*ArrayBufferReadState, @ptrCast(@alignCast(context)));

                // Get stream
                const stream = createBlobStream(state.allocator, state.ctx, state.blob_data) catch |err| {
                    state.promise.reject(makeException(err));
                    return;
                };
                defer stream.deinit();

                // Read all bytes
                const bytes = readAllBytes(state.allocator, stream) catch |err| {
                    state.promise.reject(makeException(err));
                    return;
                };

                // Create ArrayBuffer with the bytes
                const array_buffer = runtime.ArrayBuffer.create(state.ctx, bytes) catch |err| {
                    state.allocator.free(bytes);
                    state.promise.reject(makeException(err));
                    return;
                };

                state.promise.fulfill(array_buffer);
            }
        }.execute,
        .context = &ArrayBufferReadState{...},
    });

    return promise;
}

/// Blob.bytes() implementation
/// Returns a Promise that resolves to a Uint8Array
pub fn blobBytes(
    allocator: std.mem.Allocator,
    ctx: runtime.Context,
    blob_data: *const BlobData,
    event_loop: *EventLoop,
) !*async_promise.AsyncPromise(*runtime.Uint8Array) {
    const promise = try async_promise.AsyncPromise(*runtime.Uint8Array).init(allocator, event_loop);

    event_loop.queueTask(.{
        .callback = struct {
            fn execute(context: *anyopaque) void {
                const state = @as(*BytesReadState, @ptrCast(@alignCast(context)));

                // Get stream
                const stream = createBlobStream(state.allocator, state.ctx, state.blob_data) catch |err| {
                    state.promise.reject(makeException(err));
                    return;
                };
                defer stream.deinit();

                // Read all bytes
                const bytes = readAllBytes(state.allocator, stream) catch |err| {
                    state.promise.reject(makeException(err));
                    return;
                };

                // Create Uint8Array wrapping ArrayBuffer
                const uint8_array = runtime.Uint8Array.create(state.ctx, bytes) catch |err| {
                    state.allocator.free(bytes);
                    state.promise.reject(makeException(err));
                    return;
                };

                state.promise.fulfill(uint8_array);
            }
        }.execute,
        .context = &BytesReadState{...},
    });

    return promise;
}
```

