### 6. Zig Engine Integration (engine.zig)
```zig
pub const ScriptError = struct {
    message: []const u8,
    stack_trace: ?[]const u8,
    line_number: ?i32,
    column_number: ?i32,
    source_line: ?[]const u8,
    resource_name: ?[]const u8,

    pub fn deinit(self: *ScriptError, allocator: Allocator) void {
        allocator.free(self.message);
        if (self.stack_trace) |s| allocator.free(s);
        // ... free other fields
    }
};

fn v8RunScript(engine_ctx: *anyopaque, script: *anyopaque) EngineError\!?*anyopaque {
    var error_info: ?*ffi.V8ErrorInfo = null;

    const result = ffi.v8_Script_Run_Safe(context, v8_script, &error_info);

    if (error_info) |info| {
        defer ffi.v8_FreeErrorInfo(info);

        // Log detailed error
        if (info.message) |msg| {
            const msg_slice = std.mem.span(msg);
            std.log.err("Script error: {s}", .{msg_slice});
        }
        if (info.stack_trace) |stack| {
            std.log.err("Stack trace:\n{s}", .{std.mem.span(stack)});
        }

        return EngineError.ScriptError;
    }

    return @ptrCast(result);
}
