// New function to create iframe context
pub fn createChildContext\(
    parent_context: v8.Context,
    isolate: v8.Isolate,
    browsing_context: *BrowsingContext,
\) \!*ContextEntry {
    // 1. Create new V8 context
    const global_template = v8.v8_ObjectTemplate_New\(isolate\)\;
    v8.v8_ObjectTemplate_SetImmutableProto\(global_template\)\;
    const child_context = v8.v8_Context_NewWithGlobalTemplate\(isolate, global_template\)\;

    // 2. Initialize all interface bindings in new context
    interface_bindings.initializeBindings\(isolate, child_context\)\;

    // 3. Create realm with new context
    const realm = try Realm.init\(allocator, child_context, browsing_context\)\;

    // 4. Register in context manager
    return try getOrCreateWithRealm\(child_context, isolate, realm, allocator\)\;
}
```

