// Brand check must throw from callee's realm
pub fn validateBrand\(this: *Instance, expected_interface: type\) \!void {
    if \(\!this.isInstanceOf\(expected_interface\)\) {
        // Get the realm of the METHOD being called, not the caller
        const method_realm = getCurrentMethodRealm\(\)\;
        return method_realm.throwTypeError\("Illegal invocation"\)\;
