## Summary
Implement the `convert line endings to native` algorithm in `src/file/algorithms/line_endings.zig`. This algorithm is used when creating Blobs with `endings: "native"` option.

## Spec Reference
- W3C File API §3.1.1: Constructor Parameters
- https://www.w3.org/TR/FileAPI/#constructorParams
- Algorithm: specs/algorithms/FileAPI.json -> "convert-line-endings-to-native"

## Algorithm (from spec)

To **convert line endings to native** in a string `s`, run the following steps:

1. Let `native line ending` be the code point U+000A LF.
2. If the underlying platform's conventions are to represent newlines as a carriage return and line feed sequence, set `native line ending` to the code point U+000D CR followed by the code point U+000A LF.
3. Set `result` to the empty string.
4. Let `position` be a position variable for `s`, initially pointing at the start of `s`.
5. Let `token` be the result of collecting a sequence of code points that are not equal to U+000A LF or U+000D CR from `s` given `position`.
6. Append `token` to `result`.
7. While `position` is not past the end of `s`:
   a. If the code point at `position` within `s` equals U+000D CR:
      i. Append `native line ending` to `result`.
      ii. Advance `position` by 1.
      iii. If `position` is not past the end of `s` and the code point at `position` within `s` equals U+000A LF advance `position` by 1.
   b. Otherwise if the code point at `position` within `s` equals U+000A LF, advance `position` by 1 and append `native line ending` to `result`.
   c. Let `token` be the result of collecting a sequence of code points that are not equal to U+000A LF or U+000D CR from `s` given `position`.
   d. Append `token` to `result`.
8. Return `result`.

## Implementation

```zig
const std = @import("std");
const builtin = @import("builtin");

/// Native line ending for the current platform
pub const native_line_ending: []const u8 = switch (builtin.os.tag) {
    .windows => "\r\n",
    else => "\n", // Unix, macOS, Linux, etc.
};

/// Convert line endings to native per W3C File API spec §3.1.1
///
/// Handles three input line ending formats:
/// - LF (\n) - Unix style
/// - CR (\r) - Old Mac style
/// - CRLF (\r\n) - Windows style
///
/// All are converted to the platform's native line ending.
///
/// Returns owned slice that caller must free, or the original slice
/// if no conversion was needed (caller should check pointer equality).
pub fn convertLineEndingsToNative(
    allocator: std.mem.Allocator,
    s: []const u8,
) ![]const u8 {
    // Quick check: if no line endings present, return original
    if (std.mem.indexOfAny(u8, s, "\r\n") == null) {
        return s;
    }

    var result = std.ArrayList(u8).init(allocator);
    errdefer result.deinit();

    // Pre-allocate approximate size (may need more for CRLF on Unix or less for Unix on Windows)
    try result.ensureTotalCapacity(s.len);

    // Step 4: Let position be a position variable for s
    var position: usize = 0;

    // Step 5-6: Collect initial non-line-ending characters
    const initial_end = findLineEnding(s, position);
    try result.appendSlice(s[position..initial_end]);
    position = initial_end;

    // Step 7: While position is not past the end of s
    while (position < s.len) {
        const char = s[position];

        // Step 7a: If code point at position equals U+000D CR
        if (char == '\r') {
            // Step 7a.i: Append native line ending to result
            try result.appendSlice(native_line_ending);

            // Step 7a.ii: Advance position by 1
            position += 1;

            // Step 7a.iii: If next char is LF, advance position by 1 (skip CRLF pair)
            if (position < s.len and s[position] == '\n') {
                position += 1;
            }
        }
        // Step 7b: Otherwise if code point equals U+000A LF
        else if (char == '\n') {
            // Advance position by 1 and append native line ending
            position += 1;
            try result.appendSlice(native_line_ending);
        }

        // Step 7c-d: Collect next token of non-line-ending characters
        const token_end = findLineEnding(s, position);
        try result.appendSlice(s[position..token_end]);
        position = token_end;
    }

    // Step 8: Return result
    return result.toOwnedSlice();
}

/// Find the next CR or LF character, or return end of string
fn findLineEnding(s: []const u8, start: usize) usize {
    var i = start;
    while (i < s.len) : (i += 1) {
        if (s[i] == '\r' or s[i] == '\n') {
            return i;
        }
    }
    return s.len;
}
```

## Test Cases

```zig
const testing = std.testing;

test "no conversion needed - no line endings" {
    const allocator = testing.allocator;
    const input = "hello world";
    const result = try convertLineEndingsToNative(allocator, input);
    // Should return same pointer (no allocation)
    try testing.expectEqual(input.ptr, result.ptr);
}

test "convert LF to native" {
    const allocator = testing.allocator;
    const input = "line1\nline2\nline3";
    const result = try convertLineEndingsToNative(allocator, input);
    defer allocator.free(result);

    const expected = "line1" ++ native_line_ending ++ "line2" ++ native_line_ending ++ "line3";
    try testing.expectEqualStrings(expected, result);
}

test "convert CR to native" {
    const allocator = testing.allocator;
    const input = "line1\rline2\rline3";
    const result = try convertLineEndingsToNative(allocator, input);
    defer allocator.free(result);

    const expected = "line1" ++ native_line_ending ++ "line2" ++ native_line_ending ++ "line3";
    try testing.expectEqualStrings(expected, result);
}

test "convert CRLF to native" {
    const allocator = testing.allocator;
    const input = "line1\r\nline2\r\nline3";
    const result = try convertLineEndingsToNative(allocator, input);
    defer allocator.free(result);

    const expected = "line1" ++ native_line_ending ++ "line2" ++ native_line_ending ++ "line3";
    try testing.expectEqualStrings(expected, result);
}

test "convert mixed line endings" {
    const allocator = testing.allocator;
    // Mix of LF, CR, and CRLF
    const input = "line1\nline2\rline3\r\nline4";
    const result = try convertLineEndingsToNative(allocator, input);
    defer allocator.free(result);

    const expected = "line1" ++ native_line_ending ++
                     "line2" ++ native_line_ending ++
                     "line3" ++ native_line_ending ++
                     "line4";
    try testing.expectEqualStrings(expected, result);
}

test "empty string" {
    const allocator = testing.allocator;
    const input = "";
    const result = try convertLineEndingsToNative(allocator, input);
    try testing.expectEqual(input.ptr, result.ptr);
}

test "only line endings" {
    const allocator = testing.allocator;
    const input = "\n\r\n\r";
    const result = try convertLineEndingsToNative(allocator, input);
    defer allocator.free(result);

    const expected = native_line_ending ++ native_line_ending ++ native_line_ending;
    try testing.expectEqualStrings(expected, result);
}

test "line ending at start" {
    const allocator = testing.allocator;
    const input = "\nhello";
    const result = try convertLineEndingsToNative(allocator, input);
    defer allocator.free(result);

    try testing.expectEqualStrings(native_line_ending ++ "hello", result);
}

test "line ending at end" {
    const allocator = testing.allocator;
    const input = "hello\n";
    const result = try convertLineEndingsToNative(allocator, input);
    defer allocator.free(result);

    try testing.expectEqualStrings("hello" ++ native_line_ending, result);
}

test "consecutive CRLFs" {
    const allocator = testing.allocator;
    const input = "a\r\n\r\nb";
    const result = try convertLineEndingsToNative(allocator, input);
    defer allocator.free(result);

    const expected = "a" ++ native_line_ending ++ native_line_ending ++ "b";
    try testing.expectEqualStrings(expected, result);
}
```

## Platform Considerations

| Platform | Native Line Ending | Code |
|----------|-------------------|------|
| Windows | CRLF (\r\n) | U+000D U+000A |
| Unix/Linux | LF (\n) | U+000A |
| macOS | LF (\n) | U+000A |
| Classic Mac OS | CR (\r) | U+000D (historical, not supported) |

