Refactor async iterator callbacks in streams to use typed callback patterns.

## Current Pattern

```zig
// tests/streams_from_test.zig:30
fn next\(ctx: *anyopaque\) \!?common.JSValue {
    const self = @as\(*MockAsyncIterator, @ptrCast\(@alignCast\(ctx\)\)\)\;
    // ...
}

fn return_fn\(ctx: *anyopaque, reason: ?common.JSValue\) \!void {
    const self = @as\(*MockAsyncIterator, @ptrCast\(@alignCast\(ctx\)\)\)\;
    // ...
}

fn deinit\(ctx: *anyopaque\) void {
    const self = @as\(*MockAsyncIterator, @ptrCast\(@alignCast\(ctx\)\)\)\;
    // ...
}
```

## Proposed Pattern

```zig
// Typed async iterator interface
pub fn TypedAsyncIterator\(comptime Context: type\) type {
    return struct {
        context: *Context,

        // Typed callbacks
        next_fn: *const fn \(*Context\) \!?JSValue,
        return_fn: ?*const fn \(*Context, ?JSValue\) \!void = null,
        deinit_fn: ?*const fn \(*Context\) void = null,

        pub fn next\(self: @This\(\)\) \!?JSValue {
            return self.next_fn\(self.context\)\;
        }

        pub fn returnWith\(self: @This\(\), reason: ?JSValue\) \!void {
            if \(self.return_fn\) \|f\| {
                return f\(self.context, reason\)\;
            }
        }
    }\;
}
```

