fn calculateTotalTests\(discovery: DiscoveryResult, allocator: std.mem.Allocator, wpt_root: []const u8\) \!usize {
    var total: usize = 0\;

    for \(discovery.test_files.items\) \|test_file\| {
        // Parse to get globals count
        const full_path = try std.fs.path.join\(allocator, \&.{ wpt_root, test_file.path }\)\;
        defer allocator.free\(full_path\)\;

        const content = try std.fs.cwd\(\).readFileAlloc\(allocator, full_path, 10 * 1024 * 1024\)\;
        defer allocator.free\(content\)\;

        var parsed = try test_parser.parseTestFile\(allocator, test_file.path, content\)\;
        defer parsed.deinit\(\)\;

        // Count implemented contexts only
        for \(parsed.metadata.globals.items\) \|ctx\| {
            if \(ctx.isImplemented\(\)\) {
                total += 1\;
