```zig
const std = @import("std");
const types = @import("types.zig");
const policy = @import("policy.zig");
const sink_type_map = @import("sink_type_map.zig");

/// TrustedTypePolicyFactory - Creates policies and provides type checking.
/// Exposed to JavaScript as window.trustedTypes / self.trustedTypes.
/// Spec: https://w3c.github.io/trusted-types/dist/spec/#trusted-type-policy-factory
pub const TrustedTypePolicyFactory = struct {
    /// Associated default policy (initially null)
    /// Set when a policy named 'default' is created
    default_policy: ?*policy.TrustedTypePolicy = null,

    /// Set of policy names that have been created
    /// Used to enforce unique policy names when CSP requires it
    created_policy_names: std.StringHashMap(void),

    /// Pre-created empty instances
    /// Spec: emptyHTML and emptyScript are readonly attributes
    empty_html: *types.TrustedHTML,
    empty_script: *types.TrustedScript,

    allocator: std.mem.Allocator,

    /// Initialize factory with empty type instances
    pub fn init(allocator: std.mem.Allocator) !*TrustedTypePolicyFactory {
        const factory = try allocator.create(TrustedTypePolicyFactory);

        // Create emptyHTML - TrustedHTML with empty string
        const empty_html = try allocator.create(types.TrustedHTML);
        empty_html.* = .{
            .data = "",
            .allocator = allocator,
        };

        // Create emptyScript - TrustedScript with empty string
        const empty_script = try allocator.create(types.TrustedScript);
        empty_script.* = .{
            .data = "",
            .allocator = allocator,
        };

        factory.* = .{
            .default_policy = null,
            .created_policy_names = std.StringHashMap(void).init(allocator),
            .empty_html = empty_html,
            .empty_script = empty_script,
            .allocator = allocator,
        };

        return factory;
    }

    /// Create a Trusted Type Policy.
    /// Spec: https://w3c.github.io/trusted-types/dist/spec/#dom-trustedtypepolicyfactory-createpolicy
    ///
    /// Algorithm (Create a Trusted Type Policy):
    /// 1. Let global be factory's relevant global object
    /// 2. If options is empty:
    ///    a. Set options to a new TrustedTypePolicyOptions
    /// 3. Let allowedByCSP be result of 'Should Trusted Type policy creation be blocked by CSP?'
    ///    with policyName, global, and 'enforce' (false for duplicates allowed case)
    /// 4. If allowedByCSP is 'Blocked':
    ///    a. Throw TypeError
    /// 5. Let policy be new TrustedTypePolicy with name=policyName, options=options
    /// 6. Append policyName to factory's created policy names
    /// 7. If policyName is 'default':
    ///    a. Set factory's default policy to policy
    /// 8. Return policy
    pub fn createPolicy(
        self: *TrustedTypePolicyFactory,
        policy_name: []const u8,
        options: policy.TrustedTypePolicyOptions,
    ) !*policy.TrustedTypePolicy {
        // TODO: CSP check - 'Should Trusted Type policy creation be blocked by CSP?'
        // For now, skip CSP check (will be added when CSP module is ready)

        // Check for duplicate policy names (if unique names required)
        // This will be controlled by CSP 'allow-duplicates' keyword
        if (self.created_policy_names.contains(policy_name)) {
            return error.TypeError; // Duplicate policy name
        }

        // Create the policy
        const new_policy = try self.allocator.create(policy.TrustedTypePolicy);
        new_policy.* = .{
            .name = try self.allocator.dupe(u8, policy_name),
            .options = options,
            .allocator = self.allocator,
        };

        // Track created policy name
        try self.created_policy_names.put(try self.allocator.dupe(u8, policy_name), {});

        // Set default policy if name is 'default'
        if (std.mem.eql(u8, policy_name, "default")) {
            self.default_policy = new_policy;
        }

        return new_policy;
    }

    /// Check if value is a valid TrustedHTML instance.
    /// Returns true if value is TrustedHTML with data set, false otherwise.
    /// Used to detect forgery via Object.create or prototype manipulation.
    pub fn isHTML(self: *const TrustedTypePolicyFactory, value: anytype) bool {
        _ = self;
        // Check if value is a TrustedHTML instance with data set
        return @TypeOf(value) == *types.TrustedHTML;
    }

    /// Check if value is a valid TrustedScript instance.
    pub fn isScript(self: *const TrustedTypePolicyFactory, value: anytype) bool {
        _ = self;
        return @TypeOf(value) == *types.TrustedScript;
    }

    /// Check if value is a valid TrustedScriptURL instance.
    pub fn isScriptURL(self: *const TrustedTypePolicyFactory, value: anytype) bool {
        _ = self;
        return @TypeOf(value) == *types.TrustedScriptURL;
    }

    /// Get the required Trusted Type for an element's property.
    /// Returns "TrustedHTML", "TrustedScript", "TrustedScriptURL", or null.
    pub fn getPropertyType(
        self: *const TrustedTypePolicyFactory,
        tag_name: []const u8,
        property: []const u8,
        element_ns: ?[]const u8,
    ) ?[]const u8 {
        _ = self;
        return sink_type_map.getPropertyType(tag_name, property, element_ns);
    }

    /// Get the required Trusted Type for an element's attribute.
    /// Returns "TrustedHTML", "TrustedScript", "TrustedScriptURL", or null.
    pub fn getAttributeType(
        self: *const TrustedTypePolicyFactory,
        tag_name: []const u8,
        attribute: []const u8,
        element_ns: ?[]const u8,
        attr_ns: ?[]const u8,
    ) ?[]const u8 {
        _ = self;
        return sink_type_map.getAttributeType(tag_name, attribute, element_ns, attr_ns);
    }

    pub fn deinit(self: *TrustedTypePolicyFactory) void {
        // Clean up created policy names
        var iter = self.created_policy_names.keyIterator();
        while (iter.next()) |key| {
            self.allocator.free(key.*);
        }
        self.created_policy_names.deinit();

        // Clean up empty instances (unless they're empty strings)
        if (self.empty_html.data.len > 0) {
            self.empty_html.deinit();
        }
        self.allocator.destroy(self.empty_html);

        if (self.empty_script.data.len > 0) {
            self.empty_script.deinit();
        }
        self.allocator.destroy(self.empty_script);

        self.allocator.destroy(self);
    }
};
```

## Key Implementation Details

1. **Singleton per Realm**: One factory per Window/Worker global scope
2. **Policy Name Tracking**: Track created names to enforce uniqueness
3. **Default Policy**: Special handling for policy named 'default'
4. **Empty Instances**: Pre-create emptyHTML and emptyScript
5. **Type Checking**: isHTML/isScript/isScriptURL detect forgery
6. **CSP Integration**: createPolicy checks CSP (placeholder for now)

