## Summary

Create `StoredError` type to replace all `stored_error: ?*anyopaque` patterns in stream implementations.

## Problem

Currently streams store errors as:
```zig
stored_error: ?*anyopaque  // Could be V8 exception, Zig error, or garbage
```

This is used in:
- ReadableStream.zig \(stored_error field\)
- WritableStream.zig \(stored_error field\)
- ReadableStreamDefaultController.zig
- WritableStreamDefaultController.zig
- TransformStreamDefaultController.zig

## File to Create

`src/runtime/engines/v8/stored_error.zig`

## Implementation

```zig
const std = @import\("std"\)\;
const v8 = @import\("ffi.zig"\)\;
const GlobalHandle = @import\("global_handles.zig"\).GlobalHandle\;
const JSValue = @import\("js_value.zig"\).JSValue\;

/// Type-safe stored error for stream implementations
/// Replaces stored_error: ?*anyopaque
pub const StoredError = union\(enum\) {
    /// No error stored
    none: void,

    /// JavaScript exception \(stored as Global handle\)
    js_exception: GlobalHandle,

    /// Zig error code
    zig_error: anyerror,

    // === Storage ===

    /// Store a JavaScript error value
    pub fn storeJS\(self: *StoredError, value: JSValue, isolate: *v8.Isolate\) \!void {
        // Dispose existing error first
        self.dispose\(\)\;

        switch \(value\) {
            .global =\> \|g\| {
                self.* = .{ .js_exception = g }\;
            },
            .local =\> \|l\| {
                self.* = .{ .js_exception = try l.toGlobal\(isolate\) }\;
            },
            .null, .undefined =\> {
                // null/undefined error - store as none
                self.* = .none\;
            },
            else =\> {
                // Unexpected type - store as generic error
                self.* = .{ .zig_error = error.InvalidErrorType }\;
            },
        }
    }

    /// Store a Zig error
    pub fn storeZig\(self: *StoredError, err: anyerror\) void {
        self.dispose\(\)\;
        self.* = .{ .zig_error = err }\;
    }

    /// Store from legacy anyopaque \(for migration\)
    pub fn storeAnyopaque\(self: *StoredError, ptr: ?*anyopaque, isolate: *v8.Isolate\) \!void {
        if \(ptr\) \|p\| {
            const js_value = JSValue.fromAnyopaque\(p\)\;
            try self.storeJS\(js_value, isolate\)\;
        } else {
            self.* = .none\;
        }
    }

    // === Retrieval ===

    /// Check if an error is stored
    pub fn hasError\(self: StoredError\) bool {
        return self \!= .none\;
    }

    /// Get as JSValue for rejection/throwing
    pub fn toJSValue\(self: StoredError, isolate: *v8.Isolate\) JSValue {
        return switch \(self\) {
            .none =\> .{ .undefined = {} },
            .js_exception =\> \|g\| .{ .global = g },
            .zig_error =\> \|e\| {
                // Convert Zig error to JS Error object
                const msg = @errorName\(e\)\;
                const js_error = v8.v8_Error_New\(isolate, msg.ptr, msg.len\)\;
                return .{ .local = .{ .raw = js_error } }\;
            },
        }\;
    }

    /// Get as V8 Value for FFI
    pub fn toV8\(self: StoredError, isolate: *v8.Isolate\) ?*v8.Value {
        return switch \(self\) {
            .none =\> null,
            .js_exception =\> \|g\| g.get\(isolate\),
            .zig_error =\> \|e\| {
                const msg = @errorName\(e\)\;
                return v8.v8_Error_New\(isolate, msg.ptr, msg.len\)\;
            },
        }\;
    }

    /// Get as legacy anyopaque \(for migration\)
    pub fn toAnyopaque\(self: StoredError\) ?*anyopaque {
        return switch \(self\) {
            .none =\> null,
            .js_exception =\> \|g\| g.ptr,
            .zig_error =\> null, // Can't represent as pointer
        }\;
    }

    // === Promise Integration ===

    /// Reject a promise with this error
    pub fn rejectPromise\(self: StoredError, isolate: *v8.Isolate, promise: *v8.Promise\) void {
        if \(self.toV8\(isolate\)\) \|error_value\| {
            v8.v8_Promise_Reject\(promise, error_value\)\;
        }
    }

    // === Lifecycle ===

    /// Dispose stored error \(releases Global handle if any\)
    pub fn dispose\(self: *StoredError\) void {
        if \(self.* == .js_exception\) {
            var handle = self.js_exception\;
            handle.dispose\(\)\;
        }
        self.* = .none\;
    }

    /// Clone the stored error \(creates new Global handle\)
    pub fn clone\(self: StoredError, isolate: *v8.Isolate\) \!StoredError {
        return switch \(self\) {
            .none =\> .none,
            .js_exception =\> \|g\| {
                const local = g.get\(isolate\)\;
                const new_global = try GlobalHandle.create\(isolate, local\)\;
                return .{ .js_exception = new_global }\;
            },
            .zig_error =\> \|e\| .{ .zig_error = e },
        }\;
    }
}\;

// === Tests ===

test "StoredError none" {
    var err = StoredError{ .none = {} }\;
    try std.testing.expect\(\!err.hasError\(\)\)\;
    try std.testing.expect\(err.toAnyopaque\(\) == null\)\;
}

test "StoredError zig error" {
    var err = StoredError{ .none = {} }\;
    err.storeZig\(error.OutOfMemory\)\;

    try std.testing.expect\(err.hasError\(\)\)\;
    try std.testing.expect\(err == .zig_error\)\;
    try std.testing.expect\(err.zig_error == error.OutOfMemory\)\;

    err.dispose\(\)\;
    try std.testing.expect\(\!err.hasError\(\)\)\;
}
```

