Implement the mechanism to detect cookie changes and fire CookieChangeEvent.

## Background
When cookies change (via set/delete operations or from HTTP responses), we need to:
1. Detect what changed
2. Create appropriate CookieChangeEvent
3. Dispatch to all registered listeners

## Files to Modify
- src/fetch/network/curl_cookies.zig
- src/webidl/impls/CookieStore.zig

## Change Detection Strategy

### Option 1: Track Changes in CurlCookieManager (Recommended)

```zig
// In CurlCookieManager

/// Callback type for cookie change notifications
pub const CookieChangeCallback = *const fn (
    changed: []const Cookie,
    deleted: []const Cookie,
    context: ?*anyopaque,
) void;

/// Registered change listeners
change_listeners: std.ArrayList(ChangeListener),

const ChangeListener = struct {
    callback: CookieChangeCallback,
    context: ?*anyopaque,
};

/// Register a callback for cookie changes
pub fn addChangeListener(
    self: *CurlCookieManager,
    callback: CookieChangeCallback,
    context: ?*anyopaque,
) !void {
    try self.change_listeners.append(.{
        .callback = callback,
        .context = context,
    });
}

/// Remove a change listener
pub fn removeChangeListener(
    self: *CurlCookieManager,
    callback: CookieChangeCallback,
) void {
    var i: usize = 0;
    while (i < self.change_listeners.items.len) {
        if (self.change_listeners.items[i].callback == callback) {
            _ = self.change_listeners.orderedRemove(i);
        } else {
            i += 1;
        }
    }
}

/// Notify all listeners of cookie changes
fn notifyListeners(
    self: *CurlCookieManager,
    changed: []const Cookie,
    deleted: []const Cookie,
) void {
    for (self.change_listeners.items) |listener| {
        listener.callback(changed, deleted, listener.context);
    }
}
```

### Modified set() with Change Detection

```zig
pub fn set(
    self: *CurlCookieManager,
    options: CookieInit,
    context_url: ?[]const u8,
) !void {
    // ... validation code ...

    // Check if cookie exists (for change vs add detection)
    const existing = try self.get(options.name, context_url);
    const is_new = existing == null;
    if (existing) |e| e.deinit();

    // Build and set cookie
    const cookie = Cookie{ ... };

    // ... libcurl set code ...

    // Notify listeners
    if (is_new or !cookiesEqual(existing, cookie)) {
        const changed_array = [_]Cookie{cookie};
        self.notifyListeners(&changed_array, &[_]Cookie{});
    }
}

fn cookiesEqual(a: ?Cookie, b: Cookie) bool {
    if (a == null) return false;
    return std.mem.eql(u8, a.?.value, b.value) and
           std.mem.eql(u8, a.?.domain, b.domain) and
           std.mem.eql(u8, a.?.path, b.path) and
           a.?.expires == b.expires and
           a.?.secure == b.secure;
}
```

### Modified delete() with Change Detection

```zig
pub fn delete(
    self: *CurlCookieManager,
    options: CookieDeleteOptions,
    context_url: ?[]const u8,
) !void {
    // Check if cookie exists before deleting
    const existing = try self.get(options.name, context_url);

    if (existing) |cookie| {
        defer cookie.deinit();

        // ... libcurl delete code ...

        // Notify listeners
        const deleted_array = [_]Cookie{cookie};
        self.notifyListeners(&[_]Cookie{}, &deleted_array);
    }
}
