## CookieStore Event Integration

```zig
// In CookieStore

pub fn init(
    allocator: Allocator,
    cookie_manager: *CurlCookieManager,
    context_url: ?[]const u8,
) !*CookieStore {
    const self = try allocator.create(CookieStore);
    // ... existing init ...

    // Register for cookie changes
    try cookie_manager.addChangeListener(onCookieChange, self);

    return self;
}

pub fn deinit(self: *CookieStore) void {
    // Unregister from cookie changes
    self.cookie_manager.removeChangeListener(onCookieChange);

    // ... existing cleanup ...
}

fn onCookieChange(
    changed: []const Cookie,
    deleted: []const Cookie,
    context: ?*anyopaque,
) void {
    const self: *CookieStore = @ptrCast(@alignCast(context.?));

    // Convert to CookieListItem arrays
    var changed_items = std.ArrayList(CookieListItem).init(self.allocator);
    defer {
        for (changed_items.items) |*item| item.deinit(self.allocator);
        changed_items.deinit();
    }

    for (changed) |cookie| {
        changed_items.append(cookieToListItem(self.allocator, cookie)) catch continue;
    }

    var deleted_items = std.ArrayList(CookieListItem).init(self.allocator);
    defer {
        for (deleted_items.items) |*item| item.deinit(self.allocator);
        deleted_items.deinit();
    }

    for (deleted) |cookie| {
        deleted_items.append(cookieToListItem(self.allocator, cookie)) catch continue;
    }

    // Fire event
    self.fireChangeEventInternal(changed_items.items, deleted_items.items) catch {};
}

fn fireChangeEventInternal(
    self: *CookieStore,
    changed: []const CookieListItem,
    deleted: []const CookieListItem,
) !void {
    const CookieChangeEvent = @import("../../dom/events/CookieChangeEvent.zig").CookieChangeEvent;

    const event = try CookieChangeEvent.init(self.allocator, "change", .{
        .changed = changed,
        .deleted = deleted,
    });
    defer event.deinit();

    _ = try self.event_target.dispatchEvent(&event.event);
}
```

