fn invokeTransformAlgorithm\(controller: *InternalState, chunk: *v8.Value, isolate: *v8.Isolate, context: *v8.Context\) \!void {
    const algo = controller.transform_algorithm orelse {
        // Default: just enqueue the chunk unchanged
        return try enqueueInReadable\(controller, chunk\)\;
    }\;

    const transform_func = algo.get\(isolate\) orelse {
        return error.InvalidCallback\;
    }\;

    if \(\!v8.v8_Value_IsFunction\(transform_func\)\) {
        return error.TypeError\;
    }

    // Call transform\(chunk, controller\)
    var args = [_]*v8.Value{ chunk, controller.getV8Controller\(\) }\;
    const result = v8.v8_Function_Call\(@ptrCast\(transform_func\), context, undefined, 2, \&args\)\;

    // Handle promise result...
}
