### Request Configuration
```zig
    /// Configure curl handle with request parameters
    fn configureRequest(self: *Self, request: *const NetworkRequest) NetworkError!void {
        const handle = self.handle;

        // Reset handle for reuse
        curl.curl_easy_reset(handle);

        // URL (null-terminated)
        const url_z = self.allocator.dupeZ(u8, request.url) catch return .OutOfMemory;
        defer self.allocator.free(url_z);
        _ = curl.curl_easy_setopt(handle, curl.CURLOPT_URL, url_z.ptr);

        // HTTP Method
        const method_z = self.allocator.dupeZ(u8, request.method) catch return .OutOfMemory;
        defer self.allocator.free(method_z);
        _ = curl.curl_easy_setopt(handle, curl.CURLOPT_CUSTOMREQUEST, method_z.ptr);

        // Headers
        try self.configureHeaders(request.headers);

        // Request body
        if (request.body) |body| {
            _ = curl.curl_easy_setopt(handle, curl.CURLOPT_POSTFIELDS, body.ptr);
            _ = curl.curl_easy_setopt(handle, curl.CURLOPT_POSTFIELDSIZE_LARGE, @as(c_longlong, @intCast(body.len)));
        }

        // HTTP Version
        const http_ver = switch (request.http_version) {
            .http_1_0 => curl.CURL_HTTP_VERSION_1_0,
            .http_1_1 => curl.CURL_HTTP_VERSION_1_1,
            .http_2 => curl.CURL_HTTP_VERSION_2_0,
            .http_3 => curl.CURL_HTTP_VERSION_3,
        };
        _ = curl.curl_easy_setopt(handle, curl.CURLOPT_HTTP_VERSION, http_ver);

        // Timeouts
        _ = curl.curl_easy_setopt(handle, curl.CURLOPT_CONNECTTIMEOUT_MS, @as(c_long, @intCast(request.connect_timeout_ms)));
        if (request.timeout_ms > 0) {
            _ = curl.curl_easy_setopt(handle, curl.CURLOPT_TIMEOUT_MS, @as(c_long, @intCast(request.timeout_ms)));
        }

        // Don't follow redirects - Fetch spec handles these
        _ = curl.curl_easy_setopt(handle, curl.CURLOPT_FOLLOWLOCATION, @as(c_long, 0));

        // TLS Configuration
        try self.configureTls(request.cert_options);

        // Proxy Configuration
        if (request.proxy) |proxy| {
            try self.configureProxy(proxy);
        }

        // Enable automatic decompression (gzip, deflate)
        _ = curl.curl_easy_setopt(handle, curl.CURLOPT_ACCEPT_ENCODING, "");

        // Verbose mode
        if (request.verbose) {
            _ = curl.curl_easy_setopt(handle, curl.CURLOPT_VERBOSE, @as(c_long, 1));
        }

        // Response callbacks
        _ = curl.curl_easy_setopt(handle, curl.CURLOPT_WRITEFUNCTION, writeCallback);
        _ = curl.curl_easy_setopt(handle, curl.CURLOPT_WRITEDATA, @as(*anyopaque, self));
        _ = curl.curl_easy_setopt(handle, curl.CURLOPT_HEADERFUNCTION, headerCallback);
        _ = curl.curl_easy_setopt(handle, curl.CURLOPT_HEADERDATA, @as(*anyopaque, self));

        // Progress callback for abort support
        _ = curl.curl_easy_setopt(handle, curl.CURLOPT_NOPROGRESS, @as(c_long, 0));
        _ = curl.curl_easy_setopt(handle, curl.CURLOPT_XFERINFOFUNCTION, progressCallback);
        _ = curl.curl_easy_setopt(handle, curl.CURLOPT_XFERINFODATA, @as(*anyopaque, self));
    }

    fn configureHeaders(self: *Self, headers: []const NetworkRequest.Header) NetworkError!void {
        // Free previous header list
        if (self.request_header_list) |list| {
            curl.curl_slist_free_all(list);
            self.request_header_list = null;
        }

        var list: ?*curl.curl_slist = null;
        for (headers) |header| {
            const header_str = std.fmt.allocPrintZ(
                self.allocator,
                "{s}: {s}",
                .{ header.name, header.value },
            ) catch return .OutOfMemory;
            defer self.allocator.free(header_str);

            list = curl.curl_slist_append(list, header_str.ptr);
            if (list == null) return .OutOfMemory;
        }

        self.request_header_list = list;
        if (list) |l| {
            _ = curl.curl_easy_setopt(self.handle, curl.CURLOPT_HTTPHEADER, l);
        }
    }

    fn configureTls(self: *Self, cert: backend.CertVerifyOptions) NetworkError!void {
        const handle = self.handle;

        // Peer verification
        _ = curl.curl_easy_setopt(handle, curl.CURLOPT_SSL_VERIFYPEER, 
            @as(c_long, if (cert.verify_peer) 1 else 0));

        // Host verification (2 = verify hostname matches cert)
        _ = curl.curl_easy_setopt(handle, curl.CURLOPT_SSL_VERIFYHOST,
            @as(c_long, if (cert.verify_host) 2 else 0));

        // CA bundle path
        if (cert.ca_bundle_path) |path| {
            const path_z = self.allocator.dupeZ(u8, path) catch return .OutOfMemory;
            defer self.allocator.free(path_z);
            _ = curl.curl_easy_setopt(handle, curl.CURLOPT_CAINFO, path_z.ptr);
        }

        // Client certificate (mTLS)
        if (cert.client_cert_path) |path| {
            const path_z = self.allocator.dupeZ(u8, path) catch return .OutOfMemory;
            defer self.allocator.free(path_z);
            _ = curl.curl_easy_setopt(handle, curl.CURLOPT_SSLCERT, path_z.ptr);
        }

        // Client private key (mTLS)
        if (cert.client_key_path) |path| {
            const path_z = self.allocator.dupeZ(u8, path) catch return .OutOfMemory;
            defer self.allocator.free(path_z);
            _ = curl.curl_easy_setopt(handle, curl.CURLOPT_SSLKEY, path_z.ptr);
        }
    }

    fn configureProxy(self: *Self, proxy: backend.ProxyConfig) NetworkError!void {
        const handle = self.handle;

        // Proxy URL
        const proxy_z = self.allocator.dupeZ(u8, proxy.url) catch return .OutOfMemory;
        defer self.allocator.free(proxy_z);
        _ = curl.curl_easy_setopt(handle, curl.CURLOPT_PROXY, proxy_z.ptr);

        // Proxy authentication
        if (proxy.username) |user| {
            const auth = if (proxy.password) |pass|
                std.fmt.allocPrintZ(self.allocator, "{s}:{s}", .{ user, pass }) catch return .OutOfMemory
            else
                self.allocator.dupeZ(u8, user) catch return .OutOfMemory;
            defer self.allocator.free(auth);
            _ = curl.curl_easy_setopt(handle, curl.CURLOPT_PROXYUSERPWD, auth.ptr);
        }

        // No-proxy list
        if (proxy.no_proxy) |no_proxy| {
            const np_z = self.allocator.dupeZ(u8, no_proxy) catch return .OutOfMemory;
            defer self.allocator.free(np_z);
            _ = curl.curl_easy_setopt(handle, curl.CURLOPT_NOPROXY, np_z.ptr);
        }
    }
