```zig
    /// Perform the HTTP request and build response
    fn performRequest(self: *Self, allocator: Allocator, request: *const NetworkRequest) NetworkError!NetworkResponse {
        // Reset state
        self.aborted.store(false, .release);
        self.clearResponseData();

        // Configure request
        try self.configureRequest(request);

        // Perform transfer
        const result = curl.curl_easy_perform(self.handle);

        // Check for errors
        if (result != curl.CURLE_OK) {
            return curl_error.mapCurlError(result);
        }

        // Build response
        return try self.buildResponse(allocator);
    }

    fn clearResponseData(self: *Self) void {
        for (self.response_headers.items) |header| {
            self.allocator.free(header.name);
            self.allocator.free(header.value);
        }
        self.response_headers.clearRetainingCapacity();
        self.response_body.clearRetainingCapacity();
    }

    fn buildResponse(self: *Self, allocator: Allocator) NetworkError!NetworkResponse {
        const handle = self.handle;

        // Status code
        var status: c_long = 0;
        _ = curl.curl_easy_getinfo(handle, curl.CURLINFO_RESPONSE_CODE, &status);

        // HTTP version
        var http_ver: c_long = 0;
        _ = curl.curl_easy_getinfo(handle, curl.CURLINFO_HTTP_VERSION, &http_ver);

        // Timing info
        var total_time: f64 = 0;
        var ttfb: f64 = 0;
        _ = curl.curl_easy_getinfo(handle, curl.CURLINFO_TOTAL_TIME, &total_time);
        _ = curl.curl_easy_getinfo(handle, curl.CURLINFO_STARTTRANSFER_TIME, &ttfb);

        // Redirect count
        var redir_count: c_long = 0;
        _ = curl.curl_easy_getinfo(handle, curl.CURLINFO_REDIRECT_COUNT, &redir_count);

        // Remote address
        var remote_ip: [*c]u8 = null;
        var remote_port: c_long = 0;
        _ = curl.curl_easy_getinfo(handle, curl.CURLINFO_PRIMARY_IP, &remote_ip);
        _ = curl.curl_easy_getinfo(handle, curl.CURLINFO_PRIMARY_PORT, &remote_port);

        // Effective URL
        var effective_url: [*c]u8 = null;
        _ = curl.curl_easy_getinfo(handle, curl.CURLINFO_EFFECTIVE_URL, &effective_url);

        // Copy headers to response allocator
        const headers = allocator.alloc(NetworkResponse.Header, self.response_headers.items.len) catch return .OutOfMemory;
        errdefer allocator.free(headers);

        for (self.response_headers.items, 0..) |h, i| {
            headers[i] = .{
                .name = allocator.dupe(u8, h.name) catch return .OutOfMemory,
                .value = allocator.dupe(u8, h.value) catch return .OutOfMemory,
            };
        }

        // Copy body
        const body: ?[]const u8 = if (self.response_body.items.len > 0)
            allocator.dupe(u8, self.response_body.items) catch return .OutOfMemory
        else
            null;

        return NetworkResponse{
            .allocator = allocator,
            .status = @intCast(status),
            .http_version = switch (http_ver) {
                curl.c.CURL_HTTP_VERSION_1_0 => .http_1_0,
                curl.c.CURL_HTTP_VERSION_1_1 => .http_1_1,
                curl.c.CURL_HTTP_VERSION_2_0 => .http_2,
                curl.c.CURL_HTTP_VERSION_3 => .http_3,
                else => .http_1_1,
            },
            .headers = headers,
            .body = body,
            .final_url = if (effective_url) |url|
                allocator.dupe(u8, std.mem.span(url)) catch return .OutOfMemory
            else
                null,
            .total_time_ms = @intFromFloat(total_time * 1000),
            .time_to_first_byte_ms = @intFromFloat(ttfb * 1000),
            .redirect_count = @intCast(redir_count),
            .remote_ip = if (remote_ip) |ip|
                allocator.dupe(u8, std.mem.span(ip)) catch return .OutOfMemory
            else
                null,
            .remote_port = if (remote_port > 0) @intCast(remote_port) else null,
        };
    }
};
```

### Callbacks
```zig
/// Write callback - receives response body data
fn writeCallback(
    data: [*]u8,
    size: usize,
    nmemb: usize,
    userdata: *anyopaque,
) callconv(.C) usize {
    const self: *LibcurlBackend = @ptrCast(@alignCast(userdata));

    // Check abort flag
    if (self.aborted.load(.acquire)) {
        return 0; // Returning 0 aborts transfer
    }

    const total = size * nmemb;
    self.response_body.appendSlice(data[0..total]) catch {
        return 0; // Error
    };

    return total;
}

/// Header callback - receives response headers
fn headerCallback(
    data: [*]u8,
    size: usize,
    nmemb: usize,
    userdata: *anyopaque,
) callconv(.C) usize {
    const self: *LibcurlBackend = @ptrCast(@alignCast(userdata));

    const total = size * nmemb;
    const line = data[0..total];

    // Skip status line and empty lines
    if (std.mem.startsWith(u8, line, "HTTP/")) return total;
    if (line.len <= 2) return total; // Just CRLF

    // Parse "Name: Value\r\n"
    if (std.mem.indexOf(u8, line, ": ")) |colon| {
        const name = line[0..colon];
        var value = line[colon + 2 ..];

        // Trim trailing CRLF
        while (value.len > 0 and (value[value.len - 1] == '\r' or value[value.len - 1] == '\n')) {
            value = value[0 .. value.len - 1];
        }

        // Store header
        self.response_headers.append(.{
            .name = self.allocator.dupe(u8, name) catch return 0,
            .value = self.allocator.dupe(u8, value) catch return 0,
        }) catch return 0;
    }

    return total;
}

/// Progress callback - used for abort support
fn progressCallback(
    userdata: *anyopaque,
    _: c_longlong, // dltotal
    _: c_longlong, // dlnow
    _: c_longlong, // ultotal
    _: c_longlong, // ulnow
) callconv(.C) c_int {
    const self: *LibcurlBackend = @ptrCast(@alignCast(userdata));

    // Return non-zero to abort
    if (self.aborted.load(.acquire)) {
        return 1;
    }
    return 0;
}
```

