## Implementation

### ConnectionPool
```zig
pub const ConnectionPool = struct {
    allocator: Allocator,
    multi_handle: *curl.CURLM,
    active_handles: std.AutoHashMap(*curl.CURL, *RequestContext),
    max_connections_per_host: u32,
    max_total_connections: u32,

    pub fn init(allocator: Allocator) !*ConnectionPool {
        const multi = curl.curl_multi_init() orelse {
            return error.MultiInitFailed;
        };

        const pool = try allocator.create(ConnectionPool);
        pool.* = .{
            .allocator = allocator,
            .multi_handle = multi,
            .active_handles = std.AutoHashMap(*curl.CURL, *RequestContext).init(allocator),
            .max_connections_per_host = 6, // Per HTTP spec
            .max_total_connections = 256,
        };

        // Configure multi handle
        _ = curl.curl_multi_setopt(multi, curl.CURLMOPT_MAX_HOST_CONNECTIONS, 
            @as(c_long, pool.max_connections_per_host));
        _ = curl.curl_multi_setopt(multi, curl.CURLMOPT_MAX_TOTAL_CONNECTIONS,
            @as(c_long, pool.max_total_connections));

        return pool;
    }

    pub fn deinit(self: *ConnectionPool) void {
        // Remove all handles
        var it = self.active_handles.iterator();
        while (it.next()) |entry| {
            curl.curl_multi_remove_handle(self.multi_handle, entry.key_ptr.*);
            curl.curl_easy_cleanup(entry.key_ptr.*);
            entry.value_ptr.*.deinit();
        }
        self.active_handles.deinit();

        curl.curl_multi_cleanup(self.multi_handle);
        self.allocator.destroy(self);
    }

    /// Start a new request
    pub fn startRequest(
        self: *ConnectionPool,
        request: *const NetworkRequest,
        callback: RequestCallback,
    ) !*RequestHandle {
        const handle = curl.curl_easy_init() orelse {
            return error.HandleInitFailed;
        };
        errdefer curl.curl_easy_cleanup(handle);

        const ctx = try self.allocator.create(RequestContext);
        ctx.* = .{
            .callback = callback,
            .response_data = .{},
        };

        // Configure handle
        try configureHandle(handle, request, ctx);

        // Add to multi
        const result = curl.curl_multi_add_handle(self.multi_handle, handle);
        if (result != curl.CURLM_OK) {
            return error.AddHandleFailed;
        }

        try self.active_handles.put(handle, ctx);

        return @ptrCast(handle);
    }

    /// Poll for completed requests
    pub fn poll(self: *ConnectionPool, timeout_ms: i32) !void {
        var still_running: c_int = 0;
        _ = curl.curl_multi_perform(self.multi_handle, &still_running);

        // Process completed transfers
        while (true) {
            var msgs_left: c_int = 0;
            const msg = curl.curl_multi_info_read(self.multi_handle, &msgs_left);
            if (msg == null) break;

            if (msg.*.msg == curl.CURLMSG_DONE) {
                const handle = msg.*.easy_handle;
                const result = msg.*.data.result;

                if (self.active_handles.get(handle)) |ctx| {
                    if (result == curl.CURLE_OK) {
                        ctx.callback.onComplete(&ctx.response_data);
                    } else {
                        ctx.callback.onError(curl_error.mapCurlError(result));
                    }

                    // Cleanup
                    _ = curl.curl_multi_remove_handle(self.multi_handle, handle);
                    _ = self.active_handles.remove(handle);
                    // Note: Don't cleanup handle - it goes back to pool
                }
            }
        }
    }
};
```

### Global Pool
