/// Type of source expression in a directive value
pub const SourceExpressionType = enum {
    // Keywords
    keyword_none,              // 'none'
    keyword_self,              // 'self'
    keyword_unsafe_inline,     // 'unsafe-inline'
    keyword_unsafe_eval,       // 'unsafe-eval'
    keyword_unsafe_hashes,     // 'unsafe-hashes'
    keyword_strict_dynamic,    // 'strict-dynamic'
    keyword_wasm_unsafe_eval,  // 'wasm-unsafe-eval'
    keyword_report_sample,     // 'report-sample'
    keyword_trusted_types_eval, // 'trusted-types-eval' (TT integration!)

    // Value expressions
    scheme,                    // https:, data:, blob:, etc.
    host,                      // example.com, *.example.com, https://example.com
    nonce,                     // 'nonce-abc123'
    hash,                      // 'sha256-...', 'sha384-...', 'sha512-...'
};

/// Parsed source expression
pub const SourceExpression = struct {
    type: SourceExpressionType,
    raw_value: []const u8,

    // Parsed components (populated based on type)
    scheme_part: ?[]const u8 = null,  // For scheme/host expressions
    host_part: ?[]const u8 = null,    // For host expressions
    port_part: ?u16 = null,           // For host expressions with port
    path_part: ?[]const u8 = null,    // For host expressions with path
    nonce_value: ?[]const u8 = null,  // For nonce expressions
    hash_algorithm: ?[]const u8 = null, // 'sha256', 'sha384', 'sha512'
    hash_value: ?[]const u8 = null,   // Base64-encoded hash

    allocator: std.mem.Allocator,

    pub fn deinit(self: *SourceExpression) void {
        self.allocator.free(self.raw_value);
        // Free other allocated parts...
    }
};

/// Ordered list of source expressions
pub const SourceList = struct {
    expressions: std.ArrayList(SourceExpression),
    allocator: std.mem.Allocator,

    pub fn init(allocator: std.mem.Allocator) SourceList {
        return .{
            .expressions = std.ArrayList(SourceExpression).init(allocator),
            .allocator = allocator,
        };
    }

    /// Check if list contains an expression of given type
    pub fn contains(self: *const SourceList, expr_type: SourceExpressionType) bool {
        for (self.expressions.items) |expr| {
            if (expr.type == expr_type) return true;
        }
        return false;
    }

    /// Check if source list is 'none' (single 'none' keyword)
    pub fn isNone(self: *const SourceList) bool {
        return self.expressions.items.len == 1 and
               self.expressions.items[0].type == .keyword_none;
    }

    pub fn deinit(self: *SourceList) void {
        for (self.expressions.items) |*expr| {
            expr.deinit();
        }
        self.expressions.deinit();
    }
};
```

### CSP List

```zig
/// Multiple policies combined for a document/worker
/// Spec: CSP Level 3 § 2.2
pub const CSPList = struct {
    policies: std.ArrayList(Policy),
    allocator: std.mem.Allocator,

    /// Optimization flag for quick header check
    contains_header_policy: bool,

    pub fn init(allocator: std.mem.Allocator) CSPList {
        return .{
            .policies = std.ArrayList(Policy).init(allocator),
            .allocator = allocator,
            .contains_header_policy = false,
        };
    }

    pub fn append(self: *CSPList, policy: Policy) !void {
        try self.policies.append(policy);
        if (policy.source == .header) {
            self.contains_header_policy = true;
        }
    }

    /// Check if any policy has enforcement disposition
    pub fn hasEnforcingPolicy(self: *const CSPList) bool {
        for (self.policies.items) |policy| {
            if (policy.disposition == .enforce) return true;
        }
        return false;
    }

    pub fn deinit(self: *CSPList) void {
        for (self.policies.items) |*policy| {
            policy.deinit();
        }
        self.policies.deinit();
    }
};
