## Current Duplicate Code \(in each file\)

```zig
var xxx_registry: std.AutoHashMap\(usize, *InternalState\) = undefined\;
var xxx_registry_initialized: bool = false\;

fn ensureXxxRegistry\(\) void {
    if \(\!xxx_registry_initialized\) {
        xxx_registry = std.AutoHashMap\(usize, *InternalState\).init\(std.heap.page_allocator\)\;
        xxx_registry_initialized = true\;
    }
}

fn setInternalInRegistry\(instance: *runtime.Instance, internal: *InternalState\) \!void {
    ensureXxxRegistry\(\)\;
    try xxx_registry.put\(@intFromPtr\(instance\), internal\)\;
}

fn getInternalFromRegistry\(instance: *runtime.Instance\) ?*InternalState {
    ensureXxxRegistry\(\)\;
    return xxx_registry.get\(@intFromPtr\(instance\)\)\;
}

// In deinit:
_ = xxx_registry.remove\(@intFromPtr\(instance\)\)\;
```

## Solution

Create `src/webidl/utils/registry.zig`:

```zig
pub fn InstanceRegistry\(comptime T: type\) type {
    return struct {
        var map: ?std.AutoHashMap\(usize, *T\) = null\;

        pub fn ensure\(\) *std.AutoHashMap\(usize, *T\) {
            if \(map == null\) {
                map = std.AutoHashMap\(usize, *T\).init\(std.heap.page_allocator\)\;
            }
            return \&map.?\;
        }

        pub fn get\(instance: *runtime.Instance\) ?*T {
            const m = ensure\(\)\;
            return m.get\(@intFromPtr\(instance\)\)\;
        }

        pub fn set\(instance: *runtime.Instance, internal: *T\) \!void {
            const m = ensure\(\)\;
            try m.put\(@intFromPtr\(instance\), internal\)\;
        }

        pub fn remove\(instance: *runtime.Instance\) void {
            const m = ensure\(\)\;
            _ = m.remove\(@intFromPtr\(instance\)\)\;
        }
    }\;
}
```

