### Script Execution Context

```zig
pub const ParserScriptContext = struct {
    allocator: Allocator,
    ctx: runtime.Context,
    dom_adapter: *DomTreeAdapter,
    document: *runtime.Instance,
    isolate: *v8.ffi.Isolate,
    v8_context: *v8.ffi.Context,
}\;
```

### Callback Implementation

```zig
fn parserScriptCallback\(script_tree_node: *TreeNode, context: ?*anyopaque\) void {
    const ctx = @as\(*ParserScriptContext, @ptrCast\(@alignCast\(context\)\)\)\;

    // 1. Get DOM HTMLScriptElement from tree node
    const script_element = ctx.dom_adapter.getDomNode\(script_tree_node\) orelse return\;

    // 2. Get script content
    const script_content = getScriptContent\(script_tree_node\)\;

    // 3. Check if external script
    if \(getScriptSrc\(script_tree_node\)\) \|src\| {
        // Queue external script for loading
        // This may need to be async
        return\;
    }

    // 4. Execute inline script via V8
    executeScript\(ctx, script_content\) catch \|err\| {
        // Handle script error
    }\;
}

fn executeScript\(ctx: *ParserScriptContext, content: []const u8\) \!void {
    const source = v8.ffi.v8_String_NewFromUtf8\(ctx.isolate, content.ptr, content.len\)\;
    const script = v8.ffi.v8_Script_Compile\(ctx.v8_context, source, null\)\;
    _ = v8.ffi.v8_Script_Run\(script, ctx.v8_context\)\;
}
```

