pub fn parseHTML\(allocator: Allocator, ctx: runtime.Context, html: []const u8, options: ParseOptions\) \!*runtime.Instance {
    // Create document first
    const document = try interfaces.Document.init\(allocator, ctx\)\;

    // Create DOM adapter for incremental conversion
    var dom_adapter = DomTreeAdapter.init\(allocator, ctx, document\)\;

    // Create script context
    var script_ctx = ParserScriptContext{
        .allocator = allocator,
        .ctx = ctx,
        .dom_adapter = \&dom_adapter,
        .document = document,
        .isolate = v8.ffi.v8_Isolate_GetCurrent\(\),
        .v8_context = ctx.getEngineContext\(\),
    }\;

    // Set up tree builder with callbacks
    var tree_builder = try TreeBuilder.init\(allocator, \&tokenizer\)\;
    tree_builder.setDomAdapter\(\&dom_adapter\)\;
    tree_builder.setScriptExecutionCallback\(parserScriptCallback, \&script_ctx\)\;
    tree_builder.scripting_enabled = options.scripting_enabled\;

    // Parse \(scripts execute during this\)
    try tree_builder.parse\(\)\;

    return document\;
}
