## Solution

Use a generic interface pattern:

```zig
pub fn ReadRequest\(comptime Context: type\) type {
    return struct {
        allocator: std.mem.Allocator,
        context: *Context,

        // Typed callbacks
        chunk_steps: *const fn \(*Context, Value\) void,
        close_steps: *const fn \(*Context\) void,
        error_steps: *const fn \(*Context, Value\) void,

        pub fn executeChunkSteps\(self: *const @This\(\), chunk: Value\) void {
            self.chunk_steps\(self.context, chunk\)\;
        }
        // ...
    }\;
}

// Type-erased version for storage in lists
pub const ErasedReadRequest = struct {
    vtable: *const VTable,
    context: *anyopaque,
    type_id: u32,

    const VTable = struct {
        chunk_steps: *const fn \(*anyopaque, Value\) void,
        close_steps: *const fn \(*anyopaque\) void,
        error_steps: *const fn \(*anyopaque, Value\) void,
    }\;
}\;
