### 2. Snapshot Embedding Module (snapshot_loader.zig)
Create `src/runtime/engines/v8/snapshot_loader.zig`:
```zig
const std = @import("std");
const ffi = @import("ffi.zig");
const ext_refs = @import("external_references.zig");

/// Embedded snapshot blob (generated at build time)
/// This is null if no snapshot was embedded
const embedded_snapshot: ?[]const u8 = blk: {
    if (@hasDecl(@This(), "snapshot_blob")) {
        break :blk @embedFile("snapshot_blob");
    }
    break :blk null;
};

pub const SnapshotLoadResult = struct {
    isolate: *ffi.Isolate,
    context: *ffi.Context,
    used_snapshot: bool,
};

/// Initialize V8 runtime, preferring snapshot if available
pub fn initializeFromSnapshot(allocator: std.mem.Allocator) !SnapshotLoadResult {
    // Get external references (must match snapshot creation)
    const external_refs = ext_refs.getRuntimeExternalReferencesPtr();

    if (embedded_snapshot) |snapshot_data| {
        // Validate snapshot before using
        if (ffi.v8_Snapshot_IsValid(
            snapshot_data.ptr,
            @intCast(snapshot_data.len),
        )) {
            // Create isolate from snapshot
            const isolate = ffi.v8_Isolate_NewFromSnapshot(
                snapshot_data.ptr,
                @intCast(snapshot_data.len),
                external_refs,
            ) orelse {
                std.log.warn("Failed to create isolate from snapshot, falling back", .{});
                return initializeWithoutSnapshot(allocator);
            };

            // Create context from snapshot
            const context = ffi.v8_Context_NewFromSnapshot(isolate) orelse {
                std.log.warn("Failed to create context from snapshot, falling back", .{});
                ffi.v8_Isolate_Dispose(isolate);
                return initializeWithoutSnapshot(allocator);
            };

            std.log.info("V8 initialized from snapshot (fast path)", .{});

            return .{
                .isolate = isolate,
                .context = context,
                .used_snapshot = true,
            };
        } else {
            std.log.warn("Embedded snapshot is invalid, falling back to manual init", .{});
        }
    }

    return initializeWithoutSnapshot(allocator);
}

/// Initialize V8 runtime without snapshot (slow path)
fn initializeWithoutSnapshot(allocator: std.mem.Allocator) !SnapshotLoadResult {
    std.log.info("V8 initializing without snapshot (slow path)", .{});

    const start_time = std.time.milliTimestamp();

    // Create isolate normally
    const isolate = ffi.v8_Isolate_New(null) orelse 
        return error.IsolateCreationFailed;

    // Create context
    const context = ffi.v8_Context_New(isolate) orelse {
        ffi.v8_Isolate_Dispose(isolate);
        return error.ContextCreationFailed;
    };

    // Register all interfaces manually
    try registerAllInterfaces(isolate, context);

    const elapsed = std.time.milliTimestamp() - start_time;
    std.log.info("V8 initialized without snapshot in {d}ms", .{elapsed});

    return .{
        .isolate = isolate,
        .context = context,
        .used_snapshot = false,
    };
}

/// Check if a valid snapshot is available
pub fn hasValidSnapshot() bool {
    if (embedded_snapshot) |snapshot_data| {
        return ffi.v8_Snapshot_IsValid(
            snapshot_data.ptr,
            @intCast(snapshot_data.len),
        );
    }
    return false;
}

/// Get snapshot version/hash for validation
pub fn getSnapshotVersion() ?u64 {
    if (embedded_snapshot) |snapshot_data| {
        return ffi.v8_Snapshot_GetVersion(
            snapshot_data.ptr,
            @intCast(snapshot_data.len),
        );
    }
    return null;
}
```

### 3. Add Snapshot Validation FFI (v8_wrapper.cpp)
```cpp
extern "C" {
    /// Check if snapshot data is valid
    bool v8_Snapshot_IsValid(const char* data, int size) {
        if (!data || size <= 0) return false;

        StartupData snapshot;
        snapshot.data = data;
        snapshot.raw_size = size;

        // Try to create isolate to validate
        // V8 will reject invalid snapshots
        Isolate::CreateParams params;
        params.snapshot_blob = &snapshot;
        params.array_buffer_allocator = 
            ArrayBuffer::Allocator::NewDefaultAllocator();

        // V8 validates snapshot during isolate creation
        // We don't actually create it here, just check the format
        return snapshot.raw_size > 0 && 
               snapshot.data[0] != '\0';  // Basic sanity check
    }

    /// Get snapshot version for cache invalidation
    uint64_t v8_Snapshot_GetVersion(const char* data, int size) {
        if (!data || size < 8) return 0;

        // First 8 bytes contain version hash
        uint64_t version;
        memcpy(&version, data, sizeof(version));
        return version;
    }

    /// Create isolate from snapshot
    Isolate* v8_Isolate_NewFromSnapshot(
        const char* snapshot_data,
        int snapshot_size,
        const intptr_t* external_references
    ) {
        StartupData snapshot;
        snapshot.data = snapshot_data;
        snapshot.raw_size = snapshot_size;

        Isolate::CreateParams params;
        params.snapshot_blob = &snapshot;
        params.external_references = external_references;
        params.array_buffer_allocator = 
            ArrayBuffer::Allocator::NewDefaultAllocator();

        return Isolate::New(params);
    }

    /// Create context from snapshot (uses default context index 0)
    Global<Context>* v8_Context_NewFromSnapshot(Isolate* isolate) {
        HandleScope handle_scope(isolate);

        // Create context from snapshot's default context
        MaybeLocal<Context> maybe_context = 
            Context::FromSnapshot(isolate, 0);

        if (maybe_context.IsEmpty()) {
            return nullptr;
        }

        Local<Context> context = maybe_context.ToLocalChecked();
        return trackHandle(new Global<Context>(isolate, context));
    }
}
```

