// src/runtime/engines/v8/runtime.zig or similar
const snapshot_loader = @import("snapshot_loader.zig");

pub fn init(allocator: std.mem.Allocator) !*V8Runtime {
    // Initialize V8 platform if needed
    try initializePlatform();

    // Load from snapshot if available
    const init_result = try snapshot_loader.initializeFromSnapshot(allocator);

    const runtime = try allocator.create(V8Runtime);
    runtime.* = .{
        .isolate = init_result.isolate,
        .context = init_result.context,
        .allocator = allocator,
        .used_snapshot = init_result.used_snapshot,
