/// TrustedHTML - Wraps an immutable HTML string.
/// Spec: https://w3c.github.io/trusted-types/dist/spec/#trusted-html
/// 
/// TrustedHTML objects have an associated string 'data'. The value is set 
/// when the object is created, and will never change during its lifetime.
pub const TrustedHTML = struct {
    /// Internal string data (immutable after creation)
    /// This is stored in an internal slot with no setter exposed
    data: []const u8,
    allocator: std.mem.Allocator,

    /// toJSON() method steps and stringification behavior
    /// Returns the associated data value
    pub fn toString(self: *const TrustedHTML) []const u8 {
        return self.data;
    }

    pub fn toJSON(self: *const TrustedHTML) []const u8 {
        return self.data;
    }

    pub fn deinit(self: *TrustedHTML) void {
        self.allocator.free(self.data);
    }
};

/// TrustedScript - Wraps an immutable script string.
/// Spec: https://w3c.github.io/trusted-types/dist/spec/#trusted-script
pub const TrustedScript = struct {
    data: []const u8,
    allocator: std.mem.Allocator,

    pub fn toString(self: *const TrustedScript) []const u8 {
        return self.data;
    }

    pub fn toJSON(self: *const TrustedScript) []const u8 {
        return self.data;
    }

    pub fn deinit(self: *TrustedScript) void {
        self.allocator.free(self.data);
    }
};

/// TrustedScriptURL - Wraps an immutable script URL string.
/// Spec: https://w3c.github.io/trusted-types/dist/spec/#trused-script-url
/// Note: Returns USVString (not DOMString) from toJSON
pub const TrustedScriptURL = struct {
    data: []const u8,
    allocator: std.mem.Allocator,

    pub fn toString(self: *const TrustedScriptURL) []const u8 {
        return self.data;
    }

    /// Returns USVString (ensures valid Unicode scalar values)
    pub fn toJSON(self: *const TrustedScriptURL) []const u8 {
        return self.data;
    }

    pub fn deinit(self: *TrustedScriptURL) void {
        self.allocator.free(self.data);
    }
};

/// Union of all Trusted Types
/// typedef (TrustedHTML or TrustedScript or TrustedScriptURL) TrustedType;
pub const TrustedType = union(enum) {
    html: *TrustedHTML,
    script: *TrustedScript,
    script_url: *TrustedScriptURL,
};
```

## Key Implementation Details

1. **Immutability**: The 'data' field is set at creation and never changes
2. **Unforgeable**: Objects cannot be created except through policies
3. **Stringifiers**: toString() returns the inner string for backward compatibility
4. **Memory**: Each type owns its string data and must be deinitialized

