### Task 3: Response Processing

**File:** `src/xhr/algorithms/response.zig`

```zig
//! Response Processing Algorithms
//!
//! WHATWG XHR Spec: https://xhr.spec.whatwg.org/#response

const std = @import("std");
const XMLHttpRequest = @import("../../webidl/interfaces/XMLHttpRequest.zig").XMLHttpRequest;
const InternalResponse = @import("../../fetch/internal/response.zig").InternalResponse;

/// Process response (headers received)
///
/// Spec: https://xhr.spec.whatwg.org/#handle-response
pub fn processResponse(
    xhr: *XMLHttpRequest,
    response: *InternalResponse,
) !void {
    // Store response
    xhr.state.response = response;

    // Handle network error
    if (response.type == .error) {
        try handleNetworkError(xhr);
        return;
    }

    // Transition to HEADERS_RECEIVED
    xhr.state.changeState(.HEADERS_RECEIVED, xhr);

    // If response has body, transition to LOADING
    if (response.body != null) {
        xhr.state.changeState(.LOADING, xhr);
    }
}

/// Process response body chunk
///
/// Spec: Accumulate received bytes
pub fn processResponseBodyChunk(
    xhr: *XMLHttpRequest,
    chunk: []const u8,
) !void {
    // Accumulate into received_bytes
    try xhr.state.received_bytes.appendSlice(chunk);

    // Update progress tracker (fires throttled progress events)
    xhr.progress_tracker.onChunk(chunk.len);
}

/// Process response end of body
///
/// Spec: https://xhr.spec.whatwg.org/#handle-response-end-of-body
pub fn processResponseEndOfBody(xhr: *XMLHttpRequest) !void {
    // Handle any errors first
    try handleErrors(xhr);

    if (xhr.state.response) |response| {
        if (response.type == .error) {
            return; // Network error already handled
        }
    }

    // Fire final progress event
    const total = xhr.state.received_bytes.items.len;
    const length = extractLength(xhr.state.response.?.headers);
    try fireProgressEvent(xhr, "progress", total, length);

    // Transition to DONE
    xhr.state.changeState(.DONE, xhr);

    // Unset send flag
    xhr.state.send_flag = false;

    // Fire load event
    try fireProgressEvent(xhr, "load", total, length);

    // Fire loadend event
    try fireProgressEvent(xhr, "loadend", total, length);
}

/// Handle network error
fn handleNetworkError(xhr: *XMLHttpRequest) !void {
    // Set error flag
    xhr.state.error = true;

    // Transition to DONE
    xhr.state.changeState(.DONE, xhr);

    // Unset send flag
    xhr.state.send_flag = false;

    // Fire error events
    try fireProgressEvent(xhr, "error", 0, null);
    try fireProgressEvent(xhr, "loadend", 0, null);

    // Upload error events if needed
    if (!xhr.state.upload_complete_flag) {
        xhr.state.upload_complete_flag = true;
        try fireProgressEvent(xhr.upload, "error", 0, null);
        try fireProgressEvent(xhr.upload, "loadend", 0, null);
    }
}

/// Handle errors
fn handleErrors(xhr: *XMLHttpRequest) !void {
    if (xhr.state.timed_out_flag) {
        try handleTimeout(xhr);
    }
}

/// Handle timeout
fn handleTimeout(xhr: *XMLHttpRequest) !void {
    xhr.state.send_flag = false;
    xhr.state.changeState(.DONE, xhr);

    try fireProgressEvent(xhr, "timeout", 0, null);
    try fireProgressEvent(xhr, "loadend", 0, null);
}

/// Extract Content-Length from headers
fn extractLength(headers: *HeaderList) ?usize {
    const content_length = headers.get("Content-Length") orelse return null;
    return std.fmt.parseInt(usize, content_length, 10) catch null;
}

/// Fire progress event helper
fn fireProgressEvent(
    target: anytype,
    event_type: []const u8,
    loaded: usize,
    total: ?usize,
) !void {
    const progress_event = try ProgressEvent.init(
        target.allocator,
        event_type,
        total != null,
        @floatFromInt(loaded),
        if (total) |t| @floatFromInt(t) else 0,
    );

    try target.dispatchEvent(progress_event);
}
