### Task 4: Progress Event Throttling

**File:** `src/xhr/internal/progress_tracker.zig`

```zig
//! Progress Event Throttling
//!
//! Spec requirement: Progress events should be throttled to approximately 50ms
//! to avoid overwhelming the event loop during fast downloads.
//!
//! Browser implementations: All use 50ms throttling timers

const std = @import("std");
const XMLHttpRequest = @import("../../webidl/interfaces/XMLHttpRequest.zig").XMLHttpRequest;
const Timer = @import("../../runtime/timer.zig").Timer;

/// Progress event tracker with 50ms throttling
pub const ProgressTracker = struct {
    /// XHR instance
    xhr: *XMLHttpRequest,

    /// Last time progress event was fired (milliseconds)
    last_progress_time: i64,

    /// Bytes accumulated since last event
    bytes_since_last_event: usize,

    /// Total bytes received
    total_bytes: usize,

    /// Content-Length from response (if known)
    content_length: ?usize,

    /// Pending timer for throttled event
    timer: ?*Timer,

    /// Throttle interval (50ms per spec/browsers)
    const THROTTLE_MS: i64 = 50;

    pub fn init(xhr: *XMLHttpRequest) ProgressTracker {
        return .{
            .xhr = xhr,
            .last_progress_time = 0,
            .bytes_since_last_event = 0,
            .total_bytes = 0,
            .content_length = null,
            .timer = null,
        };
    }

    pub fn deinit(self: *ProgressTracker) void {
        if (self.timer) |timer| {
            timer.cancel();
        }
    }

    /// Called when a chunk is received
    pub fn onChunk(self: *ProgressTracker, chunk_size: usize) void {
        self.total_bytes += chunk_size;
        self.bytes_since_last_event += chunk_size;

        const now = std.time.milliTimestamp();
        const elapsed = now - self.last_progress_time;

        if (elapsed >= THROTTLE_MS) {
            // Enough time elapsed, fire immediately
            self.fireProgressNow();
        } else if (self.timer == null) {
            // Schedule timer to fire after throttle period
            const remaining = THROTTLE_MS - elapsed;
            self.scheduleTimer(remaining);
        }
        // Else: Timer already scheduled, will fire soon
    }

    /// Fire progress event immediately
    fn fireProgressNow(self: *ProgressTracker) void {
        const loaded = self.total_bytes;
        const total = self.content_length;

        fireProgressEvent(
            self.xhr,
            "progress",
            loaded,
            total,
        ) catch |err| {
            std.log.err("Failed to fire progress event: {}", .{err});
        };

        self.last_progress_time = std.time.milliTimestamp();
        self.bytes_since_last_event = 0;

        // Clear timer
        if (self.timer) |timer| {
            timer.cancel();
            self.timer = null;
        }
    }

    /// Schedule timer to fire progress event
    fn scheduleTimer(self: *ProgressTracker, delay_ms: i64) void {
        self.timer = Timer.setTimeout(
            @intCast(delay_ms),
            timerCallback,
            self,
        ) catch |err| {
            std.log.err("Failed to schedule progress timer: {}", .{err});
            return;
        };
    }

    /// Timer callback
    fn timerCallback(user_data: ?*anyopaque) void {
        const self: *ProgressTracker = @ptrCast(@alignCast(user_data.?));
        self.fireProgressNow();
    }

    /// Set content length from response headers
    pub fn setContentLength(self: *ProgressTracker, length: usize) void {
        self.content_length = length;
    }
};
```

