    try std.testing.expectEqualStrings("readystatechange", events.items[1]); // HEADERS_RECEIVED
    try std.testing.expectEqualStrings("readystatechange", events.items[2]); // LOADING
    // progress events...
    try std.testing.expectEqualStrings("load", events.items[events.items.len - 2]);
    try std.testing.expectEqualStrings("loadend", events.items[events.items.len - 1]);

