    // Check if value is a wrapped instance
    if \(ffi.v8_Value_IsObject\(value\)\) {
        // ... extract instance or create global ...
        return @ptrCast\(tagged_ptr\)\;  // Type information LOST
    }
    return @ptrCast\(value\)\;  // Raw Local pointer - DANGEROUS
}
```

## Required Changes

### 1. Add JSValue import

```zig
const JSValue = @import\("js_value.zig"\).JSValue\;
const OptionalJSValue = @import\("js_value.zig"\).OptionalJSValue\;
```

### 2. Add new conversion path for JSValue

```zig
/// Convert V8 value to JSValue \(type-safe\)
pub fn fromV8ValueTyped\(value: *ffi.Value, isolate: *ffi.Isolate, context: *ffi.Context\) \!JSValue {
    // Null check
    if \(ffi.v8_Value_IsNull\(value\)\) {
        return .{ .null = {} }\;
    }

    // Undefined check
    if \(ffi.v8_Value_IsUndefined\(value\)\) {
        return .{ .undefined = {} }\;
    }

    // Boolean optimization
    if \(ffi.v8_Value_IsBoolean\(value\)\) {
        return .{ .boolean = ffi.v8_Value_ToBoolean\(isolate, value\) }\;
    }

    // Number optimization
    if \(ffi.v8_Value_IsNumber\(value\)\) {
        return .{ .number = ffi.v8_Value_ToNumber\(isolate, value\) orelse 0 }\;
    }

    // Object/Function - check for wrapped instance first
    if \(ffi.v8_Value_IsObject\(value\)\) {
        const obj: *ffi.Object = @ptrCast\(value\)\;

        // Check if this is a wrapped Zig instance
        if \(ffi.v8_Object_InternalFieldCount\(obj\) \>= 2\) {
            if \(ffi.v8_Object_GetAlignedPointerFromInternalField\(obj, 0\)\) \|ptr\| {
                const instance: *runtime.Instance = @ptrCast\(@alignCast\(ptr\)\)\;
                return .{ .instance = instance }\;
            }
        }

        // Regular JS object - create Global handle for persistence
        const global = ffi.v8_Value_ToGlobal\(isolate, value\) orelse {
            return error.GlobalHandleCreationFailed\;
        }\;
        return .{ .global = .{ .ptr = global } }\;
    }

    // Other types - create Global handle
    const global = ffi.v8_Value_ToGlobal\(isolate, value\) orelse {
        return error.GlobalHandleCreationFailed\;
    }\;
    return .{ .global = .{ .ptr = global } }\;
}
```

### 3. Update fromV8Value for *const anyopaque to use JSValue internally

```zig
if \(T == *const anyopaque\) {
    // Use type-safe conversion internally
    const js_value = try fromV8ValueTyped\(value, isolate, context\)\;

    // Convert back to tagged anyopaque for legacy compatibility
    return js_value.toAnyopaque\(\) orelse @ptrFromInt\(0\)\;
}
```

### 4. Add JSValue as supported conversion target

```zig
if \(T == JSValue\) {
    return fromV8ValueTyped\(value, isolate, context\)\;
}

if \(T == OptionalJSValue\) {
    if \(ffi.v8_Value_IsNullOrUndefined\(value\)\) {
        return .{ .not_passed = {} }\;
    }
    return .{ .passed = try fromV8ValueTyped\(value, isolate, context\) }\;
}
```

### 5. Update toV8Value to handle JSValue

```zig
if \(T == JSValue\) {
    return value.toV8\(isolate\)\;
}

if \(T == OptionalJSValue\) {
    return switch \(value\) {
        .not_passed =\> ffi.v8_Undefined\(isolate\),
        .passed =\> \|v\| v.toV8\(isolate\),
    }\;
}
```

