const std = @import("std");
const websocket = @import("websocket");

pub fn main() !void {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    // Create WebSocket connection
    var ws = try websocket.WebSocketConnection.init(
        allocator,
        "wss://echo.websocket.org",
        .{},
    );
    defer ws.deinit();

    // Set up event handler
    ws.setEventCallback(handleEvent, null);

    // Connect
    try ws.connect(.{});

    // Send a message
    try ws.sendText("Hello, WebSocket!");

    // Process incoming messages
    while (ws.getReadyState() == 1) {
        try ws.processIncoming();
    }
}

fn handleEvent(event: websocket.Event, _: ?*anyopaque) void {
    switch (event) {
        .open => std.debug.print("Connected!\n", .{}),
        .message => |msg| std.debug.print("Received: {s}\n", .{msg.data}),
        .close => |c| std.debug.print("Closed: {d} {s}\n", .{c.code, c.reason}),
        .@"error" => std.debug.print("Error occurred\n", .{}),
    }
}
