### Empty Parts Array
```zig
test "process empty parts" {
    const result = try processBlobParts(allocator, &[_]BlobPart{}, .{});
    defer allocator.free(result);
    try std.testing.expectEqual(@as(usize, 0), result.len);
}
```

### Mixed Part Types
```zig
test "process mixed parts" {
    var blob_data = try BlobData.init(allocator, "blob-content", "");
    defer blob_data.deinit();

    const parts = [_]BlobPart{
        .{ .string = "hello " },
        .{ .buffer_source = .{ .data = "world" } },
        .{ .blob = blob_data },
    };

    const result = try processBlobParts(allocator, &parts, .{});
