```zig
test "process with native line endings" {
    const parts = [_]BlobPart{
        .{ .string = "line1\nline2\r\nline3\rline4" },
    };

    const result = try processBlobParts(allocator, &parts, .{ .endings = .native });
    defer allocator.free(result);

    // On Unix: \n, on Windows: \r\n
    // Check that all line endings are normalized
}
```

