```zig
test "process large blob parts" {
    // Test with multi-megabyte data to ensure no stack overflow
    const large_data = try allocator.alloc(u8, 10 * 1024 * 1024); // 10MB
    defer allocator.free(large_data);
    @memset(large_data, 'x');

