**Required implementation**:
```zig
/// Navigate to src URL - fetch, parse, and create Document
fn navigateToSrc\(self: *IFrameIntegration, url: []const u8\) IFrameError\!void {
    self.state = .navigating\;

    // 1. Resolve URL against parent base URL
    const resolved_url = try resolveURL\(self.parent_context, url\)\;
    defer self.allocator.free\(resolved_url\)\;

    // 2. Fetch content \(for file:// URLs, read from disk\)
    const content = try fetchContent\(self.allocator, resolved_url\)\;
    defer self.allocator.free\(content.bytes\)\;

    // 3. Determine encoding
    const encoding = try detectEncoding\(content.bytes, content.content_type\)\;

    // 4. Parse HTML
    const parser = try HTMLParser.init\(self.allocator, .{
        .scripting_enabled = false, // Data files don't need scripts
        .encoding = encoding,
    }\)\;
    defer parser.deinit\(\)\;

    const document = try parser.parse\(content.bytes\)\;

    // 5. Create Window for document
    const window = try createWindowForDocument\(self.allocator, document\)\;

    // 6. Set origin
    const new_origin = self.parseOriginFromURL\(resolved_url\)\;
    document.setOrigin\(new_origin\)\;

    // 7. Store in browsing context
    if \(self.browsing_context\) \|ctx\| {
        ctx.setActiveDocument\(document, window\)\;
    }

    if \(self.window_proxy\) \|*proxy\| {
        proxy.setDocumentOrigin\(new_origin\)\;
        proxy.setWindow\(window\)\;
    }

    self.state = .ready\;
}
```

### 2. Encoding detection helper

```zig
/// Detect encoding per HTML §13.2.3.2
fn detectEncoding\(bytes: []const u8, content_type: ?[]const u8\) \!Encoding {
    // 1. Check for BOM
    if \(bytes.len \>= 3 and bytes[0] == 0xEF and bytes[1] == 0xBB and bytes[2] == 0xBF\) {
        return .utf8\;
    }
    if \(bytes.len \>= 2 and bytes[0] == 0xFE and bytes[1] == 0xFF\) {
        return .utf16be\;
    }
    if \(bytes.len \>= 2 and bytes[0] == 0xFF and bytes[1] == 0xFE\) {
        return .utf16le\;
    }

    // 2. Check Content-Type header charset
    if \(content_type\) \|ct\| {
        if \(parseCharsetFromContentType\(ct\)\) \|charset\| {
            return Encoding.fromLabel\(charset\) orelse .utf8\;
        }
    }

    // 3. Default to UTF-8
    return .utf8\;
}
```

### 3. navigateToSrcdoc\(\)

```zig
fn navigateToSrcdoc\(self: *IFrameIntegration, content: []const u8\) IFrameError\!void {
    self.state = .navigating\;

    // srcdoc is always UTF-8 \(it came from parent document's parsing\)
    const parser = try HTMLParser.init\(self.allocator, .{
        .scripting_enabled = false,
        .encoding = .utf8,
    }\)\;
    defer parser.deinit\(\)\;

    const document = try parser.parse\(content\)\;
    const window = try createWindowForDocument\(self.allocator, document\)\;

    // srcdoc inherits container origin
    document.setOrigin\(self.container_origin\)\;

    if \(self.browsing_context\) \|ctx\| {
        ctx.setActiveDocument\(document, window\)\;
    }

    if \(self.window_proxy\) \|*proxy\| {
        proxy.setDocumentOrigin\(self.container_origin\)\;
        proxy.setWindow\(window\)\;
    }

    self.state = .ready\;
}
```

