fn wptLoadScript\(ctx: *anyopaque, url: []const u8\) \![]const u8 {
    const self = @as\(*BrowserContext, @ptrCast\(@alignCast\(ctx\)\)\)\;

    // Resolve URL against WPT root
    var path: []const u8 = undefined\;
    if \(std.mem.startsWith\(u8, url, "/"\)\) {
        // Absolute path from WPT root
        path = try std.fs.path.join\(self.allocator, \&.{ self.wpt_root, url[1..] }\)\;
    } else {
        // Relative to current test
        path = try std.fs.path.join\(self.allocator, \&.{ self.test_dir, url }\)\;
    }
    defer self.allocator.free\(path\)\;

    return std.fs.cwd\(\).readFileAlloc\(self.allocator, path, 10 * 1024 * 1024\)\;
}
