## Helper Functions

```zig
/// Parsed URL components for cookie matching
const ParsedUrlForMatching = struct {
    scheme: []const u8,
    host: []const u8,
    path: []const u8,
    is_secure: bool,
};

/// Parse URL string for cookie domain/path matching
fn parseUrlForMatching(url_str: []const u8) !ParsedUrlForMatching {
    // Use the URL parser from src/url/
    const url = @import("url");
    const parsed = try url.URL.parse(std.heap.page_allocator, url_str);
    defer parsed.deinit();

    return ParsedUrlForMatching{
        .scheme = parsed.scheme,
        .host = if (parsed.host) |h| h.domain else "",
        .path = if (parsed.path.len > 0) parsed.path else "/",
        .is_secure = std.mem.eql(u8, parsed.scheme, "https"),
    };
}

/// Check if a cookie matches the given URL (domain and path matching per RFC 6265)
fn cookieMatchesUrl(cookie: Cookie, url: ParsedUrlForMatching) bool {
    // Domain matching (RFC 6265 Section 5.1.3)
    if (!domainMatches(cookie.domain, url.host)) {
        return false;
    }

    // Path matching (RFC 6265 Section 5.1.4)
    if (!pathMatches(cookie.path, url.path)) {
        return false;
    }

    // Secure attribute check
    if (cookie.secure and !url.is_secure) {
        return false;
    }

    return true;
}

/// RFC 6265 Section 5.1.3 - Domain Matching
/// A string domain-matches a given domain string if:
/// 1. The domain string and the string are identical, OR
/// 2. All of:
///    - The domain string is a suffix of the string
///    - The last char of the string not included in domain is a '.'
///    - The string is a host name (not an IP address)
fn domainMatches(cookie_domain: []const u8, request_host: []const u8) bool {
    // Normalize: remove leading dot from cookie domain
    const domain = if (cookie_domain.len > 0 and cookie_domain[0] == '.')
        cookie_domain[1..]
    else
        cookie_domain;

    // Exact match
    if (std.ascii.eqlIgnoreCase(domain, request_host)) {
        return true;
    }

    // Suffix match
    if (request_host.len > domain.len) {
        const suffix_start = request_host.len - domain.len;
        if (std.ascii.eqlIgnoreCase(request_host[suffix_start..], domain)) {
            // Check that preceding char is '.'
            if (request_host[suffix_start - 1] == '.') {
                return true;
            }
        }
    }

    return false;
}

/// RFC 6265 Section 5.1.4 - Path Matching
fn pathMatches(cookie_path: []const u8, request_path: []const u8) bool {
    // The cookie-path is a prefix of the request-path, AND
    // Either the cookie-path ends with '/', OR
    // The first char after cookie-path in request-path is '/'

    if (cookie_path.len == 0) return true;

    if (std.mem.startsWith(u8, request_path, cookie_path)) {
        if (cookie_path[cookie_path.len - 1] == '/') {
            return true;
        }
        if (request_path.len == cookie_path.len) {
            return true;
        }
        if (request_path.len > cookie_path.len and request_path[cookie_path.len] == '/') {
            return true;
        }
    }

    return false;
}
```

