    const isolate = getTestIsolate\(\)\;
    const scope = v8.v8_HandleScope_New\(isolate\)\;
    defer v8.v8_HandleScope_Delete\(scope\)\;

    // Create a function
    const js_func = createTestFunction\(isolate, "function\(\) { return 42\; }"\)\;

    // Convert to anyopaque
