impl EnvironmentSettingsObject {
    /// Get the API base URL \(for resolving relative URLs\)
    pub fn apiBaseUrl\(self: *EnvironmentSettingsObject\) Url {
        // For Window: document's URL
        // For Worker: worker's script URL
        if \(self.responsible_document\) \|doc\| {
            return doc.getUrl\(\)\;
        }
        return self.api_base_url\;
    }

    /// Get the origin for security checks
    pub fn getOrigin\(self: *EnvironmentSettingsObject\) Origin {
        return self.origin\;
    }

    /// Check if same origin with another settings object
    pub fn isSameOrigin\(self: *EnvironmentSettingsObject, other: *EnvironmentSettingsObject\) bool {
        return self.origin.isSameOrigin\(other.origin\)\;
    }

    /// Get the responsible document \(may be null for workers\)
    pub fn responsibleDocument\(self: *EnvironmentSettingsObject\) ?*Document {
        return self.responsible_document\;
    }
}
