Create helper utilities for impl files to properly manage callback lifecycle, reducing boilerplate and ensuring consistent disposal.

## Target API

```zig
// src/webidl/impls/callback_helpers.zig

pub const CallbackStorage = struct {
    allocator: Allocator,
    callbacks: std.ArrayList\(Algorithm\),

    pub fn init\(allocator: Allocator\) CallbackStorage {
        return .{
            .allocator = allocator,
            .callbacks = std.ArrayList\(Algorithm\).init\(allocator\),
        }\;
    }

    pub fn deinit\(self: *CallbackStorage\) void {
        for \(self.callbacks.items\) \|*cb\| {
            cb.deinit\(\)\;
        }
        self.callbacks.deinit\(\)\;
    }

    pub fn add\(self: *CallbackStorage, callback: Algorithm\) \!usize {
        const index = self.callbacks.items.len\;
        try self.callbacks.append\(callback.clone\(\)\)\;
        return index\;
    }

    pub fn remove\(self: *CallbackStorage, index: usize\) void {
        if \(index \< self.callbacks.items.len\) {
            self.callbacks.items[index].deinit\(\)\;
            _ = self.callbacks.orderedRemove\(index\)\;
        }
    }

    pub fn replace\(self: *CallbackStorage, index: usize, callback: Algorithm\) void {
        if \(index \< self.callbacks.items.len\) {
            self.callbacks.items[index].deinit\(\)\;
            self.callbacks.items[index] = callback.clone\(\)\;
        }
    }
}\;

/// For single optional callbacks
pub const OptionalCallback = struct {
    callback: ?Algorithm,

    pub fn init\(\) OptionalCallback {
        return .{ .callback = null }\;
    }

    pub fn deinit\(self: *OptionalCallback\) void {
        if \(self.callback\) \|*cb\| cb.deinit\(\)\;
    }

    pub fn set\(self: *OptionalCallback, callback: Algorithm\) void {
        if \(self.callback\) \|*old\| old.deinit\(\)\;
        self.callback = callback.clone\(\)\;
    }

    pub fn clear\(self: *OptionalCallback\) void {
        if \(self.callback\) \|*cb\| {
            cb.deinit\(\)\;
            self.callback = null\;
        }
    }

    pub fn get\(self: *OptionalCallback\) ?Algorithm {
        return self.callback\;
    }
}\;
```

