// src/webidl/impls/EventTarget.zig
const Internal = struct {
    listeners: CallbackStorage,

    pub fn init\(allocator: Allocator\) Internal {
        return .{
            .listeners = CallbackStorage.init\(allocator\),
        }\;
    }

    pub fn deinit\(self: *Internal\) void {
        self.listeners.deinit\(\)\;
    }

    pub fn addEventListener\(self: *Internal, callback: Algorithm\) \!usize {
        return try self.listeners.add\(callback\)\;
    }

    pub fn removeEventListener\(self: *Internal, index: usize\) void {
        self.listeners.remove\(index\)\;
    }
