## WebIDL Definition (from specs/idl/cookiestore.idl)
```idl
[Exposed=(ServiceWorker,Window),
 SecureContext]
interface CookieStore : EventTarget {
  Promise<CookieListItem?> get(USVString name);
  Promise<CookieListItem?> get(optional CookieStoreGetOptions options = {});
  Promise<CookieList> getAll(USVString name);
  Promise<CookieList> getAll(optional CookieStoreGetOptions options = {});
  Promise<undefined> set(USVString name, USVString value);
  Promise<undefined> set(CookieInit options);
  Promise<undefined> delete(USVString name);
  Promise<undefined> delete(CookieStoreDeleteOptions options);

  attribute EventHandler onchange;
};

dictionary CookieStoreGetOptions {
  USVString name;
  USVString url;
};

dictionary CookieInit {
  required USVString name;
  required USVString value;
  DOMHighResTimeStamp? expires = null;
  USVString? domain = null;
  USVString path = "/";
  CookieSameSite sameSite = "strict";
  boolean partitioned = false;
};

dictionary CookieStoreDeleteOptions {
  required USVString name;
  USVString? domain = null;
  USVString path = "/";
  boolean partitioned = false;
};

dictionary CookieListItem {
  USVString name;
  USVString value;
  USVString? domain;
  USVString path;
  DOMHighResTimeStamp? expires;
  boolean secure;
  CookieSameSite sameSite;
  boolean partitioned;
};

enum CookieSameSite {
  "strict",
  "lax",
  "none"
};

typedef sequence<CookieListItem> CookieList;
```

## Implementation

```zig
const std = @import("std");
const Allocator = std.mem.Allocator;
const webidl = @import("webidl");
const EventTarget = @import("EventTarget.zig");
const CurlCookieManager = @import("../../fetch/network/curl_cookies.zig").CurlCookieManager;
const Cookie = @import("../../fetch/network/curl_cookies.zig").Cookie;

/// CookieStore implementation
/// Wraps CurlCookieManager to provide WebIDL-compliant cookie access
pub const CookieStore = struct {
    /// Inherit from EventTarget
    event_target: EventTarget,

    /// Underlying cookie manager (shared across the application)
    cookie_manager: *CurlCookieManager,

    /// The URL context for this CookieStore (used for defaults)
    context_url: ?[]const u8,

    /// Allocator
    allocator: Allocator,

    /// Initialize CookieStore with a shared cookie manager
    pub fn init(
        allocator: Allocator,
        cookie_manager: *CurlCookieManager,
        context_url: ?[]const u8,
    ) !*CookieStore {
        const self = try allocator.create(CookieStore);
        errdefer allocator.destroy(self);

        self.* = .{
            .event_target = try EventTarget.init(allocator),
            .cookie_manager = cookie_manager,
            .context_url = if (context_url) |u| try allocator.dupe(u8, u) else null,
            .allocator = allocator,
        };

        return self;
    }

    pub fn deinit(self: *CookieStore) void {
        if (self.context_url) |url| {
            self.allocator.free(url);
        }
        self.event_target.deinit();
        self.allocator.destroy(self);
    }

    // ============================================================
    // WebIDL Methods
    // ============================================================

    /// get(USVString name) -> Promise<CookieListItem?>
    /// get(CookieStoreGetOptions options) -> Promise<CookieListItem?>
    pub fn get(
        self: *CookieStore,
        name_or_options: GetArg,
    ) !?CookieListItem {
        const name = switch (name_or_options) {
            .name => |n| n,
            .options => |opts| opts.name,
        };

        const url = switch (name_or_options) {
            .name => self.context_url,
            .options => |opts| opts.url orelse self.context_url,
        };

        const cookie = try self.cookie_manager.get(name, url);
        if (cookie) |c| {
            defer c.deinit();
            return cookieToListItem(self.allocator, c);
        }
        return null;
    }

    /// getAll(USVString name) -> Promise<CookieList>
    /// getAll(CookieStoreGetOptions options) -> Promise<CookieList>
    pub fn getAll(
        self: *CookieStore,
        name_or_options: ?GetArg,
    ) !std.ArrayList(CookieListItem) {
        const name = if (name_or_options) |arg| switch (arg) {
            .name => |n| n,
            .options => |opts| opts.name,
        } else null;

        const url = if (name_or_options) |arg| switch (arg) {
            .name => self.context_url,
            .options => |opts| opts.url orelse self.context_url,
        } else self.context_url;

        var cookies = try self.cookie_manager.getAll(name, url);
        defer {
            for (cookies.items) |*c| c.deinit();
            cookies.deinit();
        }

        var items = std.ArrayList(CookieListItem).init(self.allocator);
        errdefer {
            for (items.items) |*item| item.deinit(self.allocator);
            items.deinit();
        }

        for (cookies.items) |cookie| {
            try items.append(try cookieToListItem(self.allocator, cookie));
        }

        return items;
    }

    /// set(USVString name, USVString value) -> Promise<undefined>
    /// set(CookieInit options) -> Promise<undefined>
    pub fn set(
        self: *CookieStore,
        name_or_options: SetArg,
    ) !void {
        const options = switch (name_or_options) {
            .name_value => |nv| CurlCookieManager.CookieInit{
                .name = nv.name,
                .value = nv.value,
            },
            .options => |opts| CurlCookieManager.CookieInit{
                .name = opts.name,
                .value = opts.value,
                .domain = opts.domain,
                .path = opts.path,
                .expires = opts.expires,
                .same_site = sameSiteFromString(opts.sameSite),
                .partitioned = opts.partitioned,
            },
        };

        try self.cookie_manager.set(options, self.context_url);

        // Fire change event
        try self.fireChangeEvent(.{ .changed = &[_]CookieListItem{
            try cookieToListItem(self.allocator, Cookie{
                .name = options.name,
                .value = options.value,
                .domain = options.domain orelse "",
                .path = options.path orelse "/",
                .expires = options.expires,
                .secure = options.secure orelse false,
                .same_site = options.same_site orelse .lax,
                .http_only = false,
                .allocator = self.allocator,
            }),
        }});
    }

    /// delete(USVString name) -> Promise<undefined>
    /// delete(CookieStoreDeleteOptions options) -> Promise<undefined>
    pub fn delete(
        self: *CookieStore,
        name_or_options: DeleteArg,
    ) !void {
        const options = switch (name_or_options) {
            .name => |n| CurlCookieManager.CookieDeleteOptions{ .name = n },
            .options => |opts| CurlCookieManager.CookieDeleteOptions{
                .name = opts.name,
                .domain = opts.domain,
                .path = opts.path,
                .partitioned = opts.partitioned,
            },
        };

        try self.cookie_manager.delete(options, self.context_url);

        // Fire change event
        try self.fireChangeEvent(.{ .deleted = &[_]CookieListItem{
            .{
                .name = try self.allocator.dupe(u8, options.name),
                .value = try self.allocator.dupe(u8, ""),
                .domain = if (options.domain) |d| try self.allocator.dupe(u8, d) else null,
                .path = try self.allocator.dupe(u8, options.path orelse "/"),
                .expires = null,
                .secure = false,
                .sameSite = .strict,
                .partitioned = options.partitioned orelse false,
            },
        }});
    }

    // ============================================================
    // Event Handling
    // ============================================================

    fn fireChangeEvent(self: *CookieStore, changes: CookieChangeEventInit) !void {
        _ = self;
        _ = changes;
        // TODO: Create and dispatch CookieChangeEvent
        // Requires CookieChangeEvent implementation (Phase 5)
    }

    // ============================================================
    // Helper Types
    // ============================================================

    pub const GetArg = union(enum) {
        name: []const u8,
        options: CookieStoreGetOptions,
    };

    pub const SetArg = union(enum) {
        name_value: struct { name: []const u8, value: []const u8 },
        options: CookieInit,
    };

    pub const DeleteArg = union(enum) {
        name: []const u8,
        options: CookieStoreDeleteOptions,
    };

    pub const CookieStoreGetOptions = struct {
        name: ?[]const u8 = null,
        url: ?[]const u8 = null,
    };

    pub const CookieInit = struct {
        name: []const u8,
        value: []const u8,
        expires: ?i64 = null,
        domain: ?[]const u8 = null,
        path: ?[]const u8 = "/",
        sameSite: []const u8 = "strict",
        partitioned: bool = false,
    };

    pub const CookieStoreDeleteOptions = struct {
        name: []const u8,
        domain: ?[]const u8 = null,
        path: ?[]const u8 = "/",
        partitioned: ?bool = null,
    };

    pub const CookieListItem = struct {
        name: []const u8,
        value: []const u8,
        domain: ?[]const u8,
        path: []const u8,
        expires: ?i64,
        secure: bool,
        sameSite: SameSite,
        partitioned: bool,

        pub const SameSite = enum { strict, lax, none };

        pub fn deinit(self: *CookieListItem, allocator: Allocator) void {
            allocator.free(self.name);
            allocator.free(self.value);
            if (self.domain) |d| allocator.free(d);
            allocator.free(self.path);
        }
    };

    pub const CookieChangeEventInit = struct {
        changed: ?[]const CookieListItem = null,
        deleted: ?[]const CookieListItem = null,
    };
};

// ============================================================
// Helper Functions
// ============================================================

fn cookieToListItem(allocator: Allocator, cookie: Cookie) !CookieStore.CookieListItem {
    return .{
        .name = try allocator.dupe(u8, cookie.name),
        .value = try allocator.dupe(u8, cookie.value),
        .domain = if (cookie.domain.len > 0) try allocator.dupe(u8, cookie.domain) else null,
        .path = try allocator.dupe(u8, cookie.path),
        .expires = cookie.expires,
        .secure = cookie.secure,
        .sameSite = switch (cookie.same_site) {
            .strict => .strict,
            .lax => .lax,
            .none => .none,
        },
        .partitioned = false, // TODO: CHIPS support
    };
}

fn sameSiteFromString(str: []const u8) Cookie.SameSite {
    if (std.mem.eql(u8, str, "strict")) return .strict;
    if (std.mem.eql(u8, str, "lax")) return .lax;
    if (std.mem.eql(u8, str, "none")) return .none;
    return .strict; // Default
}
```

