}

test "getPropertyType - script text requires TrustedScript" {
    try std.testing.expectEqualStrings(TRUSTED_SCRIPT, getPropertyType("script", "text", null).?);
    try std.testing.expectEqualStrings(TRUSTED_SCRIPT, getPropertyType("script", "innerText", null).?);
