## Overview

Extend the V8 Global handle FFI to support **weak handles** with GC callbacks. This enables automatic cleanup when JavaScript no longer references a value.

## Background

V8 Global handles can be:
- **Strong**: Prevents GC from collecting the value
- **Weak**: Allows GC to collect, triggers callback when collected

For dictionary conversion, we need weak handles so:
1. Callbacks can be stored beyond HandleScope lifetime
2. V8 GC can clean them up when JS drops references
3. No manual disposal tracking needed

## Implementation

### Step 1: Add C++ weak handle functions to v8_wrapper.cpp

```cpp
#include \<v8.h\>
using namespace v8\;

// Weak callback type
typedef void \(*weak_callback_fn\)\(void* data\)\;

// Storage for weak callback info
struct WeakCallbackInfo {
    Global\<Value\>* handle\;
    void* user_data\;
    weak_callback_fn callback\;
}\;

// Static weak callback that V8 calls when object is about to be GC'd
static void weakCallbackHandler\(const WeakCallbackInfo\<WeakCallbackInfo\>\& data\) {
    WeakCallbackInfo* info = data.GetParameter\(\)\;

    // Call user callback if provided
    if \(info-\>callback \!= nullptr\) {
        info-\>callback\(info-\>user_data\)\;
    }

    // Clean up the Global handle
    info-\>handle-\>Reset\(\)\;
    delete info-\>handle\;
    delete info\;
}

// Create a weak Global\<Value\> from a Local\<Value\>
// When V8 GC collects this value, callback\(user_data\) is called
extern "C" Global\<Value\>* v8_Value_ToWeakGlobal\(
    Isolate* isolate,
    Local\<Value\> local,
    void* user_data,
    weak_callback_fn callback
\) {
    if \(local.IsEmpty\(\)\) {
        return nullptr\;
    }

    // Create the Global handle
    Global\<Value\>* global = new Global\<Value\>\(isolate, local\)\;

    // Create callback info
    WeakCallbackInfo* info = new WeakCallbackInfo\(\)\;
    info-\>handle = global\;
    info-\>user_data = user_data\;
    info-\>callback = callback\;

    // Make it weak with our callback
    global-\>SetWeak\(info, weakCallbackHandler, WeakCallbackType::kParameter\)\;

    return global\;
}

// Make an existing strong Global handle weak
extern "C" void v8_Global_MakeWeak\(
    Global\<Value\>* global,
    void* user_data,
    weak_callback_fn callback
\) {
    if \(global == nullptr \|\| global-\>IsEmpty\(\)\) {
        return\;
    }

    WeakCallbackInfo* info = new WeakCallbackInfo\(\)\;
    info-\>handle = global\;
    info-\>user_data = user_data\;
    info-\>callback = callback\;

    global-\>SetWeak\(info, weakCallbackHandler, WeakCallbackType::kParameter\)\;
}

// Convert weak Global back to strong \(prevents GC\)
extern "C" void v8_Global_ClearWeak\(Global\<Value\>* global\) {
    if \(global \!= nullptr \&\& \!global-\>IsEmpty\(\)\) {
        global-\>ClearWeak\(\)\;
    }
}

// Check if Global handle is weak
extern "C" bool v8_Global_IsWeak\(Global\<Value\>* global\) {
    if \(global == nullptr \|\| global-\>IsEmpty\(\)\) {
        return false\;
    }
    return global-\>IsWeak\(\)\;
}
```

### Step 2: Add Zig FFI declarations to ffi.zig

```zig
/// Callback function type for weak handle GC notification
pub const WeakCallbackFn = *const fn \(user_data: ?*anyopaque\) callconv\(.C\) void\;

/// Create a weak Global\<Value\> handle from a Local\<Value\>
/// When V8 GC collects this value, callback\(user_data\) is called
/// Returns null if the local value is empty
/// The handle is automatically disposed when GC collects it
pub extern fn v8_Value_ToWeakGlobal\(
    isolate: *Isolate,
    local: *Value,
    user_data: ?*anyopaque,
    callback: ?WeakCallbackFn,
\) ?*Value\;

/// Make an existing strong Global handle weak
/// callback\(user_data\) will be called when V8 GC collects the value
pub extern fn v8_Global_MakeWeak\(
    global: *Value,
    user_data: ?*anyopaque,
    callback: ?WeakCallbackFn,
\) void\;

/// Convert weak Global back to strong \(prevents GC\)
pub extern fn v8_Global_ClearWeak\(global: *Value\) void\;

/// Check if Global handle is weak
pub extern fn v8_Global_IsWeak\(global: ?*Value\) bool\;
```

### Step 3: Add Zig wrapper in global_handles.zig

```zig
/// Create a weak Global handle that V8 can GC when JS drops references
/// Optionally calls callback with user_data when GC collects the value
pub fn createWeak\(
    isolate: *ffi.Isolate,
    local: *ffi.Value,
    user_data: ?*anyopaque,
    callback: ?ffi.WeakCallbackFn,
\) ?GlobalHandle {
    const global_ptr = ffi.v8_Value_ToWeakGlobal\(isolate, local, user_data, callback\)\;
    if \(global_ptr\) \|ptr\| {
        return GlobalHandle{ .ptr = ptr, .is_weak = true }\;
    }
    return null\;
}

/// Make this handle weak \(allows GC to collect\)
pub fn makeWeak\(
    self: *GlobalHandle,
    user_data: ?*anyopaque,
    callback: ?ffi.WeakCallbackFn,
\) void {
    ffi.v8_Global_MakeWeak\(self.ptr, user_data, callback\)\;
    self.is_weak = true\;
}

/// Make this handle strong again \(prevents GC\)
pub fn clearWeak\(self: *GlobalHandle\) void {
    ffi.v8_Global_ClearWeak\(self.ptr\)\;
    self.is_weak = false\;
}

/// Check if handle is weak
pub fn isWeak\(self: GlobalHandle\) bool {
    return ffi.v8_Global_IsWeak\(self.ptr\)\;
}
```

