### Phase 1: Core Script Execution

#### JSC Script Execution
```zig
// src/runtime/engines/jsc/script.zig

pub fn compileScript(
    context: ffi.JSContextRef,
    source: []const u8,
    filename: []const u8,
) \!ffi.JSObjectRef {
    // Create JSString from source
    const js_source = ffi.JSStringCreateWithUTF8CString(source.ptr);
    defer ffi.JSStringRelease(js_source);

    const js_filename = ffi.JSStringCreateWithUTF8CString(filename.ptr);
    defer ffi.JSStringRelease(js_filename);

    // Check syntax first
    var exception: ffi.JSValueRef = null;
    const syntax_ok = ffi.JSCheckScriptSyntax(
        context, js_source, js_filename, 1, &exception
    );

    if (\!syntax_ok) {
        return extractError(context, exception);
    }

    // JSC doesn't have separate compile/run - store source for later
    return createScriptObject(context, source, filename);
}

pub fn runScript(
    context: ffi.JSContextRef,
    script_obj: ffi.JSObjectRef,
) \!ffi.JSValueRef {
    const source = getScriptSource(script_obj);
    const filename = getScriptFilename(script_obj);

    var exception: ffi.JSValueRef = null;
    const result = ffi.JSEvaluateScript(
        context,
        source,
        null,  // thisObject
        filename,
        1,     // startingLineNumber
        &exception,
    );

    if (exception \!= null) {
        return extractError(context, exception);
    }

    return result;
}
```

#### QuickJS Script Execution
```zig
// src/runtime/engines/quickjs/script.zig

pub fn compileScript(
    context: *ffi.JSContext,
    source: []const u8,
    filename: []const u8,
) \!*BoxedJSValue {
    const compiled = ffi.JS_Eval(
        context,
        source.ptr,
        source.len,
        filename.ptr,
        ffi.JS_EVAL_FLAG_COMPILE_ONLY,
    );

    if (ffi.JS_IsException(compiled)) {
        return extractError(context);
    }

    return boxValue(context, compiled);
}

pub fn runScript(
    context: *ffi.JSContext,
    compiled: *BoxedJSValue,
) \!*BoxedJSValue {
    const result = ffi.JS_EvalFunction(context, compiled.value);

    if (ffi.JS_IsException(result)) {
        return extractError(context);
    }

    return boxValue(context, result);
}

// QuickJS JSValue is a struct - need to box for pointer semantics
const BoxedJSValue = struct {
    value: ffi.JSValue,
    context: *ffi.JSContext,

    pub fn deinit(self: *BoxedJSValue) void {
        ffi.JS_FreeValue(self.context, self.value);
    }
};

fn boxValue(context: *ffi.JSContext, value: ffi.JSValue) \!*BoxedJSValue {
    const boxed = try allocator.create(BoxedJSValue);
    boxed.* = .{
        .value = value,
        .context = context,
    };
    return boxed;
}
```

