}

pub fn getProperty(
    context: ffi.JSContextRef,
    object: ffi.JSObjectRef,
    key: []const u8,
) \!ffi.JSValueRef {
    const js_key = ffi.JSStringCreateWithUTF8CString(key.ptr);
    defer ffi.JSStringRelease(js_key);

    var exception: ffi.JSValueRef = null;
    const value = ffi.JSObjectGetProperty(context, object, js_key, &exception);

    if (exception \!= null) {
        return extractError(context, exception);
    }

    return value;
}

