    context: ffi.JSContextRef,
    object: ffi.JSObjectRef,
    key: []const u8,
    value: ffi.JSValueRef,
) \!void {
    const js_key = ffi.JSStringCreateWithUTF8CString(key.ptr);
    defer ffi.JSStringRelease(js_key);

    var exception: ffi.JSValueRef = null;
    ffi.JSObjectSetProperty(
        context, object, js_key, value,
