### Phase 3: Promise Support

#### JSC Promise Implementation
```zig
pub const JSCPromiseHandle = struct {
    context: ffi.JSContextRef,
    promise: ffi.JSObjectRef,
    resolve_fn: ffi.JSObjectRef,
    reject_fn: ffi.JSObjectRef,
};

pub fn createPromise(context: ffi.JSContextRef) \!*JSCPromiseHandle {
    // JSC requires creating promise via JavaScript
    const script = 
        \\(function() {
        \\    var resolve, reject;
        \\    var promise = new Promise(function(res, rej) {
        \\        resolve = res;
        \\        reject = rej;
        \\    });
        \\    return { promise: promise, resolve: resolve, reject: reject };
        \\})()
    ;

    var exception: ffi.JSValueRef = null;
    const result = ffi.JSEvaluateScript(context, script, null, null, 1, &exception);

    if (exception \!= null) return extractError(context, exception);

    const handle = try allocator.create(JSCPromiseHandle);
    handle.* = .{
        .context = context,
        .promise = ffi.JSValueToObject(context, getProperty(result, "promise"), null),
        .resolve_fn = ffi.JSValueToObject(context, getProperty(result, "resolve"), null),
        .reject_fn = ffi.JSValueToObject(context, getProperty(result, "reject"), null),
    };

    return handle;
}

pub fn resolvePromise(handle: *JSCPromiseHandle, value: ffi.JSValueRef) \!void {
    var exception: ffi.JSValueRef = null;
    var args = [_]ffi.JSValueRef{value};

    _ = ffi.JSObjectCallAsFunction(
        handle.context,
        handle.resolve_fn,
        null,
        1,
        &args,
        &exception,
    );

    if (exception \!= null) return extractError(handle.context, exception);
}
```

