```

## Solution

Make ManagedHandle generic over the handle type:

```zig
pub fn ManagedHandle\(comptime HandleType: type\) type {
    return struct {
        inner: *Inner,

        const Inner = struct {
            ref_count: std.atomic.Value\(u32\),
            ptr: *HandleType,
            allocator: Allocator,
            dispose_fn: ?*const fn \(*HandleType\) void,
            disposed: bool,
        }\;

        pub fn get\(self: @This\(\)\) *HandleType {
            return self.inner.ptr\;
        }
    }\;
}

// Type alias for V8 handles
pub const V8Handle = ManagedHandle\(v8.ffi.Value\)\;
