### 2. Implement createChildContext

```zig
/// Create a new V8 context for a child browsing context \(iframe\)
pub fn createChildContext\(
    parent_context: v8.Context,
    isolate: v8.Isolate,
    browsing_context: *BrowsingContext,
    allocator: std.mem.Allocator,
\) \!*ContextEntry {
    // 1. Create new global template with immutable prototype
    const global_template = v8.v8_ObjectTemplate_New\(isolate\)\;
    v8.v8_ObjectTemplate_SetImmutableProto\(global_template\)\;

    // 2. Set internal field count for Window binding
    v8.v8_ObjectTemplate_SetInternalFieldCount\(global_template, 2\)\;

    // 3. Create new V8 context
    const child_context = v8.v8_Context_NewWithGlobalTemplate\(isolate, global_template\)\;

    // 4. Enter the new context for initialization
    v8.v8_Context_Enter\(child_context\)\;
    defer v8.v8_Context_Exit\(child_context\)\;

    // 5. Initialize all interface bindings in new context
    try interface_bindings.initializeBindings\(isolate, child_context\)\;

    // 6. Create realm for new context
    const realm = try Realm.init\(
        allocator,
        isolate,
        child_context,
        .window,
        browsing_context,
    \)\;

    // 7. Create runtime context data
    const runtime_ctx = try ContextData.init\(allocator\)\;
    runtime_ctx.realm = realm\;

    // 8. Create context entry
    const entry = try allocator.create\(ContextEntry\)\;
    entry.* = .{
        .v8_ctx = child_context,
        .runtime_ctx = runtime_ctx,
        .realm = realm,
        .ownership = true,
        .event_loop = null, // Inherit from parent? Or create new?
        .parent_entry = getEntry\(parent_context\),
        .children = .{},
    }\;

    // 9. Register in context map
    try registerEntry\(child_context, entry\)\;

    // 10. Link to parent
    if \(entry.parent_entry\) \|parent\| {
        try parent.children.append\(allocator, entry\)\;
    }

    return entry\;
}
```

### 3. Add Context Cleanup

```zig
/// Destroy a child context and clean up resources
pub fn destroyChildContext\(entry: *ContextEntry, allocator: std.mem.Allocator\) void {
    // 1. Recursively destroy children first
    for \(entry.children.items\) \|child\| {
        destroyChildContext\(child, allocator\)\;
    }
    entry.children.deinit\(allocator\)\;

    // 2. Remove from parent's children list
    if \(entry.parent_entry\) \|parent\| {
        for \(parent.children.items, 0..\) \|child, i\| {
            if \(child == entry\) {
                _ = parent.children.swapRemove\(i\)\;
                break\;
            }
        }
    }

    // 3. Destroy realm
    if \(entry.realm\) \|realm\| {
        realm.deinit\(\)\;
    }

    // 4. Destroy runtime context
    entry.runtime_ctx.deinit\(\)\;

    // 5. Remove from context map
    unregisterEntry\(entry.v8_ctx\)\;

    // 6. Free entry
    allocator.destroy\(entry\)\;
}
```

### 4. Add Realm Lookup

```zig
/// Get the realm for a V8 context
pub fn getRealmForContext\(context: v8.Context\) ?*Realm {
    const entry = getEntry\(context\) orelse return null\;
    return entry.realm\;
}

/// Get the realm for the current V8 context
pub fn getCurrentRealm\(isolate: v8.Isolate\) ?*Realm {
    const context = v8.v8_Isolate_GetCurrentContext\(isolate\)\;
    return getRealmForContext\(context\)\;
}
```

