    const proto1 = getElementPrototype\(ctx1\)\;
    v8.v8_Context_Exit\(ctx1\)\;

    v8.v8_Context_Enter\(ctx2\)\;
    const proto2 = getElementPrototype\(ctx2\)\;
    v8.v8_Context_Exit\(ctx2\)\;

    // They MUST be different objects
    try testing.expect\(\!v8.v8_Value_StrictEquals\(proto1, proto2\)\)\;
}
```

### 3. Verify Cross-Realm instanceof

```zig
test "cross-realm instanceof returns false" {
    const ctx1 = createContext\(isolate\)\;
    const ctx2 = createContext\(isolate\)\;

    // Create an Element in ctx1
    v8.v8_Context_Enter\(ctx1\)\;
    const element = createElement\(ctx1, "div"\)\;
    v8.v8_Context_Exit\(ctx1\)\;

