```

## Target Code

```zig
/// Generic underlying source for Zig-native stream implementations
pub fn ZigUnderlyingSource\(comptime Context: type\) type {
    return struct {
        const Self = @This\(\)\;

        /// Pull callback - invoked when the stream needs more data
        /// context: Typed context pointer
        /// controller: The ReadableStreamDefaultController instance
        pull: ?*const fn \(controller: *runtime.Instance, context: *Context\) anyerror\!void = null,

        /// Cancel callback - invoked when the stream is cancelled
        /// reason: The cancellation reason \(JSValue\)
        /// context: Typed context pointer
        cancel: ?*const fn \(reason: runtime.JSValue, context: *Context\) anyerror\!void = null,

        /// Typed context pointer
        context: *Context,

        /// Convert to type-erased version for internal use
        pub fn toErased\(self: Self\) ErasedZigUnderlyingSource {
            return .{
                .pull = if \(self.pull\) \|p\| @ptrCast\(p\) else null,
                .cancel = if \(self.cancel\) \|c\| @ptrCast\(c\) else null,
                .context = @ptrCast\(self.context\),
            }\;
        }
    }\;
}

/// Type-erased version for internal storage \(when generic type is not known\)
pub const ErasedZigUnderlyingSource = struct {
    pull: ?*const fn \(*runtime.Instance, *anyopaque\) anyerror\!void = null,
    cancel: ?*const fn \(runtime.JSValue, *anyopaque\) anyerror\!void = null,
    context: *anyopaque,
}\;
```

