## Summary
Implement the core internal data structure for Blob byte storage in `src/file/blob_internals.zig`.

## Spec Reference
- W3C File API §3: The Blob Interface and Binary Data
- https://www.w3.org/TR/FileAPI/#blob-section

## Data Structure

```zig
const std = @import("std");

/// Internal representation of Blob data per W3C File API spec.
/// A Blob object refers to a byte sequence and has a size attribute
/// (total number of bytes) and a type attribute (ASCII-encoded string
/// in lower case representing the media type).
pub const BlobData = struct {
    /// The underlying byte sequence. Per spec, this is immutable once created.
    /// For memory efficiency, we store as a slice that may be:
    /// - Owned: allocated by this BlobData, freed on deinit
    /// - Borrowed: slice into another BlobData (for slice() results)
    bytes: []const u8,

    /// ASCII-encoded string in lower case representing the media type.
    /// Empty string if type cannot be determined.
    /// Per spec: must be parsable MIME type or empty string.
    mime_type: []const u8,

    /// Allocator used for this BlobData (for cleanup)
    allocator: std.mem.Allocator,

    /// Whether this BlobData owns its bytes (should free on deinit)
    owns_bytes: bool,

    /// Whether this BlobData owns its mime_type string
    owns_mime_type: bool,

    /// Snapshot state per spec - used for File objects to track
    /// if underlying file has changed since reference was taken.
    /// For pure Blob objects, this is always .valid
    snapshot_state: SnapshotState = .valid,

    pub const SnapshotState = enum {
        valid,
        invalid, // File was modified after reference taken
    };

    const Self = @This();

    /// Initialize a new BlobData with owned bytes
    pub fn init(
        allocator: std.mem.Allocator,
        bytes: []const u8,
        mime_type: []const u8,
    ) !*Self {
        const self = try allocator.create(Self);
        errdefer allocator.destroy(self);

        // Copy bytes
        const owned_bytes = try allocator.dupe(u8, bytes);
        errdefer allocator.free(owned_bytes);

        // Normalize and copy mime_type (lowercase, validate)
        const normalized_type = try normalizeMimeType(allocator, mime_type);

        self.* = .{
            .bytes = owned_bytes,
            .mime_type = normalized_type,
            .allocator = allocator,
            .owns_bytes = true,
            .owns_mime_type = true,
        };

        return self;
    }

    /// Initialize from existing bytes without copying (borrowed)
    pub fn initBorrowed(
        allocator: std.mem.Allocator,
        bytes: []const u8,
        mime_type: []const u8,
    ) !*Self {
        const self = try allocator.create(Self);

        self.* = .{
            .bytes = bytes,
            .mime_type = mime_type,
            .allocator = allocator,
            .owns_bytes = false,
            .owns_mime_type = false,
        };

        return self;
    }

    pub fn deinit(self: *Self) void {
        if (self.owns_bytes) {
            self.allocator.free(self.bytes);
        }
        if (self.owns_mime_type and self.mime_type.len > 0) {
            self.allocator.free(self.mime_type);
        }
        self.allocator.destroy(self);
    }

    /// Get the size in bytes (spec: Blob.size attribute)
    pub fn size(self: *const Self) u64 {
        return @intCast(self.bytes.len);
    }

    /// Get the MIME type (spec: Blob.type attribute)
    pub fn getType(self: *const Self) []const u8 {
        return self.mime_type;
    }

    /// Normalize MIME type per spec:
    /// - Convert to ASCII lowercase
    /// - Return empty string if contains chars outside U+0020-U+007E
    fn normalizeMimeType(allocator: std.mem.Allocator, input: []const u8) ![]const u8 {
        if (input.len == 0) return "";

        // Check for invalid characters
        for (input) |c| {
            if (c < 0x20 or c > 0x7E) {
                return ""; // Invalid, return empty
            }
        }

        // Convert to lowercase
        const result = try allocator.alloc(u8, input.len);
        for (input, 0..) |c, i| {
            result[i] = std.ascii.toLower(c);
        }

        return result;
    }
};
```

## Spec Compliance Notes

### Size Attribute (§3.2)
- Returns total number of bytes that can be read
- Returns 0 if Blob has no bytes

### Type Attribute (§3.2)
- ASCII-encoded string in lowercase
- Must be parsable MIME type or empty string
- Characters must be in range U+0020 to U+007E

### Snapshot State (§3)
- Each Blob has internal snapshot state
- Initially set to state of underlying storage
- Used primarily for File objects to detect modifications

## Testing Requirements
```zig
test "BlobData - init with bytes" {
    const allocator = std.testing.allocator;
    const data = try BlobData.init(allocator, "hello world", "text/plain");
    defer data.deinit();

    try std.testing.expectEqual(@as(u64, 11), data.size());
    try std.testing.expectEqualStrings("text/plain", data.getType());
}

test "BlobData - mime type normalization" {
    const allocator = std.testing.allocator;
    const data = try BlobData.init(allocator, "", "TEXT/PLAIN");
    defer data.deinit();

    try std.testing.expectEqualStrings("text/plain", data.getType());
}

test "BlobData - invalid mime type chars" {
    const allocator = std.testing.allocator;
    const data = try BlobData.init(allocator, "", "text/plain\x00");
    defer data.deinit();

    try std.testing.expectEqualStrings("", data.getType());
}

test "BlobData - empty blob" {
    const allocator = std.testing.allocator;
    const data = try BlobData.init(allocator, "", "");
    defer data.deinit();

    try std.testing.expectEqual(@as(u64, 0), data.size());
    try std.testing.expectEqualStrings("", data.getType());
}
```

## Acceptance Criteria
- [ ] BlobData struct defined with all required fields
- [ ] init() creates owned copy of bytes and mime_type
- [ ] initBorrowed() creates non-owning reference
- [ ] deinit() properly frees owned resources
- [ ] size() returns byte count
- [ ] getType() returns normalized mime type
- [ ] MIME type normalization follows spec (lowercase, char range validation)
- [ ] All tests pass
- [ ] Memory leak tests pass with std.testing.allocator

