```zig
pub fn CollectionMixin\(comptime Self: type, comptime ElementType: type\) type {
    return struct {
        pub fn get_length\(instance: *runtime.Instance\) anyerror\!u32 {
            const internal = Self.getInternal\(instance\) orelse return 0\;
            return @intCast\(internal.elements.size\(\)\)\;
        }

        pub fn call_item\(instance: *runtime.Instance, index: u32\) anyerror\!?*ElementType {
            const internal = Self.getInternal\(instance\) orelse return null\;
            if \(index \>= internal.elements.size\(\)\) return null\;
            return internal.elements.get\(index\)\;
        }

        // Optional: call_namedItem for HTMLCollection-like types
        pub fn call_namedItem\(
            instance: *runtime.Instance, 
            name: runtime.DOMString,
            comptime matchFn: fn\(*ElementType, runtime.DOMString\) bool,
        \) anyerror\!?*ElementType {
            const internal = Self.getInternal\(instance\) orelse return null\;
            for \(internal.elements.toSlice\(\)\) \|element\| {
                if \(matchFn\(element, name\)\) return element\;
            }
            return null\;
        }
    }\;
}
```

