### 1. browser_context.zig - Add iframe loading callback

```zig
/// Callback for iframe element insertion during parsing
pub fn onIframeInserted\(
    self: *BrowserContext,
    iframe_element: *runtime.Instance,
    src: []const u8,
\) \!void {
    if \(src.len == 0\) return\;

    // 1. Resolve src URL relative to test file
    const test_dir = std.fs.path.dirname\(self.test_path\) orelse "."\;
    const iframe_path = try std.fs.path.join\(
        self.allocator,
        \&.{ self.wpt_root, test_dir, src }
    \)\;
    defer self.allocator.free\(iframe_path\)\;

    // 2. Check for .headers file
    const charset = try self.readHeadersFileCharset\(iframe_path\)\;

    // 3. Read iframe content
    const content = try std.fs.cwd\(\).readFileAlloc\(
        self.allocator, 
        iframe_path, 
        10 * 1024 * 1024  // 10MB max for big charset files
    \)\;
    defer self.allocator.free\(content\)\;

    // 4. Get encoding from charset or detect
    const encoding = if \(charset\) \|cs\|
        Encoding.fromLabel\(cs\) orelse .utf8
    else
        detectEncoding\(content, null\)\;

    // 5. Parse HTML with encoding
    const document = try self.parseIframeContent\(content, encoding\)\;

    // 6. Store in iframe's browsing context
    const iframe_impl = HTMLIFrameElement.getInternal\(iframe_element\) orelse return\;
    if \(iframe_impl.integration.browsing_context\) \|ctx\| {
        const window = try createWindowForDocument\(self.allocator, document\)\;
        ctx.setActiveDocument\(document, window\)\;
    }

    // 7. Fire load event on iframe
    try self.fireEvent\(iframe_element, "load"\)\;
}

/// Read charset from .headers file if it exists
fn readHeadersFileCharset\(self: *BrowserContext, file_path: []const u8\) \!?[]const u8 {
    const headers_path = try std.fmt.allocPrint\(
        self.allocator,
        "{s}.headers",
        .{file_path}
    \)\;
    defer self.allocator.free\(headers_path\)\;

    const headers_content = std.fs.cwd\(\).readFileAlloc\(
        self.allocator,
        headers_path,
        4096
    \) catch return null\;
    defer self.allocator.free\(headers_content\)\;

    // Parse "Content-Type: text/html\; charset=big5"
    return parseCharsetFromHeaders\(headers_content\)\;
}

/// Parse charset from headers file content
fn parseCharsetFromHeaders\(content: []const u8\) ?[]const u8 {
    var lines = std.mem.splitScalar\(u8, content, '\n'\)\;
    while \(lines.next\(\)\) \|line\| {
        const trimmed = std.mem.trim\(u8, line, \&.{ ' ', '\t', '\r' }\)\;
        if \(std.ascii.startsWithIgnoreCase\(trimmed, "content-type:"\)\) {
            const value = trimmed["content-type:".len..]\;
            // Find charset= parameter
            if \(std.mem.indexOf\(u8, std.ascii.lowerString\(value\), "charset="\)\) \|idx\| {
                const charset_start = idx + "charset=".len\;
                // Find end of charset value \(semicolon or end\)
                var charset_end = charset_start\;
                while \(charset_end \< value.len and 
                       value[charset_end] \!= '\;' and 
                       value[charset_end] \!= ' '\) {
                    charset_end += 1\;
                }
                return std.mem.trim\(u8, value[charset_start..charset_end], "\"'"\)\;
            }
        }
    }
    return null\;
}
```

