/// Callback type for element insertion
pub const ElementInsertedCallback = *const fn\(
    element: *runtime.Instance,
    tag_name: []const u8
\) void\;

/// Set callback for element insertion events
pub fn setElementInsertedCallback\(self: *TreeBuilder, callback: ElementInsertedCallback\) void {
    self.element_inserted_callback = callback\;
}

/// Called when element is inserted into tree
fn notifyElementInserted\(self: *TreeBuilder, element: *runtime.Instance, tag_name: []const u8\) void {
    if \(self.element_inserted_callback\) \|callback\| {
        callback\(element, tag_name\)\;
    }
}
