### Test Server

```zig
// tests/websocket/test_server.zig

const std = @import("std");
const net = std.net;

/// Simple WebSocket echo server for testing
pub const TestServer = struct {
    listener: net.StreamServer,
    port: u16,
    thread: ?std.Thread,
    running: std.atomic.Atomic(bool),

    const Self = @This();

    pub fn start(allocator: std.mem.Allocator) !*Self {
        const self = try allocator.create(Self);

        self.running = std.atomic.Atomic(bool).init(true);

        // Bind to random available port
        const address = net.Address.initIp4(.{ 127, 0, 0, 1 }, 0);
        self.listener = net.StreamServer.init(.{});
        try self.listener.listen(address);

        self.port = self.listener.listen_address.getPort();

        // Start accept thread
        self.thread = try std.Thread.spawn(.{}, acceptLoop, .{self});

        return self;
    }

    pub fn stop(self: *Self) void {
        self.running.store(false, .SeqCst);
        self.listener.close();
        if (self.thread) |t| t.join();
    }

    fn acceptLoop(self: *Self) void {
        while (self.running.load(.SeqCst)) {
            const conn = self.listener.accept() catch continue;
            handleConnection(conn) catch {};
        }
    }

    fn handleConnection(conn: net.StreamServer.Connection) !void {
        // Read HTTP upgrade request
        var buf: [4096]u8 = undefined;
        const n = try conn.stream.read(&buf);

        // Extract Sec-WebSocket-Key
        const key = extractKey(buf[0..n]) orelse return error.NoKey;

        // Send upgrade response
        const accept = calculateAccept(key);
        try conn.stream.writer().print(
            "HTTP/1.1 101 Switching Protocols\r\n" ++
            "Upgrade: websocket\r\n" ++
            "Connection: Upgrade\r\n" ++
            "Sec-WebSocket-Accept: {s}\r\n" ++
            "\r\n",
            .{accept},
        );

        // Echo loop
        while (true) {
            const frame = readFrame(conn.stream) catch break;

            switch (frame.opcode) {
                .text, .binary => {
                    // Echo back
                    try sendFrame(conn.stream, frame.opcode, frame.payload);
                },
                .ping => {
                    // Respond with pong
                    try sendFrame(conn.stream, .pong, frame.payload);
                },
                .close => {
                    // Echo close
                    try sendFrame(conn.stream, .close, frame.payload);
                    break;
                },
                else => {},
            }
        }
    }
};
```

