const std = @import("std");
const testing = std.testing;
const frame = @import("websocket").protocol.frame;
const masking = @import("websocket").protocol.masking;
const handshake = @import("websocket").protocol.handshake;

test "frame parsing: all opcode types" {
    const test_cases = [_]struct {
        bytes: []const u8,
        expected_opcode: Opcode,
    }{
        .{ .bytes = &[_]u8{ 0x81, 0x05 } ++ "hello", .expected_opcode = .text },
        .{ .bytes = &[_]u8{ 0x82, 0x04, 0x01, 0x02, 0x03, 0x04 }, .expected_opcode = .binary },
        .{ .bytes = &[_]u8{ 0x88, 0x02, 0x03, 0xe8 }, .expected_opcode = .close },
        .{ .bytes = &[_]u8{ 0x89, 0x00 }, .expected_opcode = .ping },
        .{ .bytes = &[_]u8{ 0x8A, 0x00 }, .expected_opcode = .pong },
    };

    for (test_cases) |tc| {
        const result = try frame.parseFrameHeader(tc.bytes, true);
        try testing.expectEqual(tc.expected_opcode, result.header.opcode);
    }
}

test "masking: RFC 6455 example" {
    var data = "Hello".*;
    const key = [4]u8{ 0x37, 0xfa, 0x21, 0x3d };
    const expected_masked = [_]u8{ 0x7f, 0x9f, 0x4d, 0x51, 0x58 };

    masking.applyMask(&data, key);
    try testing.expectEqualSlices(u8, &expected_masked, &data);
}

test "handshake: key accept calculation" {
    const key = "dGhlIHNhbXBsZSBub25jZQ==";
    const expected = "s3pPLMBiTxaQ9kYGzzhZRbK+xOo=";

    const accept = handshake.calculateSecWebSocketAccept(key);
    try testing.expectEqualSlices(u8, expected, &accept);
}
