```zig
//! Implementation for WebSocket interface

const std = @import("std");
const runtime = @import("runtime");
const interfaces = @import("interfaces");
const typedefs = @import("typedefs");
const enums = @import("enums");
const webidl = @import("webidl");
const WebSocket = interfaces.WebSocket;
const url_mod = @import("url");
const websocket = @import("websocket");
const encoding = @import("encoding");

pub const State = WebSocket.State;

pub const InternalState = struct {
    /// The underlying WebSocket connection
    connection: *websocket.WebSocketConnection,
    /// Binary type setting
    binary_type: enums.BinaryType,
    /// Event handlers
    onopen: ?typedefs.EventHandler,
    onerror: ?typedefs.EventHandler,
    onclose: ?typedefs.EventHandler,
    onmessage: ?typedefs.EventHandler,
};

pub fn init(
    allocator: std.mem.Allocator,
    comptime StateType: type,
    vtable: *const runtime.VTable,
    ctx: runtime.Context,
) !*runtime.Instance {
    const instance = try runtime.Instance.init(allocator, StateType, vtable, ctx);
    return instance;
}

pub fn deinit(instance: *runtime.Instance) void {
    const state = instance.getState(State);
    if (state._internal) |internal| {
        internal.connection.deinit();
        instance.allocator.destroy(internal);
    }
    runtime.Instance.deinit(instance);
}

/// Constructor: new WebSocket(url, protocols)
pub fn call_constructor(
    allocator: std.mem.Allocator,
    ctx: runtime.Context,
    url_string: runtime.USVString,
    protocols_arg: webidl.Opt(*const anyopaque),
) !*runtime.Instance {
    // Step 1-2: Parse URL
    const base_url = ctx.getBaseUrl() orelse null;
    const url_record = url_mod.parse(allocator, url_string, base_url) catch {
        return error.SyntaxError; // DOMException
    };

    // Step 4-5: Normalize scheme (http→ws, https→wss)
    var scheme = url_record.scheme;
    if (std.mem.eql(u8, scheme, "http")) {
        scheme = "ws";
    } else if (std.mem.eql(u8, scheme, "https")) {
        scheme = "wss";
    }

    // Step 6: Validate scheme
    if (!std.mem.eql(u8, scheme, "ws") and !std.mem.eql(u8, scheme, "wss")) {
        return error.SyntaxError;
    }

    // Step 7: Reject fragments
    if (url_record.fragment != null) {
        return error.SyntaxError;
    }

    // Step 8: Normalize protocols to array
    var protocols: []const []const u8 = &.{};
    if (protocols_arg.wasPassed()) {
        // Handle (DOMString or sequence<DOMString>)
        // This requires type discrimination from the JS binding layer
        protocols = parseProtocolsArg(protocols_arg.value);
    }

    // Step 9: Validate protocols
    for (protocols) |proto| {
        if (!isValidSubprotocol(proto)) {
            return error.SyntaxError;
        }
    }

    // Check for duplicates
    for (protocols, 0..) |proto, i| {
        for (protocols[i + 1..]) |other| {
            if (std.mem.eql(u8, proto, other)) {
                return error.SyntaxError;
            }
        }
    }

    // Create instance
    const instance = try init(allocator, State, &WebSocket.vtable, ctx);
    errdefer deinit(instance);

    // Initialize state
    const state = instance.getState(State);
    state.url = try url_mod.serialize(allocator, url_record);
    state.readyState = 0; // CONNECTING
    state.bufferedAmount = 0;
    state.extensions = "";
    state.protocol = "";
    state.binaryType = .blob; // Default per spec

    // Create internal state
    const internal = try allocator.create(InternalState);
    internal.* = .{
        .connection = try websocket.WebSocketConnection.init(allocator, state.url, .{}),
        .binary_type = .blob,
        .onopen = null,
        .onerror = null,
        .onclose = null,
        .onmessage = null,
    };
    state._internal = internal;

    // Set up event callback
    internal.connection.setEventCallback(handleConnectionEvent, instance);

    // Step 12: Start connection in parallel
    // In a real implementation, this would be queued to the event loop
    spawnConnectionTask(internal.connection, .{
        .protocols = protocols,
    });

    return instance;
}

fn handleConnectionEvent(event: websocket.Event, user_data: ?*anyopaque) void {
    const instance: *runtime.Instance = @ptrCast(@alignCast(user_data));
    const state = instance.getState(State);
    const internal = state._internal orelse return;

    switch (event) {
        .open => |e| {
            state.readyState = 1; // OPEN
            state.extensions = e.extensions orelse "";
            state.protocol = e.protocol orelse "";

            // Fire 'open' event
            if (internal.onopen) |handler| {
                fireEvent(instance, "open", handler);
            }
        },
        .message => |e| {
            if (internal.onmessage) |handler| {
                // Create MessageEvent based on binary type
                const msg_event = if (e.is_text)
                    createTextMessageEvent(instance.allocator, e.data, state.url)
                else
                    createBinaryMessageEvent(instance.allocator, e.data, state.url, internal.binary_type);

                fireMessageEvent(instance, handler, msg_event);
            }
        },
        .@"error" => {
            if (internal.onerror) |handler| {
                fireEvent(instance, "error", handler);
            }
        },
        .close => |e| {
            state.readyState = 3; // CLOSED

            if (internal.onclose) |handler| {
                const close_event = createCloseEvent(
                    instance.allocator,
                    e.was_clean,
                    e.code,
                    e.reason,
                );
                fireCloseEvent(instance, handler, close_event);
            }
        },
    }
}

/// Getter for url
pub fn get_url(instance: *runtime.Instance) anyerror!runtime.USVString {
    const state = instance.getState(State);
    return state.url;
}

/// Getter for readyState
pub fn get_readyState(instance: *runtime.Instance) anyerror!u16 {
    const state = instance.getState(State);
    return state.readyState;
}

/// Getter for bufferedAmount
pub fn get_bufferedAmount(instance: *runtime.Instance) anyerror!u64 {
    const state = instance.getState(State);
    const internal = state._internal orelse return 0;
    return internal.connection.getBufferedAmount();
}

/// Getter for extensions
pub fn get_extensions(instance: *runtime.Instance) anyerror!runtime.DOMString {
    const state = instance.getState(State);
    return state.extensions;
}

/// Getter for protocol
pub fn get_protocol(instance: *runtime.Instance) anyerror!runtime.DOMString {
    const state = instance.getState(State);
    return state.protocol;
}

/// Getter for binaryType
pub fn get_binaryType(instance: *runtime.Instance) anyerror!enums.BinaryType {
    const state = instance.getState(State);
    const internal = state._internal orelse return .blob;
    return internal.binary_type;
}

/// Setter for binaryType
pub fn set_binaryType(instance: *runtime.Instance, value: enums.BinaryType) anyerror!void {
    const state = instance.getState(State);
    const internal = state._internal orelse return;
    internal.binary_type = value;
}

/// Event handler getters and setters
pub fn get_onopen(instance: *runtime.Instance) anyerror!typedefs.EventHandler {
    const state = instance.getState(State);
    const internal = state._internal orelse return null;
    return internal.onopen;
}

pub fn set_onopen(instance: *runtime.Instance, value: typedefs.EventHandler) anyerror!void {
    const state = instance.getState(State);
    const internal = state._internal orelse return;
    internal.onopen = value;
}

// ... similar for onerror, onclose, onmessage ...

/// Operation: close(code, reason)
pub fn call_close(
    instance: *runtime.Instance,
    code: webidl.Opt(u16),
    reason: webidl.Opt(runtime.USVString),
) anyerror!void {
    const state = instance.getState(State);
    const internal = state._internal orelse return;

    // Step 1: Validate code
    if (code.wasPassed()) {
        const c = code.value;
        if (c != 1000 and (c < 3000 or c > 4999)) {
            return error.InvalidAccessError;
        }
    }

    // Step 2: Validate reason length
    if (reason.wasPassed()) {
        const r = reason.value;
        const byte_len = encoding.utf8ByteLength(r);
        if (byte_len > 123) {
            return error.SyntaxError;
        }
    }

    // Step 3: Perform close
    switch (state.readyState) {
        2, 3 => {}, // CLOSING or CLOSED - do nothing
        else => {
            try internal.connection.close(
                if (code.wasPassed()) code.value else null,
                if (reason.wasPassed()) reason.value else null,
            );
            state.readyState = 2; // CLOSING
        },
    }
}

/// Operation: send(data)
pub fn call_send(instance: *runtime.Instance, data: *const anyopaque) anyerror!void {
    const state = instance.getState(State);
    const internal = state._internal orelse return;

    // Step 1: Check ready state
    if (state.readyState == 0) { // CONNECTING
        return error.InvalidStateError;
    }

    // Step 2: Send based on data type
    // The data type is determined by the JS binding layer
    // For now, assume we receive type information somehow
    const data_info = getDataTypeInfo(data);

    switch (data_info.type) {
        .string => {
            const text = data_info.asString();
            try internal.connection.sendText(text);
            state.bufferedAmount += encoding.utf8ByteLength(text);
        },
        .blob => {
            const blob_data = try data_info.asBlobData();
            try internal.connection.sendBinary(blob_data);
            state.bufferedAmount += blob_data.len;
        },
        .array_buffer => {
            const buffer = data_info.asArrayBuffer();
            try internal.connection.sendBinary(buffer);
            state.bufferedAmount += buffer.len;
        },
        .array_buffer_view => {
            const view = data_info.asArrayBufferView();
            try internal.connection.sendBinary(view);
            state.bufferedAmount += view.len;
        },
    }
}

/// Validate subprotocol per RFC 6455
fn isValidSubprotocol(proto: []const u8) bool {
    if (proto.len == 0) return false;
    for (proto) |c| {
        // Must be visible ASCII (0x21-0x7E) excluding separators
        if (c < 0x21 or c > 0x7E) return false;
        if (isSeparator(c)) return false;
    }
    return true;
}

fn isSeparator(c: u8) bool {
    return switch (c) {
        '(', ')', '<', '>', '@', ',', ';', ':', '\\', '"',
        '/', '[', ']', '?', '=', '{', '}', ' ', '\t' => true,
        else => false,
    };
}
