const std = @import("std");
const types = @import("types.zig");

/// Get the fallback list for a directive name.
/// Returns list of directive names to check in order.
/// Spec: CSP Level 3 § 6.8.3
pub fn getFetchDirectiveFallbackList(directive_name: []const u8) []const []const u8 {
    // Using comptime string map for O(1) lookup
    const fallback_map = std.ComptimeStringMap([]const []const u8, .{
        .{ "script-src-elem", &[_][]const u8{ "script-src-elem", "script-src", "default-src" } },
        .{ "script-src-attr", &[_][]const u8{ "script-src-attr", "script-src", "default-src" } },
        .{ "style-src-elem", &[_][]const u8{ "style-src-elem", "style-src", "default-src" } },
        .{ "style-src-attr", &[_][]const u8{ "style-src-attr", "style-src", "default-src" } },
        .{ "worker-src", &[_][]const u8{ "worker-src", "child-src", "script-src", "default-src" } },
        .{ "connect-src", &[_][]const u8{ "connect-src", "default-src" } },
        .{ "frame-src", &[_][]const u8{ "frame-src", "child-src", "default-src" } },
        .{ "img-src", &[_][]const u8{ "img-src", "default-src" } },
        .{ "font-src", &[_][]const u8{ "font-src", "default-src" } },
        .{ "media-src", &[_][]const u8{ "media-src", "default-src" } },
        .{ "object-src", &[_][]const u8{ "object-src", "default-src" } },
        .{ "manifest-src", &[_][]const u8{ "manifest-src", "default-src" } },
        .{ "prefetch-src", &[_][]const u8{ "prefetch-src", "default-src" } },
        .{ "script-src", &[_][]const u8{ "script-src", "default-src" } },
        .{ "style-src", &[_][]const u8{ "style-src", "default-src" } },
        .{ "child-src", &[_][]const u8{ "child-src", "default-src" } },
        .{ "default-src", &[_][]const u8{"default-src"} },
    });

    return fallback_map.get(directive_name) orelse &[_][]const u8{};
}

/// Get the effective directive for a policy.
/// Returns the first directive in the fallback chain that exists in the policy.
/// Spec: CSP Level 3 § 6.8.4
pub fn getEffectiveDirective(
    policy: *const types.Policy,
    directive_name: []const u8,
) ?*const types.Directive {
    const fallback_list = getFetchDirectiveFallbackList(directive_name);

    for (fallback_list) |fallback_name| {
        if (policy.getDirective(fallback_name)) |directive| {
            return directive;
        }
    }

    return null;
}

/// Get the effective source list for a directive.
/// Returns the source list from the effective directive, or null if none.
pub fn getEffectiveSourceList(
    policy: *const types.Policy,
    directive_name: []const u8,
) ?*const types.SourceList {
    if (getEffectiveDirective(policy, directive_name)) |directive| {
        return &directive.value;
    }
    return null;
}

/// Check if a policy allows a request for a given directive.
/// Uses fallback chain to find the effective directive.
pub fn doesPolicyAllowRequest(
    policy: *const types.Policy,
    directive_name: []const u8,
    url: anytype,
    redirect_count: u32,
) bool {
    const source_list = getEffectiveSourceList(policy, directive_name) orelse {
        // No effective directive means request is allowed
        return true;
    };

    const matching = @import("matching.zig");
    return matching.doesUrlMatchSourceList(
        url,
        source_list,
        policy.self_origin,
        redirect_count,
    );
}
```

