## Overview

Add defensive validation helpers to catch V8 pointer type confusion early, providing better error messages and preventing silent corruption.

## Problem

When V8 pointers are misused \(Local passed where Global expected, or vice versa\), the result is often:
- Segfault with cryptic "misaligned address" error
- Silent memory corruption
- Crashes in unrelated code later

## Solution: Validation Helpers

### 1. Pointer Validation in C++ \(v8_wrapper.cpp\)

```cpp
// Validate that a pointer looks like a valid Global\<Value\>*
extern "C" bool v8_ValidateGlobalPointer\(void* ptr\) {
    if \(ptr == nullptr\) return false\;

    uintptr_t addr = reinterpret_cast\<uintptr_t\>\(ptr\)\;

    // Global handles are heap-allocated, should be:
    // 1. Properly aligned \(8-byte on 64-bit\)
    // 2. Not in typical stack address range
    // 3. Not a V8 tagged pointer \(no tag bits\)

    if \(addr \< 0x1000\) return false\;  // Null page
    if \(addr \& 0x7\) return false\;      // Misaligned
    if \(\(addr \& 0x1\) == 1\) return false\;  // V8 tagged pointer

    // Additional heuristic: check if it looks like valid memory
    // This is platform-specific and can't catch all cases

    return true\;
}

// Debug helper: describe what type of pointer this likely is
extern "C" const char* v8_DescribePointer\(void* ptr\) {
    if \(ptr == nullptr\) return "null"\;

    uintptr_t addr = reinterpret_cast\<uintptr_t\>\(ptr\)\;

    if \(addr \< 0x1000\) return "null_page"\;
    if \(\(addr \& 0x1\) == 1\) return "v8_tagged_heapobject"\;
    if \(\(addr \& 0x3\) == 0 \&\& addr \< 0x7FFFFFFF\) return "possible_smi"\;
    if \(addr \& 0x7\) return "misaligned"\;

    // Check if it's in V8's heap
    // This would require isolate access...

    return "possibly_valid_heap"\;
}
```

### 2. Zig Validation Wrapper \(validation.zig\)

```zig
const std = @import\("std"\)\;
const v8 = @import\("ffi.zig"\)\;

pub const PointerType = enum {
    null_ptr,
    null_page,
    v8_tagged_heapobject,
    possible_smi,
    misaligned,
    possibly_valid_heap,
}\;

pub fn describePointer\(ptr: *const anyopaque\) PointerType {
    const addr = @intFromPtr\(ptr\)\;

    if \(addr == 0\) return .null_ptr\;
    if \(addr \< 0x1000\) return .null_page\;
    if \(\(addr \& 0x1\) == 1\) return .v8_tagged_heapobject\;
    if \(\(addr \& 0x7\) \!= 0\) return .misaligned\;

    return .possibly_valid_heap\;
}

pub fn validateV8Pointer\(ptr: *const anyopaque, comptime context: []const u8\) \!void {
    const ptr_type = describePointer\(ptr\)\;

    switch \(ptr_type\) {
        .null_ptr, .null_page =\> {
            std.debug.print\("[V8 ERROR] {s}: null or near-null pointer\n", .{context}\)\;
            return error.InvalidV8Pointer\;
        },
        .v8_tagged_heapobject =\> {
            std.debug.print\("[V8 ERROR] {s}: tagged V8 pointer \(Local handle?\) passed where Global expected\n", .{context}\)\;
            std.debug.print\("  Address: 0x{x}\n", .{@intFromPtr\(ptr\)}\)\;
            return error.V8TaggedPointer\;
        },
        .misaligned =\> {
            std.debug.print\("[V8 ERROR] {s}: misaligned pointer\n", .{context}\)\;
            return error.MisalignedPointer\;
        },
        .possibly_valid_heap =\> {
            // OK
        },
        else =\> {},
    }
}

/// Debug: Assert this is a valid V8 pointer \(compile-time removable in release\)
pub fn assertValidV8Ptr\(ptr: *const anyopaque, comptime context: []const u8\) void {
    if \(std.debug.runtime_safety\) {
        validateV8Pointer\(ptr, context\) catch \|err\| {
            std.debug.panic\("Invalid V8 pointer in {s}: {}", .{ context, err }\)\;
        }\;
    }
}
```

