### 4. Debug Logging for Handle Lifecycle

```zig
const HandleTracker = struct {
    const Entry = struct {
        ptr: usize,
        source: []const u8,
        created_at: std.time.Timer.Instant,
        disposed: bool,
    }\;

    entries: std.ArrayList\(Entry\),

    pub fn trackGlobalCreation\(self: *HandleTracker, ptr: *anyopaque, source: []const u8\) void {
        if \(\!std.debug.runtime_safety\) return\;

        self.entries.append\(.{
            .ptr = @intFromPtr\(ptr\),
            .source = source,
            .created_at = std.time.Timer.now\(\),
            .disposed = false,
        }\) catch {}\;
    }

    pub fn trackGlobalDisposal\(self: *HandleTracker, ptr: *anyopaque\) void {
        if \(\!std.debug.runtime_safety\) return\;

        for \(self.entries.items\) \|*entry\| {
            if \(entry.ptr == @intFromPtr\(ptr\)\) {
                if \(entry.disposed\) {
                    std.debug.print\("WARNING: Double-dispose of Global handle from {s}\n", .{entry.source}\)\;
                }
                entry.disposed = true\;
                return\;
            }
        }
        std.debug.print\("WARNING: Disposing unknown Global handle\n", .{}\)\;
    }

    pub fn reportLeaks\(self: *HandleTracker\) void {
        var leak_count: usize = 0\;
        for \(self.entries.items\) \|entry\| {
            if \(\!entry.disposed\) {
                std.debug.print\("LEAK: Global handle from {s} never disposed\n", .{entry.source}\)\;
                leak_count += 1\;
            }
        }
        if \(leak_count \> 0\) {
            std.debug.print\("Total Global handle leaks: {}\n", .{leak_count}\)\;
        }
    }
}\;
```

