### Policy Enum
```zig
//! W3C Referrer Policy implementation.
//! Spec: https://w3c.github.io/webappsec-referrer-policy/

/// Referrer policy values per spec.
pub const ReferrerPolicy = enum {
    /// Empty string policy (use default)
    empty,

    /// Never send Referer header
    no_referrer,

    /// Send full URL to same-origin, nothing to cross-origin HTTPS->HTTP
    no_referrer_when_downgrade,

    /// Only send Referer for same-origin requests
    same_origin,

    /// Send only origin (not path) for all requests
    origin,

    /// Send only origin for cross-origin, nothing for HTTPS->HTTP
    strict_origin,

    /// Send full URL to same-origin, origin to cross-origin
    origin_when_cross_origin,

    /// Send only origin to same-origin, nothing for HTTPS->HTTP cross-origin
    strict_origin_when_cross_origin,

    /// Always send full URL (unsafe)
    unsafe_url,

    /// Parse a referrer policy string.
    pub fn parse(value: []const u8) ?ReferrerPolicy {
        const trimmed = std.mem.trim(u8, value, " \t");
        const lower = std.ascii.lowerString(trimmed);

        if (std.mem.eql(u8, lower, "")) return .empty;
        if (std.mem.eql(u8, lower, "no-referrer")) return .no_referrer;
        if (std.mem.eql(u8, lower, "no-referrer-when-downgrade")) return .no_referrer_when_downgrade;
        if (std.mem.eql(u8, lower, "same-origin")) return .same_origin;
        if (std.mem.eql(u8, lower, "origin")) return .origin;
        if (std.mem.eql(u8, lower, "strict-origin")) return .strict_origin;
        if (std.mem.eql(u8, lower, "origin-when-cross-origin")) return .origin_when_cross_origin;
        if (std.mem.eql(u8, lower, "strict-origin-when-cross-origin")) return .strict_origin_when_cross_origin;
        if (std.mem.eql(u8, lower, "unsafe-url")) return .unsafe_url;

        return null; // Invalid policy
    }

    /// Get the default policy.
    pub fn default() ReferrerPolicy {
        return .strict_origin_when_cross_origin;
    }
};
```

### Determine Request's Referrer Algorithm
```zig
/// Determine the referrer URL for a request.
///
/// Spec: § 8.3 "Determine request's Referrer"
///
/// Inputs:
/// - request: The request being made
/// 
/// Outputs:
/// - "no-referrer" (don't send Referer)
/// - A URL (the referrer to send)
pub fn determineRequestsReferrer(
    allocator: std.mem.Allocator,
    request: *InternalRequest,
) !Referrer {
    // Step 1: Let policy be request's referrer policy
    const policy = request.referrer_policy;

    // Step 2: If request's referrer is "no-referrer", return no referrer
    if (request.referrer == .no_referrer) {
        return .no_referrer;
    }

    // Step 3: Let environment be request's client
    // Step 4: Let referrerSource be...
    const referrer_source = switch (request.referrer) {
        .client => blk: {
            // Use environment's document URL or global's URL
            if (request.client) |client| {
                break :blk client.getApiBaseUrl();
            }
            return .no_referrer;
        },
        .url => |url| url,
        .no_referrer => return .no_referrer,
    };

    // Step 5: Let referrerURL be result of stripping referrerSource for use as referrer
    var referrer_url = stripUrlForReferrer(referrer_source);

    // Step 6: Let referrerOrigin be ASCII serialization of referrerURL's origin
    const referrer_origin = referrer_url.getOrigin();

    // Step 7: If policy is empty, set to default
    const effective_policy = if (policy == .empty) 
        ReferrerPolicy.default() 
    else 
        policy;

    // Step 8: Execute policy-specific algorithm
    return applyReferrerPolicy(
        allocator,
        effective_policy,
        referrer_url,
        referrer_origin,
        request.currentUrl().*,
    );
}

pub const Referrer = union(enum) {
    no_referrer,
    url: URL,
};
```

### Strip URL for Referrer
```zig
/// Strip a URL for use as a referrer.
///
/// Algorithm:
/// 1. If URL is local or has opaque origin, return no referrer
/// 2. Set URL's username and password to empty
/// 3. Set URL's fragment to null
/// 4. Return URL
pub fn stripUrlForReferrer(url: URL) ?URL
```

### Apply Referrer Policy
```zig
/// Apply a referrer policy to determine referrer.
///
/// This implements the policy-specific logic from § 8.3.
fn applyReferrerPolicy(
    allocator: std.mem.Allocator,
    policy: ReferrerPolicy,
    referrer_url: URL,
    referrer_origin: Origin,
    current_url: URL,
) !Referrer {
    const is_same_origin = referrer_origin.isSameOrigin(current_url.getOrigin());
    const is_downgrade = isDowngrade(referrer_url, current_url);

    return switch (policy) {
        .no_referrer => .no_referrer,

        .no_referrer_when_downgrade => {
            if (is_downgrade) return .no_referrer;
            return .{ .url = referrer_url };
        },

        .same_origin => {
            if (is_same_origin) return .{ .url = referrer_url };
            return .no_referrer;
        },

        .origin => .{ .url = try originOnly(allocator, referrer_url) },

        .strict_origin => {
            if (is_downgrade) return .no_referrer;
            return .{ .url = try originOnly(allocator, referrer_url) };
        },

        .origin_when_cross_origin => {
            if (is_same_origin) return .{ .url = referrer_url };
            return .{ .url = try originOnly(allocator, referrer_url) };
        },

        .strict_origin_when_cross_origin => {
            if (is_same_origin) return .{ .url = referrer_url };
            if (is_downgrade) return .no_referrer;
            return .{ .url = try originOnly(allocator, referrer_url) };
        },

        .unsafe_url => .{ .url = referrer_url },

        .empty => unreachable, // Handled before calling this
    };
}
```

### Helper Functions
```zig
/// Check if this is a downgrade (HTTPS -> HTTP).
fn isDowngrade(referrer: URL, target: URL) bool {
    return std.mem.eql(u8, referrer.scheme, "https") and
           std.mem.eql(u8, target.scheme, "http");
}

/// Get origin-only URL (strip path, query, fragment).
fn originOnly(allocator: std.mem.Allocator, url: URL) !URL {
    // Return scheme://host:port/
    var result = url.clone(allocator);
    result.path = "/";
    result.query = null;
    result.fragment = null;
    return result;
}
```

### Parse Referrer-Policy Header
```zig
/// Parse Referrer-Policy header (may contain multiple values).
/// Returns the last valid policy, or null if none valid.
///
/// The header can contain comma-separated values for fallback.
pub fn parseReferrerPolicyHeader(header_value: []const u8) ?ReferrerPolicy {
    var result: ?ReferrerPolicy = null;

    var iter = std.mem.split(u8, header_value, ",");
    while (iter.next()) |token| {
        if (ReferrerPolicy.parse(token)) |policy| {
            result = policy;
        }
    }

    return result;
}
```

