### 3. v8::Locker Support for Multi-Threaded Access
```cpp
extern "C" {
    /// Acquire exclusive lock on isolate
    /// Must be called before accessing isolate from any thread
    void* v8_Locker_New(Isolate* isolate) {
        return new Locker(isolate);
    }

    /// Release lock on isolate
    void v8_Locker_Dispose(void* locker) {
        delete static_cast<Locker*>(locker);
    }

    /// Check if current thread holds lock
    bool v8_Locker_IsLocked(Isolate* isolate) {
        return Locker::IsLocked(isolate);
    }

    /// Check if isolate is currently in use by any thread
    bool v8_Locker_IsActive(Isolate* isolate) {
        return Locker::IsActive(isolate);
