### 4. Zig-Side Locker Wrapper (locker.zig)
Create `src/runtime/engines/v8/locker.zig`:
```zig
const ffi = @import("ffi.zig");

/// RAII wrapper for v8::Locker
/// Ensures exclusive access to an isolate
pub const IsolateLock = struct {
    locker: *anyopaque,
    isolate: *ffi.Isolate,

    /// Acquire exclusive lock on isolate
    /// Blocks until lock is available
    pub fn acquire(isolate: *ffi.Isolate) IsolateLock {
        return .{
            .locker = ffi.v8_Locker_New(isolate),
            .isolate = isolate,
        };
    }

    /// Release the lock
    pub fn release(self: *IsolateLock) void {
        ffi.v8_Locker_Dispose(self.locker);
        self.* = undefined;
    }

    /// Check if current thread holds lock
    pub fn isLocked(isolate: *ffi.Isolate) bool {
        return ffi.v8_Locker_IsLocked(isolate);
    }
};

/// Scoped lock helper - use with defer
pub fn withLock(isolate: *ffi.Isolate, comptime func: fn (*ffi.Isolate) anyerror!void) !void {
    var lock = IsolateLock.acquire(isolate);
    defer lock.release();

    try func(isolate);
}

/// Assert that we hold the lock (debug only)
pub fn assertLocked(isolate: *ffi.Isolate) void {
    if (std.debug.runtime_safety) {
        if (!IsolateLock.isLocked(isolate)) {
            @panic("Isolate accessed without holding lock");
        }
    }
}
```

