pub fn runInIsolate(
    isolate: *ffi.Isolate, 
    context: *ffi.Context,
    script: []const u8,
) !*ffi.Value {
    // Acquire lock before any V8 operations
    var lock = locker.IsolateLock.acquire(isolate);
    defer lock.release();

    // Enter isolate
    ffi.v8_Isolate_Enter(isolate);
    defer ffi.v8_Isolate_Exit(isolate);

    // Enter context
    ffi.v8_Context_Enter(context);
    defer ffi.v8_Context_Exit(context);

    // Now safe to execute script
    const compiled = try compileScript(script);
    return try runScript(compiled);
}
