```zig
/// Temporarily release lock for blocking operations
pub const IsolateUnlock = struct {
    unlocker: *anyopaque,

    pub fn release(isolate: *ffi.Isolate) IsolateUnlock {
        return .{ .unlocker = ffi.v8_Unlocker_New(isolate) };
    }

    pub fn reacquire(self: *IsolateUnlock) void {
        ffi.v8_Unlocker_Dispose(self.unlocker);
        self.* = undefined;
    }
};

/// Use for blocking operations within locked section
pub fn withUnlock(isolate: *ffi.Isolate, comptime func: fn () anyerror!void) !void {
    var unlock = IsolateUnlock.release(isolate);
    defer unlock.reacquire();

    try func();
}
