## Summary

Implement the WebSocket handshake key generation and validation per RFC 6455 Section 4.2.2 and WHATWG WebSockets spec.

## Specification Reference

### RFC 6455 Section 4.2.2 - Sending the Server's Opening Handshake

The server generates Sec-WebSocket-Accept by:
1. Take the Sec-WebSocket-Key value
2. Concatenate with the GUID: "258EAFA5-E914-47DA-95CA-C5AB0DC85B11"
3. Take the SHA-1 hash
4. Base64 encode the result

### WHATWG WebSockets Spec - Opening Handshake (Step 5)

> Let keyValue be a nonce consisting of a randomly selected 16-byte value 
> that has been forgiving-base64-encoded and isomorphic encoded.

## Implementation Details

### File: src/websocket/protocol/handshake.zig

```zig
const std = @import("std");
const base64 = std.base64.standard;
const Sha1 = std.crypto.hash.Sha1;

/// The magic GUID from RFC 6455 Section 4.2.2
pub const WEBSOCKET_GUID = "258EAFA5-E914-47DA-95CA-C5AB0DC85B11";

/// Generate a Sec-WebSocket-Key for client handshake
/// Returns a 24-character base64-encoded string (16 random bytes encoded)
pub fn generateSecWebSocketKey() [24]u8 {
    var random_bytes: [16]u8 = undefined;
    std.crypto.random.bytes(&random_bytes);

    var key: [24]u8 = undefined;
    _ = base64.Encoder.encode(&key, &random_bytes);
    return key;
}

/// Calculate expected Sec-WebSocket-Accept value from client's key
/// Used by client to validate server's response
pub fn calculateSecWebSocketAccept(client_key: []const u8) [28]u8 {
    var hasher = Sha1.init(.{});
    hasher.update(client_key);
    hasher.update(WEBSOCKET_GUID);
    const hash = hasher.finalResult();

    var accept: [28]u8 = undefined;
    _ = base64.Encoder.encode(&accept, &hash);
    return accept;
}

/// Validate server's Sec-WebSocket-Accept header
pub fn validateSecWebSocketAccept(
    client_key: []const u8,
    server_accept: []const u8,
) bool {
    const expected = calculateSecWebSocketAccept(client_key);
    return std.mem.eql(u8, &expected, server_accept);
}

/// Validate that a Sec-WebSocket-Key is well-formed
/// Must be exactly 24 characters of valid base64
pub fn isValidSecWebSocketKey(key: []const u8) bool {
    if (key.len != 24) return false;

    // Try to decode - if it fails, it's not valid base64
    var decoded: [16]u8 = undefined;
    base64.Decoder.decode(&decoded, key) catch return false;

    return true;
}

/// Errors for handshake operations
pub const HandshakeError = error{
    /// Server's Sec-WebSocket-Accept doesn't match expected value
    InvalidAccept,
    /// Sec-WebSocket-Key is malformed
    InvalidKey,
    /// Required handshake header is missing
    MissingHeader,
    /// Protocol version not supported
    UnsupportedVersion,
    /// Subprotocol mismatch
    SubprotocolMismatch,
};

/// Parsed handshake response from server
pub const HandshakeResponse = struct {
    /// Negotiated extensions (from Sec-WebSocket-Extensions)
    extensions: ?[]const u8,
    /// Negotiated subprotocol (from Sec-WebSocket-Protocol)
    protocol: ?[]const u8,
};

/// Validate a complete handshake response
/// Per WHATWG WebSockets spec "establish a WebSocket connection" step 11
pub fn validateHandshakeResponse(
    client_key: []const u8,
    response_headers: anytype, // Generic header accessor
    requested_protocols: []const []const u8,
) HandshakeError!HandshakeResponse {
    // Validate Sec-WebSocket-Accept
    const accept = response_headers.get("Sec-WebSocket-Accept") orelse 
        return error.MissingHeader;
    if (!validateSecWebSocketAccept(client_key, accept)) {
        return error.InvalidAccept;
    }

    // Get extensions (optional)
    const extensions = response_headers.get("Sec-WebSocket-Extensions");

    // Validate subprotocol
    const protocol = response_headers.get("Sec-WebSocket-Protocol");
    if (requested_protocols.len > 0) {
        if (protocol == null) {
            return error.SubprotocolMismatch;
        }
        // Verify server selected one of our requested protocols
        var found = false;
        for (requested_protocols) |req| {
            if (std.mem.eql(u8, req, protocol.?)) {
                found = true;
                break;
            }
        }
        if (!found) {
            return error.SubprotocolMismatch;
        }
    }

    return .{
        .extensions = extensions,
        .protocol = protocol,
    };
}
```

