//! Mock FormData for Fetch body extraction
//!
//! TODO(xhr-spec): Replace this mock with real FormData implementation when
//! XMLHttpRequest specification is implemented.
//! See: https://xhr.spec.whatwg.org/#interface-formdata
//!
//! This mock provides minimal functionality for Fetch:
//! - Store name/value pairs (strings only)
//! - Serialize to multipart/form-data format
//! - NO File support (requires File API integration)
//! - NO HTMLFormElement support

const std = @import("std");

/// Mock FormData.
///
/// Real FormData should:
/// - Support File values (Blob with filename)
/// - Support creating from HTMLFormElement
/// - Support iteration (entries, keys, values)
/// - Integrate with File API
pub const FormData = struct {
    allocator: std.mem.Allocator,

    /// Stored entries (name, value pairs)
    entries: std.ArrayList(Entry),

    pub const Entry = struct {
        name: []const u8,
        value: EntryValue,
    };

    pub const EntryValue = union(enum) {
        string: []const u8,
        // TODO(xhr-spec): Add File support
        // file: *File,
    };

    pub fn init(allocator: std.mem.Allocator) FormData {
        return .{
            .allocator = allocator,
            .entries = std.ArrayList(Entry).init(allocator),
        };
    }

    pub fn deinit(self: *FormData) void {
        for (self.entries.items) |entry| {
            self.allocator.free(entry.name);
            switch (entry.value) {
                .string => |s| self.allocator.free(s),
            }
        }
        self.entries.deinit();
    }

    /// Append a name/value pair.
    pub fn append(self: *FormData, name: []const u8, value: []const u8) !void {
        try self.entries.append(.{
            .name = try self.allocator.dupe(u8, name),
            .value = .{ .string = try self.allocator.dupe(u8, value) },
        });
    }

    /// Set a name/value pair (removes existing entries with same name).
    pub fn set(self: *FormData, name: []const u8, value: []const u8) !void {
        self.delete(name);
        try self.append(name, value);
    }

    /// Get the first value for a name.
    pub fn get(self: *FormData, name: []const u8) ?[]const u8 {
        for (self.entries.items) |entry| {
            if (std.mem.eql(u8, entry.name, name)) {
                return switch (entry.value) {
                    .string => |s| s,
                };
            }
        }
        return null;
    }

    /// Get all values for a name.
    pub fn getAll(self: *FormData, allocator: std.mem.Allocator, name: []const u8) ![][]const u8 {
        var result = std.ArrayList([]const u8).init(allocator);
        for (self.entries.items) |entry| {
            if (std.mem.eql(u8, entry.name, name)) {
                try result.append(switch (entry.value) {
                    .string => |s| s,
                });
            }
        }
        return result.toOwnedSlice();
    }

    /// Check if name exists.
    pub fn has(self: *FormData, name: []const u8) bool {
        for (self.entries.items) |entry| {
            if (std.mem.eql(u8, entry.name, name)) {
                return true;
            }
        }
        return false;
    }

    /// Delete all entries with name.
    pub fn delete(self: *FormData, name: []const u8) void {
        var i: usize = 0;
        while (i < self.entries.items.len) {
            if (std.mem.eql(u8, self.entries.items[i].name, name)) {
                const entry = self.entries.orderedRemove(i);
                self.allocator.free(entry.name);
                switch (entry.value) {
                    .string => |s| self.allocator.free(s),
                }
            } else {
                i += 1;
            }
        }
    }
};
