) !struct { body: []const u8, boundary: []const u8 } {
    // Generate boundary
    const boundary = try generateBoundary(allocator);

    var body = std.ArrayList(u8).init(allocator);
    const writer = body.writer();

    for (form_data.entries.items) |entry| {
        try writer.print("--{s}\r\n", .{boundary});
        try writer.print("Content-Disposition: form-data; name=\"{s}\"\r\n", .{entry.name});
        try writer.writeAll("\r\n");

        switch (entry.value) {
            .string => |s| try writer.writeAll(s),
        }
        try writer.writeAll("\r\n");
    }

    try writer.print("--{s}--\r\n", .{boundary});

    return .{
        .body = try body.toOwnedSlice(),
        .boundary = boundary,
    };
}

fn generateBoundary(allocator: std.mem.Allocator) ![]const u8 {
    var buf: [16]u8 = undefined;
    std.crypto.random.bytes(&buf);
    return try std.fmt.allocPrint(allocator, "----FormBoundary{s}", 
        .{std.fmt.fmtSliceHexLower(&buf)});
}
```

