# Implement Structured Clone Algorithm

## Spec Reference
HTML Standard Section 2.7 "Safe passing of structured data"

## Location
`src/html/structured_clone/` (new directory)

## Requirements

### Core Structured Clone
```zig
// src/html/structured_clone/clone.zig
pub const StructuredClone = struct {
    allocator: Allocator,
    memory: HashMap(*anyopaque, *anyopaque), // For circular references
    transfer_list: ?[]Transferable,

    pub fn clone(self: *StructuredClone, value: JSValue) !JSValue {
        return self.internalClone(value);
    }

    fn internalClone(self: *StructuredClone, value: JSValue) !JSValue {
        // Check for circular reference
        if (self.memory.get(@ptrToInt(value.ptr))) |existing| {
            return JSValue.fromPtr(existing);
        }

        return switch (value.getType()) {
            // Primitives (no clone needed, immutable)
            .undefined, .null, .boolean, .number, .bigint => value,
            .string => self.cloneString(value),

            // Objects
            .object => self.cloneObject(value),
            .array => self.cloneArray(value),

            // Special types
            .date => self.cloneDate(value),
            .regexp => self.cloneRegExp(value),
            .map => self.cloneMap(value),
            .set => self.cloneSet(value),
            .array_buffer => self.cloneArrayBuffer(value),
            .typed_array => self.cloneTypedArray(value),
            .data_view => self.cloneDataView(value),
            .blob => self.cloneBlob(value),
            .file => self.cloneFile(value),
            .file_list => self.cloneFileList(value),
            .image_bitmap => self.cloneImageBitmap(value),
            .image_data => self.cloneImageData(value),
            .error => self.cloneError(value),

            // Non-cloneable (throw)
            .function, .symbol => return error.DataCloneError,
        };
    }

    fn cloneObject(self: *StructuredClone, value: JSValue) !JSValue {
        const clone = try JSValue.createObject(self.allocator);

        // Store in memory for circular reference
        self.memory.put(@ptrToInt(value.ptr), @ptrToInt(clone.ptr));

        // Clone each property
        var iter = value.propertyIterator();
        while (iter.next()) |entry| {
            const cloned_value = try self.internalClone(entry.value);
            try clone.setProperty(entry.key, cloned_value);
        }

        return clone;
    }

    fn cloneArray(self: *StructuredClone, value: JSValue) !JSValue {
        const length = value.getArrayLength();
        const clone = try JSValue.createArray(self.allocator, length);

        self.memory.put(@ptrToInt(value.ptr), @ptrToInt(clone.ptr));

        for (0..length) |i| {
            if (value.hasArrayIndex(i)) {
                const elem = value.getArrayIndex(i);
                const cloned_elem = try self.internalClone(elem);
                try clone.setArrayIndex(i, cloned_elem);
            }
        }

        return clone;
    }

    fn cloneArrayBuffer(self: *StructuredClone, value: JSValue) !JSValue {
        // Check if being transferred
        if (self.isBeingTransferred(value)) {
            return self.transferArrayBuffer(value);
        }

        const data = value.getArrayBufferData();
        const clone = try JSValue.createArrayBuffer(self.allocator, data.len);
        @memcpy(clone.getArrayBufferData(), data);
        return clone;
    }

    // ... more clone methods
};
```

