## Requirements

### Timer Manager Structure
```zig
pub const TimerManager = struct {
    allocator: Allocator,
    pending_timers: PriorityQueue(Timer, compareFireTime),
    timer_ids: AutoHashMap(u32, *Timer),
    next_timer_id: u32,
    platform: *PlatformTimerBackend,

    // Throttling state
    visibility_state: VisibilityState,

    pub fn init(allocator: Allocator, platform: *PlatformTimerBackend) TimerManager;
    pub fn deinit(self: *TimerManager) void;
};

pub const Timer = struct {
    id: u32,
    callback: TimerCallback,
    fire_time: i64,  // Absolute time in milliseconds
    interval: ?i64,  // null for setTimeout, value for setInterval
    nesting_level: u32,
    is_cancelled: bool,
};
```

### Core Methods
```zig
pub fn setTimeout(
    self: *TimerManager,
    callback: TimerCallback,
    delay: i64,
    nesting_level: u32,
) u32 {
    // 1. Apply 4ms clamping if nesting > 5 and delay < 4
    var actual_delay = delay;
    if (nesting_level > 5 and delay < 4) {
        actual_delay = 4;
    }

    // 2. Apply visibility throttling
    actual_delay = self.applyThrottling(actual_delay);

    // 3. Create timer and add to heap
    const timer = self.allocator.create(Timer) catch return 0;
    timer.* = .{
        .id = self.next_timer_id,
        .callback = callback,
        .fire_time = self.platform.getCurrentTime() + actual_delay,
        .interval = null,
        .nesting_level = nesting_level,
        .is_cancelled = false,
    };
    self.next_timer_id += 1;

    self.pending_timers.add(timer);
    self.timer_ids.put(timer.id, timer);

    // 4. Update platform wake time
    self.updateWakeTime();

    return timer.id;
}

pub fn setInterval(
    self: *TimerManager,
    callback: TimerCallback,
    delay: i64,
    nesting_level: u32,
) u32 {
    // Same as setTimeout but with interval set
    // ...
}

pub fn clearTimeout(self: *TimerManager, id: u32) void {
    if (self.timer_ids.get(id)) |timer| {
        timer.is_cancelled = true;
        _ = self.timer_ids.remove(id);
    }
}

pub fn clearInterval(self: *TimerManager, id: u32) void {
    self.clearTimeout(id); // Same implementation
}

pub fn getNextWakeTime(self: *TimerManager) ?i64 {
    while (self.pending_timers.peek()) |timer| {
        if (timer.is_cancelled) {
            _ = self.pending_timers.remove();
            continue;
        }
        return timer.fire_time;
    }
    return null;
}

pub fn processReadyTimers(self: *TimerManager, now: i64, event_loop: *EventLoop) void {
    while (self.pending_timers.peek()) |timer| {
        if (timer.fire_time > now) break;
        _ = self.pending_timers.remove();

        if (timer.is_cancelled) {
            self.allocator.destroy(timer);
            continue;
        }

        // Queue task to event loop
        event_loop.queueTask(.timer, .{
            .callback = timer.callback,
            .nesting_level = timer.nesting_level + 1,
        });

        // Reschedule if interval
        if (timer.interval) |interval| {
            timer.fire_time = now + interval;
            self.pending_timers.add(timer);
        } else {
            _ = self.timer_ids.remove(timer.id);
            self.allocator.destroy(timer);
        }
    }
}
```

### Throttling (Chrome-style)
```zig
fn applyThrottling(self: *TimerManager, delay: i64) i64 {
    return switch (self.visibility_state) {
        .visible => delay, // No throttling
        .hidden => @max(delay, 1000), // 1 second minimum when hidden
        .hidden_long => @max(delay, 60000), // 1 minute for long-hidden
    };
}

pub const VisibilityState = enum {
    visible,
    hidden,
    hidden_long, // Hidden > 5 minutes
};
```

