pub const RealTimerBackend = struct {
    scheduled_wakeup: ?i64,

    pub fn init() RealTimerBackend {
        return .{ .scheduled_wakeup = null };
    }

    fn getCurrentTime(ptr: *anyopaque) i64 {
        _ = ptr;
        return std.time.milliTimestamp();
    }

    fn scheduleWakeup(ptr: *anyopaque, time: i64) void {
        const self = @ptrCast(*RealTimerBackend, @alignCast(@alignOf(RealTimerBackend), ptr));
        self.scheduled_wakeup = time;
    }

    fn cancelWakeup(ptr: *anyopaque) void {
        const self = @ptrCast(*RealTimerBackend, @alignCast(@alignOf(RealTimerBackend), ptr));
        self.scheduled_wakeup = null;
    }

    pub fn waitUntilWakeup(self: *RealTimerBackend) void {
        if (self.scheduled_wakeup) |wakeup| {
            const now = std.time.milliTimestamp();
            if (wakeup > now) {
                std.time.sleep(@intCast(u64, wakeup - now) * std.time.ns_per_ms);
            }
        }
    }

    pub const vtable = VTable{...};
    pub fn backend(self: *RealTimerBackend) PlatformTimerBackend {...}
};
```

