```zig
pub fn shouldBlockFetch(
    csp_list: *const CSPList,
    request: *const Request,
    destination: FetchDestination,
) CSPCheckResult {
    // 1. Determine directive based on destination
    const directive = getDirectiveForDestination(destination);

    // 2. Check each policy
    for (csp_list.policies) |policy| {
        const effective = fallback.getEffectiveDirective(policy, directive);
        if (effective) |sources| {
            if (!matching.doesUrlMatchSourceList(request.url, sources)) {
                return .{
                    .blocked = policy.disposition == .enforce,
                    .violated_policy = policy,
                };
            }
        }
    }

    return .{ .blocked = false };
}

fn getDirectiveForDestination(dest: FetchDestination) []const u8 {
    return switch (dest) {
        .script => "script-src",
        .style => "style-src",
        .image => "img-src",
        .font => "font-src",
        .media => "media-src",
        .object => "object-src",
        .frame, .iframe => "frame-src",
        .worker => "worker-src",
        .connect => "connect-src",
        else => "default-src",
    };
}
```

### Inline Script/Style Checking
```zig
pub fn shouldBlockInlineScript(
    csp_list: *const CSPList,
    script_content: []const u8,
    nonce: ?[]const u8,
    parser_inserted: bool,
) CSPCheckResult {
    for (csp_list.policies) |policy| {
        const sources = fallback.getEffectiveDirective(policy, "script-src");

        // Check nonce first
        if (nonce) |n| {
            if (matching.doesNonceMatch(sources, n)) continue;
        }

        // Check hash
        const hash = computeHash(script_content);
        if (matching.doesHashMatch(sources, hash)) continue;

        // Check 'unsafe-inline'
        if (matching.allowsUnsafeInline(sources)) {
            // But 'strict-dynamic' overrides
            if (!matching.hasStrictDynamic(sources)) continue;
        }

        // Check 'strict-dynamic' for parser-inserted
        if (matching.hasStrictDynamic(sources) and !parser_inserted) {
            continue; // Non-parser-inserted allowed with strict-dynamic
        }

        return .{
            .blocked = policy.disposition == .enforce,
            .violated_policy = policy,
        };
    }

    return .{ .blocked = false };
}

fn computeHash(content: []const u8) []const u8 {
    // SHA-256, SHA-384, or SHA-512
    var hasher = std.crypto.hash.sha2.Sha256.init(.{});
    hasher.update(content);
    const hash = hasher.finalResult();
    return std.base64.standard.encode(hash);
}
```

### eval() Blocking
```zig
pub fn shouldBlockEval(csp_list: *const CSPList) bool {
    for (csp_list.policies) |policy| {
        const sources = fallback.getEffectiveDirective(policy, "script-src");
        if (!matching.allowsUnsafeEval(sources)) {
            if (policy.disposition == .enforce) return true;
        }
    }
    return false;
}
```

