### document.write() Algorithm
```zig
pub fn documentWrite(
    document: *Document,
    args: []const []const u8,
) !void {
    // Per spec section 8.4.3.1

    // 1. If document is XML, throw InvalidStateError
    if (document.type == .xml) {
        return error.InvalidStateError;
    }

    // 2. If document is throw-on-dynamic-markup-insertion, throw
    if (document.throw_on_dynamic_markup_insertion) {
        return error.InvalidStateError;
    }

    // 3. If active document is not document, return
    // (cross-origin check)

    // 4. If insertion point is undefined:
    if (document.parser == null or document.parser.?.insertion_point == null) {
        // 4.1 If document unload counter > 0 or ignore-destructive-writes-counter > 0, return
        if (document.unload_counter > 0 or document.ignore_destructive_writes_counter > 0) {
            return;
        }

        // 4.2 Run document open steps
        try documentOpen(document, document.relevant_global_object, "", "");
    }

    // 5. Concatenate arguments
    var content = ArrayList(u8).init(document.allocator);
    defer content.deinit();
    for (args) |arg| {
        try content.appendSlice(arg);
    }

    // 6. Insert string into input stream at insertion point
    try document.parser.?.input_stream.insert(content.items);

    // 7. If no pending parsing-blocking script, process input
    if (document.pending_parsing_blocking_script == null) {
        // Resume parsing
        try document.parser.?.run();
    }
}
```

### document.writeln() Algorithm
```zig
pub fn documentWriteln(
    document: *Document,
    args: []const []const u8,
) !void {
    // Same as document.write(), but append "\n" to arguments
    var new_args = ArrayList([]const u8).init(document.allocator);
    defer new_args.deinit();

    for (args) |arg| {
        try new_args.append(arg);
    }
    try new_args.append("\n");

    return documentWrite(document, new_args.items);
}
```

### document.open() Algorithm
```zig
pub fn documentOpen(
    document: *Document,
    caller_global: *GlobalScope,
    unused1: []const u8,
    unused2: []const u8,
) !*Document {
    // Per spec section 8.4.3.2

    // 1. If document is XML, throw InvalidStateError
    if (document.type == .xml) {
        return error.InvalidStateError;
    }

    // 2. If throw-on-dynamic-markup-insertion, throw
    if (document.throw_on_dynamic_markup_insertion) {
        return error.InvalidStateError;
    }

    // 3. entry_document = caller's relevant document
    // 4. If active document != document, return document

    // 5. If document has active parser with script nesting > 0, return document
    if (document.parser) |parser| {
        if (parser.script_nesting_level > 0) {
            return document;
        }
    }

    // 6. If unload counter > 0, return document
    if (document.unload_counter > 0) {
        return document;
    }

    // 7. If active parser, abort and destroy it
    if (document.parser) |parser| {
        parser.abort();
        document.parser = null;
    }

    // 8. If document is the associated Document of its browsing context, clear
    // 9. Remove all children from document
    while (document.firstChild) |child| {
        document.removeChild(child);
    }

    // 10. If entry document's origin != document's origin, set to entry's origin
    // 11. Set document's URL to entry document's URL
    // 12. Unset document's reload override flag
    // 13. If caller's document's is initial about:blank, do nothing
    // 14. Otherwise:
    //     - Set document's is initial about:blank to false
    //     - Create new parser
    //     - Set insertion point to end of input stream

    document.parser = try HTMLParser.init(document.allocator, document);
    document.parser.?.insertion_point = .{
        .position = 0,
        .calling_script = null,
    };

    return document;
}
