pub fn documentClose(document: *Document) !void {
    // Per spec section 8.4.3.3

    // 1. If document is XML, throw InvalidStateError
    if (document.type == .xml) {
        return error.InvalidStateError;
    }

    // 2. If throw-on-dynamic-markup-insertion, throw
    if (document.throw_on_dynamic_markup_insertion) {
        return error.InvalidStateError;
    }

    // 3. If parser is null or can't change mode, return
    if (document.parser == null) return;

    // 4. Insert explicit EOF at insertion point
    document.parser.?.insertion_point = null; // End of stream

    // 5. If no pending parsing-blocking script:
    if (document.pending_parsing_blocking_script == null) {
        // Run the parser until EOF
        try document.parser.?.run();
    }
}
