### Error Reporter
```zig
pub const ParseErrorReporter = struct {
    allocator: Allocator,
    errors: ArrayList(ParseErrorInfo),
    callback: ?*const fn(ParseErrorInfo) void,

    // Position tracking
    line: u32 = 1,
    column: u32 = 0,

    pub fn init(allocator: Allocator) ParseErrorReporter {
        return .{
            .allocator = allocator,
            .errors = ArrayList(ParseErrorInfo).init(allocator),
            .callback = null,
        };
    }

    pub fn reportError(
        self: *ParseErrorReporter,
        error_type: ParseError,
        context: anytype,
    ) void {
        const info = ParseErrorInfo{
            .error_type = error_type,
            .line = self.line,
            .column = self.column,
            .token = context.token,
            .element = context.element,
            .attribute = context.attribute,
        };

        self.errors.append(info) catch {};

        if (self.callback) |cb| {
            cb(info);
        }
    }

    pub fn updatePosition(self: *ParseErrorReporter, char: u21) void {
        if (char == '\n') {
            self.line += 1;
            self.column = 0;
        } else {
            self.column += 1;
        }
    }
};
```

