# Implement DOMParser.parseFromString()

## Spec Reference
HTML Standard Section 8.4.4 "DOMParser"

## Location
`src/webidl/impls/DOMParser.zig` (complete existing stub)

## Requirements

### parseFromString Algorithm
```zig
pub fn call_parseFromString(
    instance: *runtime.Instance,
    string: runtime.DOMString,
    mime_type: enums.DOMParserSupportedType,
) anyerror!*runtime.Instance {
    const allocator = runtime.ArenaAllocator.get();

    return switch (mime_type) {
        .@"text/html" => try parseAsHTML(allocator, string),
        .@"text/xml",
        .@"application/xml",
        .@"application/xhtml+xml" => try parseAsXML(allocator, string),
        .@"image/svg+xml" => try parseAsSVG(allocator, string),
    };
}
```

### HTML Parsing Mode
```zig
fn parseAsHTML(allocator: Allocator, html: []const u8) !*runtime.Instance {
    // Per spec:
    // 1. Create new Document with type "html"
    const document = try HTMLDocument.create(allocator);

    // 2. Set content type to "text/html"
    document.content_type = "text/html";

    // 3. Create HTML parser for document
    var parser = try HTMLParser.init(allocator, document);

    // 4. Disable scripting (DOMParser never runs scripts)
    parser.scripting_flag = false;

    // 5. Parse the string
    parser.setInput(html);
    try parser.run();

    return document.as_instance;
}
```

### XML Parsing Mode
```zig
fn parseAsXML(allocator: Allocator, xml: []const u8) !*runtime.Instance {
    // Per spec:
    // 1. Parse as XML
    // 2. If parse error, return error document with <parsererror>

    const result = XMLParser.parse(allocator, xml);

    if (result.error) |err| {
        // Create error document
        const doc = try Document.create(allocator);
        const root = try doc.createElementNS(
            "http://www.mozilla.org/newlayout/xml/parsererror.xml",
            "parsererror"
        );
        try root.setTextContent(err.message);
        try doc.appendChild(root);
        return doc.as_instance;
    }

    return result.document.as_instance;
}
```

### SVG Parsing Mode
```zig
fn parseAsSVG(allocator: Allocator, svg: []const u8) !*runtime.Instance {
    // Parse as XML with SVG namespace
    // Mostly same as XML but document is SVG type
}
```

