    fn isElementRendered(_: *anyopaque, _: *Element) bool {
        return true; // Assume everything is rendered
    }

    fn getComputedStyle(_: *anyopaque, _: *Element, _: ?[]const u8) *CSSStyleDeclaration {
        // Return empty style declaration
        return &empty_style;
    }

