/// A V8 Local handle that is only valid within current HandleScope.
/// This type is designed to prevent accidental storage.
pub const LocalValue = struct {
    ptr: *ffi.Value,

    /// Get the raw pointer for FFI calls \(use immediately, don't store\!\)
    pub fn rawPtr\(self: LocalValue\) *ffi.Value {
        return self.ptr\;
