    /// Convert to a GlobalHandle for storage
    pub fn toGlobal\(self: LocalValue, isolate: *ffi.Isolate\) ?GlobalHandle {
        return GlobalHandle.create\(isolate, @ptrCast\(self.ptr\)\)\;
    }
}\;
