/// @param list: Existing list (or null to create new)
/// @param string: String to append (copied internally)
/// Returns: New list head or null on failure
/// Reference: https://curl.se/libcurl/c/curl_slist_append.html
pub extern fn curl_slist_append(list: ?*curl_slist, string: [*:0]const u8) ?*curl_slist;
```

### curl_slist_free_all
```zig
/// Free entire curl_slist
/// @param list: List to free
/// Reference: https://curl.se/libcurl/c/curl_slist_free_all.html
pub extern fn curl_slist_free_all(list: ?*curl_slist) void;
```

## Types to Add (if not already present)

```zig
/// Linked list node for strings
pub const curl_slist = extern struct {
    data: [*:0]u8,
    next: ?*curl_slist,
};
```

## Helper Functions to Add (Zig wrapper)

```zig
/// Iterator for curl_slist
pub const SlistIterator = struct {
    current: ?*curl_slist,

    pub fn next(self: *SlistIterator) ?[*:0]const u8 {
        if (self.current) |node| {
            const data = node.data;
            self.current = node.next;
            return data;
        }
        return null;
    }
};

/// Create iterator from slist
pub fn slistIterator(list: ?*curl_slist) SlistIterator {
    return .{ .current = list };
}

/// Count items in slist
pub fn slistCount(list: ?*curl_slist) usize {
    var count: usize = 0;
    var current = list;
    while (current) |node| {
        count += 1;
        current = node.next;
    }
    return count;
}
```

## Cookie String Format (Netscape)
When reading cookies via CURLINFO_COOKIELIST, each string is tab-separated:
```
.example.com	TRUE	/	FALSE	0	session_id	abc123
^domain       ^flag  ^path ^secure ^expiry ^name    ^value
```

Fields:
1. domain - Cookie domain (leading dot = include subdomains)
2. flag - TRUE if domain has leading dot (include subdomains)
3. path - Cookie path
4. secure - TRUE if HTTPS only
5. expiry - Unix timestamp (0 = session cookie)
6. name - Cookie name
7. value - Cookie value

