//! WHATWG TestUtils spec: https://testutils.spec.whatwg.org/
//!
//! This module provides testing APIs for browser implementations.
//! It is intended for use by test suites like web-platform-tests,
//! NOT for production applications.
//!
//! ## Availability
//!
//! This module is ONLY available when built with `-Denable-test-utils=true`.
//! It must NOT be enabled in production/shipping builds.
//!
//! ## API
//!
//! - `TestUtils.gc()` - Trigger garbage collection, returns Promise<undefined>
//!
//! ## Usage
//!
//! ```zig
//! const testutils = @import("testutils");
//!
//! // From WebIDL implementation:
//! pub fn call_gc(ctx: runtime.Context) !*anyopaque {
//!     return testutils.performGC(ctx);
//! }
//! ```
//!
//! ## Specification
//!
//! Per WHATWG TestUtils Standard:
//! > The interfaces defined in this specification must not be enabled in the
//! > default shipping configuration of user agents. They must only be enabled
//! > in testing configurations.

const std = @import("std");
const runtime = @import("runtime");

// Sub-modules
pub const gc_mod = @import("gc.zig");
pub const context_mod = @import("context.zig");

// Re-export key types
pub const GCThread = gc_mod.GCThread;
pub const GCRequest = gc_mod.GCRequest;
pub const ExposureError = context_mod.ExposureError;

/// TestUtils.gc() - Trigger garbage collection
///
/// Per WHATWG TestUtils spec:
/// 1. Let p be a new promise.
/// 2. Run the following in parallel:
///    2.1. Run implementation-defined steps to perform a garbage collection
///         covering at least the entry Realm.
///    2.2. Resolve p.
///
/// ## Arguments
/// - ctx: Runtime context with engine and realm info
///
/// ## Returns
/// Opaque pointer to Promise object (to be returned to JavaScript)
///
/// ## Errors
/// - ExposureError.NotExposedInContext: Called from wrong context type
/// - EngineError.NoEngine: No JS engine configured
/// - EngineError.PromiseError: Failed to create Promise
///
/// ## Example
/// ```zig
/// // In WebIDL impl:
/// pub fn call_gc(ctx: runtime.Context) !*const anyopaque {
///     return testutils.performGC(ctx);
/// }
/// ```
pub fn performGC(ctx: runtime.Context) !*anyopaque {
    // Step 0: Validate context exposure
    // TestUtils is [Exposed=(Window,Worker)]
    try context_mod.validateExposure(ctx, .window_and_worker);

    // Steps 1-2: Create promise and run GC in parallel
    return gc_mod.requestGarbageCollection(ctx);
}

/// Check if TestUtils is available in the current context
///
/// Returns true if:
/// - Context is Window or Worker (per [Exposed] attribute)
/// - Engine is configured (GC requires engine)
pub fn isAvailable(ctx: runtime.Context) bool {
    // Check exposure
    if (!ctx.realm_info.isExposedTo(.window_and_worker)) {
        return false;
    }

    // Check engine
    if (ctx.getEngine() == null) {
        return false;
    }

    return true;
}

