pub fn init(allocator: Allocator, options: Options) !*WebSocketCurlBackend {
    const self = try allocator.create(WebSocketCurlBackend);
    errdefer allocator.destroy(self);

    // ... existing init ...

    // Get global cookie manager
    const curl_cookies = @import("../fetch/network/curl_cookies.zig");
