### 4. Handle credentials Mode
```zig
/// Per Fetch spec: credentials mode affects cookie behavior
/// - "omit": Don't send or receive cookies
/// - "same-origin": Send cookies for same-origin requests only
/// - "include": Always send cookies
fn configureCookiesForRequest(
    self: *CurlBackend,
    handle: *curl.CURL,
    request: *Request,
) !void {
    if (self.cookie_manager == null) return;

    switch (request.credentials) {
        .omit => {
            // Don't use cookies for this request
            // Note: We still use the shared handle but disable cookie sending
            _ = curl.curl_easy_setopt(handle, curl.CURLOPT_COOKIE, "");
        },
        .same_origin => {
            // Check if request is same-origin
            if (isSameOrigin(request.url, self.document_origin)) {
                self.cookie_manager.?.attachToHandle(handle);
            }
        },
        .include => {
            // Always use cookies
            self.cookie_manager.?.attachToHandle(handle);
        },
    }
}

fn isSameOrigin(request_url: []const u8, document_origin: ?[]const u8) bool {
    if (document_origin == null) return false;

    const url = @import("url");
    const request_parsed = url.URL.parse(std.heap.page_allocator, request_url) catch return false;
    defer request_parsed.deinit();

    const doc_parsed = url.URL.parse(std.heap.page_allocator, document_origin.?) catch return false;
    defer doc_parsed.deinit();

    // Same origin = same scheme + host + port
    return std.mem.eql(u8, request_parsed.scheme, doc_parsed.scheme) and
           std.mem.eql(u8, request_parsed.host.?.domain, doc_parsed.host.?.domain) and
           request_parsed.port == doc_parsed.port;
}
```

