/// Collect an HTTP quoted string from input starting at position.
/// 
/// Algorithm:
/// 1. Assert: code point at position is U+0022 (")
/// 2. Advance position by 1
/// 3. While true:
///    a. Append chars that are not " or \\ to value
///    b. If position past end, break
///    c. If char is \\:
///       - If next position past end, append \\ and break
///       - Else append next char, advance by 1
///    d. If char is ", break
/// 4. Return value (or full quoted string if extract-value is false)
///
/// @param extract_value - if true, return inner value; if false, return with quotes
pub fn collectHttpQuotedString(
    input: []const u8, 
    position: *usize, 
    extract_value: bool
) []const u8
```

