## set() Method

```zig
/// Set a cookie in the cookie store
///
/// Per CookieStore API spec:
/// 1. If name starts with "__Secure-" or "__Host-", enforce secure context
/// 2. If name starts with "__Host-", enforce domain=null and path="/"
/// 3. Validate name and value don't contain forbidden characters
///
/// @param options: Cookie options
/// @param context_url: The URL of the context setting the cookie (for defaults)
pub fn set(
    self: *CurlCookieManager,
    options: CookieInit,
    context_url: ?[]const u8,
) !void {
    // Validate cookie name (RFC 6265 Section 4.1.1)
    if (!isValidCookieName(options.name)) {
        return error.InvalidCookieName;
    }

    // Validate cookie value (RFC 6265 Section 4.1.1)
    if (!isValidCookieValue(options.value)) {
        return error.InvalidCookieValue;
    }

    // Handle __Secure- prefix
    if (std.mem.startsWith(u8, options.name, "__Secure-")) {
        if (options.secure != null and !options.secure.?) {
            return error.SecurePrefixRequiresSecure;
        }
        // Force secure=true
    }

    // Handle __Host- prefix
    if (std.mem.startsWith(u8, options.name, "__Host-")) {
        if (options.domain != null) {
            return error.HostPrefixNoDomain;
        }
        if (options.path != null and !std.mem.eql(u8, options.path.?, "/")) {
            return error.HostPrefixRootPath;
        }
        // Force secure=true, domain=null, path="/"
    }

    // Determine effective domain
    const effective_domain = options.domain orelse blk: {
        if (context_url) |url| {
            const parsed = try parseUrlForMatching(url);
            break :blk parsed.host;
        }
        break :blk "";
    };

    // Determine effective path
    const effective_path = options.path orelse "/";

    // Determine effective secure flag
    const effective_secure = options.secure orelse blk: {
        if (std.mem.startsWith(u8, options.name, "__Secure-") or
            std.mem.startsWith(u8, options.name, "__Host-")) {
            break :blk true;
        }
        if (context_url) |url| {
            const parsed = try parseUrlForMatching(url);
            break :blk parsed.is_secure;
        }
        break :blk false;
    };

    // Build cookie for libcurl
    const cookie = Cookie{
        .name = options.name,
        .value = options.value,
        .domain = effective_domain,
        .path = effective_path,
        .expires = options.expires,
        .secure = effective_secure,
        .same_site = options.same_site orelse .lax,
        .http_only = false,
        .allocator = self.allocator,
    };

    // Format as Set-Cookie string
    const cookie_str = try formatSetCookieString(self.allocator, cookie);
    defer self.allocator.free(cookie_str);

    // Add null terminator for C string
    const cookie_cstr = try self.allocator.dupeZ(u8, cookie_str);
    defer self.allocator.free(cookie_cstr);

    // Set cookie via libcurl
    self.mutex.lock();
    defer self.mutex.unlock();

    const result = curl.curl_easy_setopt(
        self.cookie_handle,
        curl.CURLOPT_COOKIELIST,
        cookie_cstr.ptr,
    );

    if (result != curl.CURLE_OK) {
        return error.SetCookieFailed;
    }
}

/// Convenience method: set cookie by name and value only
pub fn setSimple(
    self: *CurlCookieManager,
    name: []const u8,
    value: []const u8,
    context_url: ?[]const u8,
) !void {
    return self.set(.{ .name = name, .value = value }, context_url);
}
```

## Validation Helpers

```zig
/// Validate cookie name per RFC 6265 Section 4.1.1
/// cookie-name = token
/// token = 1*<any CHAR except CTLs or separators>
/// separators = "(" | ")" | "<" | ">" | "@" | "," | ";" | ":" | "\" | <"> | "/" | "[" | "]" | "?" | "=" | "{" | "}" | SP | HT
fn isValidCookieName(name: []const u8) bool {
    if (name.len == 0) return false;

    for (name) |c| {
        // CTLs (0-31, 127)
        if (c <= 31 or c == 127) return false;

        // Separators
        switch (c) {
            '(', ')', '<', '>', '@', ',', ';', ':', '\\', '"',
            '/', '[', ']', '?', '=', '{', '}', ' ', '\t' => return false,
            else => {},
        }
    }

    return true;
}

/// Validate cookie value per RFC 6265 Section 4.1.1
/// cookie-value = *cookie-octet / ( DQUOTE *cookie-octet DQUOTE )
/// cookie-octet = %x21 / %x23-2B / %x2D-3A / %x3C-5B / %x5D-7E
fn isValidCookieValue(value: []const u8) bool {
    // Empty value is valid
    if (value.len == 0) return true;

    // Check for quoted value
    var check_value = value;
    if (value.len >= 2 and value[0] == '"' and value[value.len - 1] == '"') {
        check_value = value[1 .. value.len - 1];
    }

    for (check_value) |c| {
        // Valid cookie-octet ranges
        const valid = (c == 0x21) or
            (c >= 0x23 and c <= 0x2B) or
            (c >= 0x2D and c <= 0x3A) or
            (c >= 0x3C and c <= 0x5B) or
            (c >= 0x5D and c <= 0x7E);

        if (!valid) return false;
    }

    return true;
}
```

